window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["国家网信办"] = {"gerenxinxibaohuheguishenjiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范个人信息保护合规审计活动，保护个人信息权益，根据《中华人民共和国个人信息保护法》、《网络数据安全管理条例》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内开展个人信息保护合规审计，适用本办法。 本办法所称个人信息保护合规审计，是指对个人信息处理者的个人信息处理活动是否遵守法律、行政法规的情况进行审查和评价的监督活动。"},{"i":3,"n":"第三条","txt":"个人信息处理者自行开展个人信息保护合规审计的，应当由个人信息处理者内部机构或者委托专业机构定期对其处理个人信息遵守法律、行政法规的情况进行合规审计。"},{"i":4,"n":"第四条","txt":"处理超过1000万人个人信息的个人信息处理者，应当每两年至少开展一次个人信息保护合规审计。"},{"i":5,"n":"第五条","txt":"个人信息处理者有以下情形之一的，国家网信部门和其他履行个人信息保护职责的部门（以下统称为保护部门），可以要求个人信息处理者委托专业机构对个人信息处理活动进行合规审计： （一）发现个人信息处理活动存在严重影响个人权益或者严重缺乏安全措施等较大风险的； （二）个人信息处理活动可能侵害众多个人的权益的； （三）发生个人信息安全事件，导致100万人以上个人信息或者10万人以上敏感个人信息泄露、篡改、丢失、毁损的。 对同一个人信息安全事件或者风险，不得重复要求个人信息处理者委托专业机构开展个人信息保护合规审计。"},{"i":6,"n":"第六条","txt":"个人信息处理者自行开展或者按照保护部门要求委托专业机构开展个人信息保护合规审计的，应当参照本办法附件《个人信息保护合规审计指引》。"},{"i":7,"n":"第七条","txt":"专业机构应当具备开展个人信息保护合规审计的能力，有与服务相适应的审计人员、场所、设施和资金等。 鼓励相关专业机构通过认证。专业机构的认证按照《中华人民共和国认证认可条例》的有关规定执行。"},{"i":8,"n":"第八条","txt":"个人信息处理者按照保护部门要求开展个人信息保护合规审计的，应当为专业机构正常开展个人信息保护合规审计工作提供必要支持，并承担审计费用。"},{"i":9,"n":"第九条","txt":"个人信息处理者按照保护部门要求开展个人信息保护合规审计的，应当按照保护部门要求选定专业机构，在限定时间内完成个人信息保护合规审计；情况复杂的，报保护部门批准后，可以适当延长。"},{"i":10,"n":"第十条","txt":"个人信息处理者按照保护部门要求开展个人信息保护合规审计的，在完成合规审计后，应当将专业机构出具的个人信息保护合规审计报告报送保护部门。 个人信息保护合规审计报告应当由专业机构主要负责人、合规审计负责人签字并加盖专业机构公章。"},{"i":11,"n":"第十一条","txt":"个人信息处理者按照保护部门要求开展个人信息保护合规审计的，应当按照保护部门要求对合规审计中发现的问题进行整改。在整改完成后15个工作日内，向保护部门报送整改情况报告。"},{"i":12,"n":"第十二条","txt":"处理100万人以上个人信息的个人信息处理者应当指定个人信息保护负责人，负责个人信息处理者的个人信息保护合规审计工作。 提供重要互联网平台服务、用户数量巨大、业务类型复杂的个人信息处理者，应当成立主要由外部成员组成的独立机构对个人信息保护合规审计情况进行监督。"},{"i":13,"n":"第十三条","txt":"专业机构在从事个人信息保护合规审计活动时，应当遵守法律法规，诚信正直，公正客观地作出合规审计职业判断，对在履行个人信息保护合规审计职责中获得的个人信息、商业秘密、保密商务信息等应当依法予以保密，不得泄露或者非法向他人提供，在合规审计工作结束后及时删除相关信息。"},{"i":14,"n":"第十四条","txt":"专业机构不得转委托其他机构开展个人信息保护合规审计。"},{"i":15,"n":"第十五条","txt":"同一专业机构及其关联机构、同一合规审计负责人不得连续三次以上对同一审计对象开展个人信息保护合规审计。"},{"i":16,"n":"第十六条","txt":"保护部门对个人信息处理者开展个人信息保护合规审计情况进行监督检查。"},{"i":17,"n":"第十七条","txt":"任何组织、个人有权对个人信息保护合规审计中的违法活动向保护部门进行投诉、举报。收到投诉、举报的部门应当依法及时处理，并将处理结果告知投诉、举报人。"},{"i":18,"n":"第十八条","txt":"个人信息处理者、专业机构违反本办法规定的，依照《中华人民共和国个人信息保护法》、《网络数据安全管理条例》等法律法规的规定处理；构成犯罪的，依法追究刑事责任。"},{"i":19,"n":"第十九条","txt":"对国家机关和法律、法规授权的具有管理公共事务职能的组织的个人信息保护合规审计，不适用本办法。"},{"i":20,"n":"第二十条","txt":"本办法自2025年5月1日起施行。 附件 个人信息保护合规审计指引 一、本指引根据《中华人民共和国个人信息保护法》、《网络数据安全管理条例》等法律、行政法规制定。 二、对个人信息处理活动的合法性基础进行合规审计的，应当重点审查下列事项： （一）基于个人同意处理个人信息的，是否取得个人同意，该同意是否由个人在充分知情的前提下自愿、明确作出； （二）基于个人同意处理个人信息的，个人信息的处理目的、处理方式、处理的个人信息种类发生变更的，是否重新取得个人同意； （三）基于个人同意处理个人信息的，是否依照法律、行政法规取得个人单独同意或者书面同意； （四）处理个人信息未取得个人同意的，是否属于法律、行政法规规定不需要取得个人同意的情形。 三、对个人信息处理规则进行合规审计的，应当重点审查下列事项： （一）是否真实、准确、完整地告知个人信息处理者的名称或者姓名和联系方式； （二）是否以清单等便于"}],"gerenxinxichujingbiaozhunhetongbanfa":[{"i":1,"n":"第一条","txt":"为了保护个人信息权益，规范个人信息出境活动，根据《中华人民共和国个人信息保护法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"个人信息处理者通过与境外接收方订立个人信息出境标准合同（以下简称标准合同）的方式向中华人民共和国境外提供个人信息，适用本办法。"},{"i":3,"n":"第三条","txt":"通过订立标准合同的方式开展个人信息出境活动，应当坚持自主缔约与备案管理相结合、保护权益与防范风险相结合，保障个人信息跨境安全、自由流动。"},{"i":4,"n":"第四条","txt":"个人信息处理者通过订立标准合同的方式向境外提供个人信息的，应当同时符合下列情形： （一）非关键信息基础设施运营者； （二）处理个人信息不满100万人的； （三）自上年1月1日起累计向境外提供个人信息不满10万人的； （四）自上年1月1日起累计向境外提供敏感个人信息不满1万人的。 法律、行政法规或者国家网信部门另有规定的，从其规定。 个人信息处理者不得采取数量拆分等手段，将依法应当通过出境安全评估的个人信息通过订立标准合同的方式向境外提供。"},{"i":5,"n":"第五条","txt":"个人信息处理者向境外提供个人信息前，应当开展个人信息保护影响评估，重点评估以下内容： （一）个人信息处理者和境外接收方处理个人信息的目的、范围、方式等的合法性、正当性、必要性； （二）出境个人信息的规模、范围、种类、敏感程度，个人信息出境可能对个人信息权益带来的风险； （三）境外接收方承诺承担的义务，以及履行义务的管理和技术措施、能力等能否保障出境个人信息的安全； （四）个人信息出境后遭到篡改、破坏、泄露、丢失、非法利用等的风险，个人信息权益维护的渠道是否通畅等； （五）境外接收方所在国家或者地区的个人信息保护政策和法规对标准合同履行的影响； （六）其他可能影响个人信息出境安全的事项。"},{"i":6,"n":"第六条","txt":"标准合同应当严格按照本办法附件订立。国家网信部门可以根据实际情况对附件进行调整。 个人信息处理者可以与境外接收方约定其他条款，但不得与标准合同相冲突。 标准合同生效后方可开展个人信息出境活动。"},{"i":7,"n":"第七条","txt":"个人信息处理者应当在标准合同生效之日起10个工作日内向所在地省级网信部门备案。备案应当提交以下材料： （一）标准合同； （二）个人信息保护影响评估报告。 个人信息处理者应当对所备案材料的真实性负责。"},{"i":8,"n":"第八条","txt":"在标准合同有效期内出现下列情形之一的，个人信息处理者应当重新开展个人信息保护影响评估，补充或者重新订立标准合同，并履行相应备案手续： （一）向境外提供个人信息的目的、范围、种类、敏感程度、方式、保存地点或者境外接收方处理个人信息的用途、方式发生变化，或者延长个人信息境外保存期限的； （二）境外接收方所在国家或者地区的个人信息保护政策和法规发生变化等可能影响个人信息权益的； （三）可能影响个人信息权益的其他情形。"},{"i":9,"n":"第九条","txt":"网信部门及其工作人员对在履行职责中知悉的个人隐私、个人信息、商业秘密、保密商务信息等应当依法予以保密，不得泄露或者非法向他人提供、非法使用。"},{"i":10,"n":"第十条","txt":"任何组织和个人发现个人信息处理者违反本办法向境外提供个人信息的，可以向省级以上网信部门举报。"},{"i":11,"n":"第十一条","txt":"省级以上网信部门发现个人信息出境活动存在较大风险或者发生个人信息安全事件的，可以依法对个人信息处理者进行约谈。个人信息处理者应当按照要求整改，消除隐患。"},{"i":12,"n":"第十二条","txt":"违反本办法规定的，依据《中华人民共和国个人信息保护法》等法律法规处理；构成犯罪的，依法追究刑事责任。"},{"i":13,"n":"第十三条","txt":"本办法自2023年6月1日起施行。本办法施行前已经开展的个人信息出境活动，不符合本办法规定的，应当自本办法施行之日起6个月内完成整改。 附件：个人信息出境标准合同.pdf"}],"hulianwangxinxineirongguanlixingzhengzhifachengxug6d3fcf":[{"i":1,"n":"第一条","txt":"为了规范和保障互联网信息内容管理部门依法履行职责，保护公民、法人和其他组织的合法权益，维护国家安全和公共利益，根据《中华人民共和国行政处罚法》《中华人民共和国网络安全法》和《国务院关于授权国家互联网信息办公室负责互联网信息内容管理工作的通知》，制定本规定。"},{"i":2,"n":"第二条","txt":"互联网信息内容管理部门依法实施行政执法，对违反有关互联网信息内容管理法律法规规章的行为实施行政处罚，适用本规定。 本规定所称互联网信息内容管理部门，是指国家互联网信息办公室和地方互联网信息办公室。"},{"i":3,"n":"第三条","txt":"互联网信息内容管理部门实施行政执法，应当遵循公开、公平、公正的原则，做到事实清楚、证据确凿、程序合法、法律法规规章适用准确适当、执法文书使用规范。"},{"i":4,"n":"第四条","txt":"互联网信息内容管理部门建立行政执法督查制度。 上级互联网信息内容管理部门对下级互联网信息内容管理部门实施的行政执法进行督查。"},{"i":5,"n":"第五条","txt":"互联网信息内容管理部门应当加强执法队伍建设，建立健全执法人员培训、考试考核、资格管理和持证上岗制度。 执法人员应当参加互联网信息内容管理部门组织的法律知识和业务知识培训，并经行政执法资格考试或者考核合格，取得执法证后方可从事执法工作。 执法证由国家互联网信息内容管理部门统一制定、核发或者授权省、自治区、直辖市互联网信息内容管理部门核发。"},{"i":6,"n":"第六条","txt":"行政处罚由违法行为发生地的互联网信息内容管理部门管辖。 违法行为发生地包括实施违法行为的网站备案地，工商登记地（工商登记地与主营业地不一致的，应按主营业地），网站建立者、管理者、使用者所在地，网络接入地，计算机等终端设备所在地等。"},{"i":7,"n":"第七条","txt":"市（地、州）级以下互联网信息内容管理部门依职权管辖本行政区域内的互联网信息内容行政处罚案件。 省、自治区、直辖市互联网信息内容管理部门依职权管辖本行政区域内重大、复杂的互联网信息内容行政处罚案件。 国家互联网信息内容管理部门依职权管辖应当由自己实施行政处罚的案件及全国范围内发生的重大、复杂的互联网信息内容行政处罚案件。 省、自治区、直辖市互联网信息内容管理部门可以依据法律法规规章，结合本地区实际，制定本行政区域内级别管辖的具体规定。"},{"i":8,"n":"第八条","txt":"对当事人的同一违法行为，两个以上互联网信息内容管理部门均有管辖权的，由先行立案的互联网信息内容管理部门管辖。必要时，可以移送主要违法行为发生地的互联网信息内容管理部门管辖。 两个以上的互联网信息内容管理部门对管辖权有争议的，应当协商解决；协商不成的，报请共同的上一级互联网信息内容管理部门指定管辖。"},{"i":9,"n":"第九条","txt":"上级互联网信息内容管理部门认为必要时，可以直接办理下级互联网信息内容管理部门管辖的案件，也可以将自己管辖的案件移交下级互联网信息内容管理部门办理。 下级互联网信息内容管理部门对其管辖的案件由于特殊原因不能行使管辖权的，可以报请上级互联网信息内容管理部门管辖或者指定管辖。"},{"i":10,"n":"第十条","txt":"互联网信息内容管理部门发现案件不属于其管辖的，应当及时移送有管辖权的互联网信息内容管理部门。 受移送的互联网信息内容管理部门应当将案件查处结果及时函告移送案件的互联网信息内容管理部门；认为移送不当的，应当报请共同的上一级互联网信息内容管理部门指定管辖，不得再次移送。"},{"i":11,"n":"第十一条","txt":"上级互联网信息内容管理部门接到管辖争议或者报请指定管辖请示后，应当在十个工作日内作出指定管辖的决定，并书面通知下级互联网信息内容管理部门。"},{"i":12,"n":"第十二条","txt":"互联网信息内容管理部门发现案件属于其他行政机关管辖的，应当依法移送有关机关。 互联网信息内容管理部门发现违法行为涉嫌犯罪的，应当及时移送司法机关。司法机关决定立案的，互联网信息内容管理部门应当自接到司法机关立案通知书之日起三日内将与案件有关的材料移交司法机关，并办结交接手续。"},{"i":13,"n":"第十三条","txt":"互联网信息内容管理部门对依法应当撤销互联网新闻信息服务许可、吊销互联网新闻信息服务许可证的，应当提出处理建议，并将取得的证据及相关材料报送原发证的互联网信息内容管理部门，由原发证的互联网信息内容管理部门依法作出是否撤销许可、吊销许可证的决定。"},{"i":14,"n":"第十四条","txt":"互联网信息内容管理部门应当对下列事项及时调查处理, 并填写《案件来源登记表》（格式见附件1）： （一）在监督检查中发现案件线索的； （二）自然人、法人或者其他组织投诉、申诉、举报的; （三）上级机关交办或者下级机关报请查处的； （四）有关部门移送或者经由其他方式、途径发现的。"},{"i":15,"n":"第十五条","txt":"行政处罚立案应当符合下列条件： （一）有涉嫌违法的事实； （二）依法应当予以行政处罚； （三）属于互联网信息内容监督管理行政处罚的范围； （四）属于本互联网信息内容管理部门管辖。 符合立案条件的，应当填写《立案审批表》（格式见附件2），同时附上相关材料，在七个工作日内报互联网信息内容管理部门负责人批准立案，并确定两名以上执法人员为案件承办人。特殊情况下，可以延长至十五个工作日内立案。"},{"i":16,"n":"第十六条","txt":"对于不予立案的投诉、申诉、举报，经互联网信息内容管理部门负责人批准后，应将结果告知具名的投诉人、申诉人、举报人，并将不予立案的相关情况作书面记录留存。 对于其他部门移送的案件，决定不予立案的，应当书面告知移送部门。 不予立案或者撤销立案的，承办人应当制作《不予立案审批表》（格式见附件3）或者《撤销立案审批表》（格式见附件4），报互联网信息内容管理部门负责人批准。"},{"i":17,"n":"第十七条","txt":"办案人员有下列情形之一的，应当自行回避；当事人也有权申请办案人员回避： （一）是本案的当事人或者当事人的近亲属； （二）与本案有直接利害关系； （三）与本案当事人有其他关系，可能影响案件公正处理。 办案人员的回避由互联网信息内容管理部门负责人决定。当事人对决定不服的，可以申请复议一次。 回避决定作出前，被申请回避人员不停止对案件的调查处理。"},{"i":18,"n":"第十八条","txt":"互联网信息内容管理部门进行案件调查取证时，执法人员不得少于两人，并应当出示执法证。必要时，也可以聘请专业人员进行协助。 首次向案件当事人收集、调取证据的，应当告知其有申请办案人员回避的权利。 向有关单位、个人收集、调取证据时，应当告知其有如实提供证据的义务。被调查对象或者有关人员应当如实回答询问并协助、配合调查，及时提供依法应当保存的互联网信息服务提供者发布的信息、用户发布的信息、日志信息等相关材料，不得阻挠、干扰案件的调查。 执法人员对在办案过程中知悉的国家秘密、商业秘密、个人隐私、个人信息应当依法保密。"},{"i":19,"n":"第十九条","txt":"互联网信息内容管理部门在办案过程中需要其他地区互联网信息内容管理部门协助调查、取证的，应当出具委托调查函。受委托的互联网信息内容管理部门应当积极予以协助，一般应当在接到委托调查函之日起十五个工作日内完成相关工作；需要延期完成或者无法协助的，应当及时函告委托的互联网信息内容管理部门。"},{"i":20,"n":"第二十条","txt":"办案人员应当依法收集与案件有关的证据，包括电子数据、视听资料、书证、物证、证人证言、当事人的陈述、鉴定意见、检验报告、勘验笔录、现场笔录、询问笔录等。 电子数据是指案件发生过程中形成的，以数字化形式存储、处理、传输的，能够证明案件事实的数据，包括但不限于网页、博客、微博客、即时通信工具、论坛、贴吧、网盘、电子邮件、网络后台等方式承载的电子信息或文件。电子数据主要存在于计算机设备、移动通信设备、互联网服务器、移动存储设备、云存储系统等电子设备或存储介质中。 视听资料包括录音资料和影像资料。 存储在电子介质中的录音资料和影像资料，适用电子数据的规定。"},{"i":21,"n":"第二十一条","txt":"互联网信息内容管理部门在立案前调查或者检查过程中依法取得的证据，可以作为认定事实的依据。通过网络巡查等技术手段获取的、具有可靠性的电子数据可以作为认定事实的依据。 电子数据的收集、提取应当符合法律法规规章、国家标准、行业标准和技术规范，并保证所收集、提取的电子数据的完整性、合法性、真实性、关联性。否则，不得作为认定事实的依据。"},{"i":22,"n":"第二十二条","txt":"互联网信息内容管理部门在立案前，可以采取询问、勘验、检查、鉴定、调取证据材料等措施，不得限制初查对象的人身、财产权利。 互联网信息内容管理部门在立案后，可以对物品、设施、场所采取先行登记保存等措施。"},{"i":23,"n":"第二十三条","txt":"互联网信息内容管理部门在办案过程中，应当及时询问证人。 执法人员进行询问的，应当制作《询问笔录》（格式见附件5），载明时间、地点、有关事实、经过等内容。询问笔录应当交询问对象或者有关人员核对并确认。"},{"i":24,"n":"第二十四条","txt":"互联网信息内容管理部门对于涉及互联网信息内容违法的场所、物品、网络应当进行勘验、检查，及时收集、固定书证、物证、视听资料以及电子数据。"},{"i":25,"n":"第二十五条","txt":"互联网信息内容管理部门可以委托司法鉴定机构就案件中的专门性问题出具鉴定意见；不属于司法鉴定范围的，可以委托有能力或者条件的机构出具检测报告或者检验报告。"},{"i":26,"n":"第二十六条","txt":"互联网信息内容管理部门可以向有关单位、个人调取能够证明案件事实的证据材料，并且可以根据需要拍照、录像、复印和复制。 调取的书证、物证应当是原件、原物。调取原件、原物确有困难的，可以由提交证据的有关单位、个人在复制品上签字或者盖章，注明“此件由×××提供，经核对与原件（物）无异”的字样或者文字说明，并注明出证日期、证据出处，并签名或者盖章。 调取的视听资料、电子数据应当是原始载体或备份介质。调取原始载体或备份介质确有困难的，可以收集复制件，并注明制作方法、制作时间、制作人等情况。调取声音资料的应当附有该声音内容的文字记录。"},{"i":27,"n":"第二十七条","txt":"在证据可能灭失或者以后难以取得的情况下，经互联网信息内容管理部门负责人批准，执法人员可以依法对涉案计算机、服务器、硬盘、移动存储设备、存储卡等涉嫌实施违法行为的物品先行登记保存，制作《登记保存物品清单》（格式见附件6），向当事人出具《登记保存物品通知书》（格式见附件7）。先行登记保存期间，当事人或有关人员不得损毁、销毁或者非法转移证据。 互联网信息内容管理部门实施先行登记保存时，应当通知当事人或者持有人到场，并在现场笔录中对采取的相关措施情况予以记载。"},{"i":28,"n":"第二十八条","txt":"互联网信息内容管理部门对先行登记保存的证据，应当在七日内作出以下处理决定： （一）需要采取证据保全措施的，采取记录、复制、拍照、录像等证据保全措施后予以返还； （二）需要检验、检测、鉴定的，送交具有相应资质的机构检验、检测、鉴定； （三）违法事实成立的，依法应当予以没收的，作出行政处罚决定，没收违法物品； （四）违法事实不成立，或者违法事实成立但依法不应当予以没收的，解除先行登记保存。 逾期未作出处理决定的，应当解除先行登记保存。"},{"i":29,"n":"第二十九条","txt":"为了收集、保全电子数据，互联网信息内容管理部门可以采取现场取证，远程取证，责令有关单位、个人固定和提交等措施。 现场取证、远程取证结束后应当制作《电子取证工作记录》（格式见附件8）。"},{"i":30,"n":"第三十条","txt":"执法人员在调查取证过程中，应当要求当事人在笔录或者其他材料上签字、捺指印、盖章或者以其他方式确认。当事人拒绝到场，拒绝签字、捺指印、盖章或者以其他方式确认，或者无法找到当事人的，应当由两名执法人员在笔录或者其他材料上注明原因，并邀请有关人员作为见证人签字或者盖章，也可以采取录音、录像等方式记录。"},{"i":31,"n":"第三十一条","txt":"案件调查终结后，承办人应当撰写《案件处理意见报告》（格式见附件9）： 认为违法事实成立，应当予以行政处罚的，撰写《案件处理意见报告》，草拟行政处罚建议书。 有下列情形之一的，撰写《案件处理意见报告》，说明拟作处理的理由，报互联网信息内容管理部门负责人批准后根据不同情况分别处理： （一）认为违法事实不成立，应当予以销案的； （二）违法行为情节轻微，没有造成危害后果，不予行政处罚的； （三）案件不属于本机关管辖，应当移送其他行政机关管辖的； （四）涉嫌犯罪，应当移送司法机关的。"},{"i":32,"n":"第三十二条","txt":"互联网信息内容管理部门进行案件调查时，对已有证据证明违法事实成立的，应当出具责令改正通知书，责令当事人改正或者限期改正违法行为。"},{"i":33,"n":"第三十三条","txt":"互联网信息内容管理部门作出吊销互联网新闻信息服务许可证、较大数额罚款等行政处罚决定之前，应当告知当事人有要求举行听证的权利。当事人要求听证的，应当在被告知后三日内提出，互联网信息内容管理部门应当组织听证。当事人逾期未要求听证的，视为放弃权利。"},{"i":34,"n":"第三十四条","txt":"互联网信息内容管理部门应当在听证的七日前，将《举行听证通知书》（格式见附件10）送达当事人，告知举行听证的时间、地点。 听证应当制作《听证笔录》（格式见附件11），交当事人审核无误后签字或者盖章。"},{"i":35,"n":"第三十五条","txt":"互联网信息内容管理部门对互联网信息服务提供者违法行为作出行政处罚决定前，可以根据有关规定对其实施约谈，谈话结束后制作《执法约谈笔录》（格式见附件12）。"},{"i":36,"n":"第三十六条","txt":"互联网信息内容管理部门作出行政处罚决定之前，应当填写《行政处罚意见告知书》（格式见附件13），告知当事人拟作出行政处罚的违法事实、处罚的理由和依据，以及当事人依法享有的陈述、申辩权。 互联网信息内容管理部门应当充分听取当事人的陈述和申辩。当事人提出的事实、理由或者证据经复核成立的，应当采纳。当事人在接到告知书之日起三个工作日内未提出陈述、申辩的，视为放弃权利。 互联网信息内容管理部门不得因当事人陈述、申辩而加重处罚。"},{"i":37,"n":"第三十七条","txt":"拟作出的行政处罚决定应当报互联网信息内容管理部门负责人审查。互联网信息内容管理部门负责人根据不同情况，分别作出如下决定： （一）确有应受行政处罚的违法行为的，根据情节轻重及具体情况，作出行政处罚决定； （二）违法行为轻微，依法可以不予行政处罚的，不予行政处罚； （三）违法事实不能成立的，不予行政处罚； （四）违法行为已构成犯罪的，移送司法机关。"},{"i":38,"n":"第三十八条","txt":"对情节复杂或者重大违法行为给予较重的行政处罚，互联网信息内容管理部门负责人应当集体讨论决定。集体讨论决定的过程应当有书面记录。 情节复杂、重大违法行为标准由互联网信息内容管理部门根据实际情况确定。"},{"i":39,"n":"第三十九条","txt":"互联网信息内容管理部门作出行政处罚决定，应当制作统一编号的《行政处罚决定书》（格式见附件14）。 《行政处罚决定书》应当载明下列事项： （一）当事人的姓名或者名称、地址等基本情况； （二）违反法律、法规或者规章的事实和证据； （三）行政处罚的种类和依据; （四）行政处罚的履行方式和期限； （五）不服行政处罚决定，申请行政复议或者提起行政诉讼的途径和期限； （六）作出行政处罚决定的互联网信息内容管理部门名称和作出决定的日期。 行政处罚决定中涉及没收有关物品的，还应当附没收物品凭证。 《行政处罚决定书》应当盖有作出行政处罚决定的互联网信息内容管理部门的印章。"},{"i":40,"n":"第四十条","txt":"《行政处罚决定书》应当在宣告后当场交付当事人；当事人不在场的，应当在七日内依照民事诉讼法的有关规定，将《行政处罚决定书》送达当事人。"},{"i":41,"n":"第四十一条","txt":"《行政处罚决定书》送达后，当事人应当在处罚决定的期限内予以履行。 当事人确有经济困难，可以提出延期或者分期缴纳罚款的申请，并提交书面材料。经案件承办人审核，确定延期或者分期缴纳罚款的期限和金额，报互联网信息内容管理部门负责人批准后执行。"},{"i":42,"n":"第四十二条","txt":"互联网信息服务提供者违反相关法律法规规章，需由电信主管部门关闭网站、吊销互联网信息服务增值电信业务经营许可证或者取消备案的，转电信主管部门处理。"},{"i":43,"n":"第四十三条","txt":"当事人对互联网信息内容管理部门给予的行政处罚享有陈述、申辩权，对行政处罚决定不服的，有权依法申请行政复议或者提起行政诉讼。 当事人对行政处罚决定不服，申请行政复议或者提起行政诉讼的，行政处罚不停止执行，但法律另有规定的除外。"},{"i":44,"n":"第四十四条","txt":"当事人在法定期限内不申请行政复议或者提起行政诉讼，又不履行行政处罚决定的，作出处罚决定的互联网信息内容管理部门可以申请人民法院强制执行。 互联网信息内容管理部门申请人民法院强制执行前应当填写《履行行政处罚决定催告书》（格式见附件15），书面催告当事人履行义务，并告知履行义务的期限和方式、依法享有的陈述和申辩权，涉及加处罚款的，应当有明确的金额和给付方式。 加处罚款的总数额不得超过原罚款数额。 当事人进行陈述、申辩的，互联网信息内容管理部门应当对当事人提出的事实、理由和证据进行记录、复核，并制作陈述申辩笔录、陈述申辩复核意见书。当事人提出的事实、理由或者证据成立的，互联网信息内容管理部门应当采纳。 《履行行政处罚决定催告书》送达十个工作日后，当事人仍未履行处罚决定的，互联网信息内容管理部门可以申请人民法院强制执行，并填写《行政处罚强制执行申请书》（格式见附件16）。"},{"i":45,"n":"第四十五条","txt":"行政处罚决定履行或者执行后，办案人应当填写《行政处罚结案报告》（格式见附件17），将有关案件材料进行整理装订，归档保存。"},{"i":46,"n":"第四十六条","txt":"本规定中的期限以时、日计算，开始的时和日不计算在内。期限届满的最后一日是节假日的，以节假日后的第一日为届满的日期。法律、法规另有规定的除外。"},{"i":47,"n":"第四十七条","txt":"本规定中的“以上”“以下”“以内”，均包括本数。"},{"i":48,"n":"第四十八条","txt":"国家互联网信息内容管理部门负责制定行政执法所适用的文书格式范本。各省、自治区、直辖市互联网信息内容管理部门可以参照文书格式范本，制定本行政区域行政处罚所适用的文书格式并自行印制。"},{"i":49,"n":"第四十九条","txt":"本规定自2017年6月1日起施行。 附 件： 1.案件来源登记表 2.立案审批表 3.不予立案审批表 4.撤销立案审批表 5.询问笔录 6.登记保存物品清单 7.登记保存物品通知书 8.电子取证工作记录 9.案件处理意见报告 10.举行听证通知书 11.听证笔录 12.执法约谈笔录 13.行政处罚意见告知书 14.行政处罚决定书 15.履行行政处罚决定催告书 16.行政处罚强制执行申请书 17.行政处罚结案报告"}],"hulianwangxinxifuwushenduhechengguanliguiding-2":[{"i":1,"n":"第一条","txt":"为了加强互联网信息服务深度合成管理，弘扬社会主义核心价值观，维护国家安全和社会公共利益，保护公民、法人和其他组织的合法权益，根据《中华人民共和国网络安全法》、《中华人民共和国数据安全法》、《中华人民共和国个人信息保护法》、《互联网信息服务管理办法》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内应用深度合成技术提供互联网信息服务（以下简称深度合成服务），适用本规定。法律、行政法规另有规定的，依照其规定。"},{"i":3,"n":"第三条","txt":"国家网信部门负责统筹协调全国深度合成服务的治理和相关监督管理工作。国务院电信主管部门、公安部门依据各自职责负责深度合成服务的监督管理工作。 地方网信部门负责统筹协调本行政区域内的深度合成服务的治理和相关监督管理工作。地方电信主管部门、公安部门依据各自职责负责本行政区域内的深度合成服务的监督管理工作。"},{"i":4,"n":"第四条","txt":"提供深度合成服务，应当遵守法律法规，尊重社会公德和伦理道德，坚持正确政治方向、舆论导向、价值取向，促进深度合成服务向上向善。"},{"i":5,"n":"第五条","txt":"鼓励相关行业组织加强行业自律，建立健全行业标准、行业准则和自律管理制度，督促指导深度合成服务提供者和技术支持者制定完善业务规范、依法开展业务和接受社会监督。"},{"i":6,"n":"第六条","txt":"任何组织和个人不得利用深度合成服务制作、复制、发布、传播法律、行政法规禁止的信息，不得利用深度合成服务从事危害国家安全和利益、损害国家形象、侵害社会公共利益、扰乱经济和社会秩序、侵犯他人合法权益等法律、行政法规禁止的活动。 深度合成服务提供者和使用者不得利用深度合成服务制作、复制、发布、传播虚假新闻信息。转载基于深度合成服务制作发布的新闻信息的，应当依法转载互联网新闻信息稿源单位发布的新闻信息。"},{"i":7,"n":"第七条","txt":"深度合成服务提供者应当落实信息安全主体责任，建立健全用户注册、算法机制机理审核、科技伦理审查、信息发布审核、数据安全、个人信息保护、反电信网络诈骗、应急处置等管理制度，具有安全可控的技术保障措施。"},{"i":8,"n":"第八条","txt":"深度合成服务提供者应当制定和公开管理规则、平台公约，完善服务协议，依法依约履行管理责任，以显著方式提示深度合成服务技术支持者和使用者承担信息安全义务。"},{"i":9,"n":"第九条","txt":"深度合成服务提供者应当基于移动电话号码、身份证件号码、统一社会信用代码或者国家网络身份认证公共服务等方式，依法对深度合成服务使用者进行真实身份信息认证，不得向未进行真实身份信息认证的深度合成服务使用者提供信息发布服务。"},{"i":10,"n":"第十条","txt":"深度合成服务提供者应当加强深度合成内容管理，采取技术或者人工方式对深度合成服务使用者的输入数据和合成结果进行审核。 深度合成服务提供者应当建立健全用于识别违法和不良信息的特征库，完善入库标准、规则和程序，记录并留存相关网络日志。 深度合成服务提供者发现违法和不良信息的，应当依法采取处置措施，保存有关记录，及时向网信部门和有关主管部门报告；对相关深度合成服务使用者依法依约采取警示、限制功能、暂停服务、关闭账号等处置措施。"},{"i":11,"n":"第十一条","txt":"深度合成服务提供者应当建立健全辟谣机制，发现利用深度合成服务制作、复制、发布、传播虚假信息的，应当及时采取辟谣措施，保存有关记录，并向网信部门和有关主管部门报告。"},{"i":12,"n":"第十二条","txt":"深度合成服务提供者应当设置便捷的用户申诉和公众投诉、举报入口，公布处理流程和反馈时限，及时受理、处理和反馈处理结果。"},{"i":13,"n":"第十三条","txt":"互联网应用商店等应用程序分发平台应当落实上架审核、日常管理、应急处置等安全管理责任，核验深度合成类应用程序的安全评估、备案等情况；对违反国家有关规定的，应当及时采取不予上架、警示、暂停服务或者下架等处置措施。"},{"i":14,"n":"第十四条","txt":"深度合成服务提供者和技术支持者应当加强训练数据管理，采取必要措施保障训练数据安全；训练数据包含个人信息的，应当遵守个人信息保护的有关规定。 深度合成服务提供者和技术支持者提供人脸、人声等生物识别信息编辑功能的，应当提示深度合成服务使用者依法告知被编辑的个人，并取得其单独同意。"},{"i":15,"n":"第十五条","txt":"深度合成服务提供者和技术支持者应当加强技术管理，定期审核、评估、验证生成合成类算法机制机理。 深度合成服务提供者和技术支持者提供具有以下功能的模型、模板等工具的，应当依法自行或者委托专业机构开展安全评估： （一）生成或者编辑人脸、人声等生物识别信息的； （二）生成或者编辑可能涉及国家安全、国家形象、国家利益和社会公共利益的特殊物体、场景等非生物识别信息的。"},{"i":16,"n":"第十六条","txt":"深度合成服务提供者对使用其服务生成或者编辑的信息内容，应当采取技术措施添加不影响用户使用的标识，并依照法律、行政法规和国家有关规定保存日志信息。"},{"i":17,"n":"第十七条","txt":"深度合成服务提供者提供以下深度合成服务，可能导致公众混淆或者误认的，应当在生成或者编辑的信息内容的合理位置、区域进行显著标识，向公众提示深度合成情况： （一）智能对话、智能写作等模拟自然人进行文本的生成或者编辑服务； （二）合成人声、仿声等语音生成或者显著改变个人身份特征的编辑服务； （三）人脸生成、人脸替换、人脸操控、姿态操控等人物图像、视频生成或者显著改变个人身份特征的编辑服务； （四）沉浸式拟真场景等生成或者编辑服务； （五）其他具有生成或者显著改变信息内容功能的服务。 深度合成服务提供者提供前款规定之外的深度合成服务的，应当提供显著标识功能，并提示深度合成服务使用者可以进行显著标识。"},{"i":18,"n":"第十八条","txt":"任何组织和个人不得采用技术手段删除、篡改、隐匿本规定第十六条和第十七条规定的深度合成标识。"},{"i":19,"n":"第十九条","txt":"具有舆论属性或者社会动员能力的深度合成服务提供者，应当按照《互联网信息服务算法推荐管理规定》履行备案和变更、注销备案手续。 深度合成服务技术支持者应当参照前款规定履行备案和变更、注销备案手续。 完成备案的深度合成服务提供者和技术支持者应当在其对外提供服务的网站、应用程序等的显著位置标明其备案编号并提供公示信息链接。"},{"i":20,"n":"第二十条","txt":"深度合成服务提供者开发上线具有舆论属性或者社会动员能力的新产品、新应用、新功能的，应当按照国家有关规定开展安全评估。"},{"i":21,"n":"第二十一条","txt":"网信部门和电信主管部门、公安部门依据职责对深度合成服务开展监督检查。深度合成服务提供者和技术支持者应当依法予以配合，并提供必要的技术、数据等支持和协助。 网信部门和有关主管部门发现深度合成服务存在较大信息安全风险的，可以按照职责依法要求深度合成服务提供者和技术支持者采取暂停信息更新、用户账号注册或者其他相关服务等措施。深度合成服务提供者和技术支持者应当按照要求采取措施，进行整改，消除隐患。"},{"i":22,"n":"第二十二条","txt":"深度合成服务提供者和技术支持者违反本规定的，依照有关法律、行政法规的规定处罚；造成严重后果的，依法从重处罚。 构成违反治安管理行为的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":23,"n":"第二十三条","txt":"本规定中下列用语的含义： 深度合成技术，是指利用深度学习、虚拟现实等生成合成类算法制作文本、图像、音频、视频、虚拟场景等网络信息的技术，包括但不限于： （一）篇章生成、文本风格转换、问答对话等生成或者编辑文本内容的技术； （二）文本转语音、语音转换、语音属性编辑等生成或者编辑语音内容的技术； （三）音乐生成、场景声编辑等生成或者编辑非语音内容的技术； （四）人脸生成、人脸替换、人物属性编辑、人脸操控、姿态操控等生成或者编辑图像、视频内容中生物特征的技术； （五）图像生成、图像增强、图像修复等生成或者编辑图像、视频内容中非生物特征的技术； （六）三维重建、数字仿真等生成或者编辑数字人物、虚拟场景的技术。 深度合成服务提供者，是指提供深度合成服务的组织、个人。 深度合成服务技术支持者，是指为深度合成服务提供技术支持的组织、个人。 深度合成服务使用者，是指使用深度合成服务制作、复制、发布、传"},{"i":24,"n":"第二十四条","txt":"深度合成服务提供者和技术支持者从事网络出版服务、网络文化活动和网络视听节目服务的，应当同时符合新闻出版、文化和旅游、广播电视主管部门的规定。"},{"i":25,"n":"第二十五条","txt":"本规定自2023年1月10日起施行。"}],"hulianwangxinxifuwusuanfatuijianguanliguiding":[{"i":1,"n":"第一条","txt":"为了规范互联网信息服务算法推荐活动，弘扬社会主义核心价值观，维护国家安全和社会公共利益，保护公民、法人和其他组织的合法权益，促进互联网信息服务健康有序发展，根据《中华人民共和国网络安全法》、《中华人民共和国数据安全法》、《中华人民共和国个人信息保护法》、《互联网信息服务管理办法》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内应用算法推荐技术提供互联网信息服务（以下简称算法推荐服务），适用本规定。法律、行政法规另有规定的，依照其规定。 前款所称应用算法推荐技术，是指利用生成合成类、个性化推送类、排序精选类、检索过滤类、调度决策类等算法技术向用户提供信息。"},{"i":3,"n":"第三条","txt":"国家网信部门负责统筹协调全国算法推荐服务治理和相关监督管理工作。国务院电信、公安、市场监管等有关部门依据各自职责负责算法推荐服务监督管理工作。 地方网信部门负责统筹协调本行政区域内的算法推荐服务治理和相关监督管理工作。地方电信、公安、市场监管等有关部门依据各自职责负责本行政区域内的算法推荐服务监督管理工作。"},{"i":4,"n":"第四条","txt":"提供算法推荐服务，应当遵守法律法规，尊重社会公德和伦理，遵守商业道德和职业道德，遵循公正公平、公开透明、科学合理和诚实信用的原则。"},{"i":5,"n":"第五条","txt":"鼓励相关行业组织加强行业自律，建立健全行业标准、行业准则和自律管理制度，督促指导算法推荐服务提供者制定完善服务规范、依法提供服务并接受社会监督。"},{"i":6,"n":"第六条","txt":"算法推荐服务提供者应当坚持主流价值导向，优化算法推荐服务机制，积极传播正能量，促进算法应用向上向善。 算法推荐服务提供者不得利用算法推荐服务从事危害国家安全和社会公共利益、扰乱经济秩序和社会秩序、侵犯他人合法权益等法律、行政法规禁止的活动，不得利用算法推荐服务传播法律、行政法规禁止的信息，应当采取措施防范和抵制传播不良信息。"},{"i":7,"n":"第七条","txt":"算法推荐服务提供者应当落实算法安全主体责任，建立健全算法机制机理审核、科技伦理审查、用户注册、信息发布审核、数据安全和个人信息保护、反电信网络诈骗、安全评估监测、安全事件应急处置等管理制度和技术措施，制定并公开算法推荐服务相关规则，配备与算法推荐服务规模相适应的专业人员和技术支撑。"},{"i":8,"n":"第八条","txt":"算法推荐服务提供者应当定期审核、评估、验证算法机制机理、模型、数据和应用结果等，不得设置诱导用户沉迷、过度消费等违反法律法规或者违背伦理道德的算法模型。"},{"i":9,"n":"第九条","txt":"算法推荐服务提供者应当加强信息安全管理，建立健全用于识别违法和不良信息的特征库，完善入库标准、规则和程序。发现未作显著标识的算法生成合成信息的，应当作出显著标识后，方可继续传输。 发现违法信息的，应当立即停止传输，采取消除等处置措施，防止信息扩散，保存有关记录，并向网信部门和有关部门报告。发现不良信息的，应当按照网络信息内容生态治理有关规定予以处置。"},{"i":10,"n":"第十条","txt":"算法推荐服务提供者应当加强用户模型和用户标签管理，完善记入用户模型的兴趣点规则和用户标签管理规则，不得将违法和不良信息关键词记入用户兴趣点或者作为用户标签并据以推送信息。"},{"i":11,"n":"第十一条","txt":"算法推荐服务提供者应当加强算法推荐服务版面页面生态管理，建立完善人工干预和用户自主选择机制，在首页首屏、热搜、精选、榜单类、弹窗等重点环节积极呈现符合主流价值导向的信息。"},{"i":12,"n":"第十二条","txt":"鼓励算法推荐服务提供者综合运用内容去重、打散干预等策略，并优化检索、排序、选择、推送、展示等规则的透明度和可解释性，避免对用户产生不良影响，预防和减少争议纠纷。"},{"i":13,"n":"第十三条","txt":"算法推荐服务提供者提供互联网新闻信息服务的，应当依法取得互联网新闻信息服务许可，规范开展互联网新闻信息采编发布服务、转载服务和传播平台服务，不得生成合成虚假新闻信息，不得传播非国家规定范围内的单位发布的新闻信息。"},{"i":14,"n":"第十四条","txt":"算法推荐服务提供者不得利用算法虚假注册账号、非法交易账号、操纵用户账号或者虚假点赞、评论、转发，不得利用算法屏蔽信息、过度推荐、操纵榜单或者检索结果排序、控制热搜或者精选等干预信息呈现，实施影响网络舆论或者规避监督管理行为。"},{"i":15,"n":"第十五条","txt":"算法推荐服务提供者不得利用算法对其他互联网信息服务提供者进行不合理限制，或者妨碍、破坏其合法提供的互联网信息服务正常运行，实施垄断和不正当竞争行为。"},{"i":16,"n":"第十六条","txt":"算法推荐服务提供者应当以显著方式告知用户其提供算法推荐服务的情况，并以适当方式公示算法推荐服务的基本原理、目的意图和主要运行机制等。"},{"i":17,"n":"第十七条","txt":"算法推荐服务提供者应当向用户提供不针对其个人特征的选项，或者向用户提供便捷的关闭算法推荐服务的选项。用户选择关闭算法推荐服务的，算法推荐服务提供者应当立即停止提供相关服务。 算法推荐服务提供者应当向用户提供选择或者删除用于算法推荐服务的针对其个人特征的用户标签的功能。 算法推荐服务提供者应用算法对用户权益造成重大影响的，应当依法予以说明并承担相应责任。"},{"i":18,"n":"第十八条","txt":"算法推荐服务提供者向未成年人提供服务的，应当依法履行未成年人网络保护义务，并通过开发适合未成年人使用的模式、提供适合未成年人特点的服务等方式，便利未成年人获取有益身心健康的信息。 算法推荐服务提供者不得向未成年人推送可能引发未成年人模仿不安全行为和违反社会公德行为、诱导未成年人不良嗜好等可能影响未成年人身心健康的信息，不得利用算法推荐服务诱导未成年人沉迷网络。"},{"i":19,"n":"第十九条","txt":"算法推荐服务提供者向老年人提供服务的，应当保障老年人依法享有的权益，充分考虑老年人出行、就医、消费、办事等需求，按照国家有关规定提供智能化适老服务，依法开展涉电信网络诈骗信息的监测、识别和处置，便利老年人安全使用算法推荐服务。"},{"i":20,"n":"第二十条","txt":"算法推荐服务提供者向劳动者提供工作调度服务的，应当保护劳动者取得劳动报酬、休息休假等合法权益，建立完善平台订单分配、报酬构成及支付、工作时间、奖惩等相关算法。"},{"i":21,"n":"第二十一条","txt":"算法推荐服务提供者向消费者销售商品或者提供服务的，应当保护消费者公平交易的权利，不得根据消费者的偏好、交易习惯等特征，利用算法在交易价格等交易条件上实施不合理的差别待遇等违法行为。"},{"i":22,"n":"第二十二条","txt":"算法推荐服务提供者应当设置便捷有效的用户申诉和公众投诉、举报入口，明确处理流程和反馈时限，及时受理、处理并反馈处理结果。"},{"i":23,"n":"第二十三条","txt":"网信部门会同电信、公安、市场监管等有关部门建立算法分级分类安全管理制度，根据算法推荐服务的舆论属性或者社会动员能力、内容类别、用户规模、算法推荐技术处理的数据重要程度、对用户行为的干预程度等对算法推荐服务提供者实施分级分类管理。"},{"i":24,"n":"第二十四条","txt":"具有舆论属性或者社会动员能力的算法推荐服务提供者应当在提供服务之日起十个工作日内通过互联网信息服务算法备案系统填报服务提供者的名称、服务形式、应用领域、算法类型、算法自评估报告、拟公示内容等信息，履行备案手续。 算法推荐服务提供者的备案信息发生变更的，应当在变更之日起十个工作日内办理变更手续。 算法推荐服务提供者终止服务的，应当在终止服务之日起二十个工作日内办理注销备案手续，并作出妥善安排。"},{"i":25,"n":"第二十五条","txt":"国家和省、自治区、直辖市网信部门收到备案人提交的备案材料后，材料齐全的，应当在三十个工作日内予以备案，发放备案编号并进行公示；材料不齐全的，不予备案，并应当在三十个工作日内通知备案人并说明理由。"},{"i":26,"n":"第二十六条","txt":"完成备案的算法推荐服务提供者应当在其对外提供服务的网站、应用程序等的显著位置标明其备案编号并提供公示信息链接。"},{"i":27,"n":"第二十七条","txt":"具有舆论属性或者社会动员能力的算法推荐服务提供者应当按照国家有关规定开展安全评估。"},{"i":28,"n":"第二十八条","txt":"网信部门会同电信、公安、市场监管等有关部门对算法推荐服务依法开展安全评估和监督检查工作，对发现的问题及时提出整改意见并限期整改。 算法推荐服务提供者应当依法留存网络日志，配合网信部门和电信、公安、市场监管等有关部门开展安全评估和监督检查工作，并提供必要的技术、数据等支持和协助。"},{"i":29,"n":"第二十九条","txt":"参与算法推荐服务安全评估和监督检查的相关机构和人员对在履行职责中知悉的个人隐私、个人信息和商业秘密应当依法予以保密，不得泄露或者非法向他人提供。"},{"i":30,"n":"第三十条","txt":"任何组织和个人发现违反本规定行为的，可以向网信部门和有关部门投诉、举报。收到投诉、举报的部门应当及时依法处理。"},{"i":31,"n":"第三十一条","txt":"算法推荐服务提供者违反本规定第七条、第八条、第九条第一款、第十条、第十四条、第十六条、第十七条、第二十二条、第二十四条、第二十六条规定，法律、行政法规有规定的，依照其规定；法律、行政法规没有规定的，由网信部门和电信、公安、市场监管等有关部门依据职责给予警告、通报批评，责令限期改正；拒不改正或者情节严重的，责令暂停信息更新，并处一万元以上十万元以下罚款。构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":32,"n":"第三十二条","txt":"算法推荐服务提供者违反本规定第六条、第九条第二款、第十一条、第十三条、第十五条、第十八条、第十九条、第二十条、第二十一条、第二十七条、第二十八条第二款规定的，由网信部门和电信、公安、市场监管等有关部门依据职责，按照有关法律、行政法规和部门规章的规定予以处理。"},{"i":33,"n":"第三十三条","txt":"具有舆论属性或者社会动员能力的算法推荐服务提供者通过隐瞒有关情况、提供虚假材料等不正当手段取得备案的，由国家和省、自治区、直辖市网信部门予以撤销备案，给予警告、通报批评；情节严重的，责令暂停信息更新，并处一万元以上十万元以下罚款。 具有舆论属性或者社会动员能力的算法推荐服务提供者终止服务未按照本规定第二十四条第三款要求办理注销备案手续，或者发生严重违法情形受到责令关闭网站、吊销相关业务许可证或者吊销营业执照等行政处罚的，由国家和省、自治区、直辖市网信部门予以注销备案。"},{"i":34,"n":"第三十四条","txt":"本规定由国家互联网信息办公室会同工业和信息化部、公安部、国家市场监督管理总局负责解释。"},{"i":35,"n":"第三十五条","txt":"本规定自2022年3月1日起施行。"}],"hulianwangyumingguanlibanfa-2":[{"i":1,"n":"第一条","txt":"为了规范互联网域名服务，保护用户合法权益，保障互联网域名系统安全、可靠运行，推动中文域名和国家顶级域名发展和应用，促进中国互联网健康发展，根据《中华人民共和国行政许可法》《国务院对确需保留的行政审批项目设定行政许可的决定》等规定，参照国际上互联网域名管理准则，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事互联网域名服务及其运行维护、监督管理等相关活动，应当遵守本办法。 本办法所称互联网域名服务（以下简称域名服务），是指从事域名根服务器运行和管理、顶级域名运行和管理、域名注册、域名解析等活动。"},{"i":3,"n":"第三条","txt":"工业和信息化部对全国的域名服务实施监督管理，主要职责是： （一）制定互联网域名管理规章及政策； （二）制定中国互联网域名体系、域名资源发展规划； （三）管理境内的域名根服务器运行机构和域名注册管理机构； （四）负责域名体系的网络与信息安全管理； （五）依法保护用户个人信息和合法权益； （六）负责与域名有关的国际协调； （七）管理境内的域名解析服务； （八）管理其他与域名服务相关的活动。"},{"i":4,"n":"第四条","txt":"各省、自治区、直辖市通信管理局对本行政区域内的域名服务实施监督管理，主要职责是： （一）贯彻执行域名管理法律、行政法规、规章和政策； （二）管理本行政区域内的域名注册服务机构； （三）协助工业和信息化部对本行政区域内的域名根服务器运行机构和域名注册管理机构进行管理； （四）负责本行政区域内域名系统的网络与信息安全管理； （五）依法保护用户个人信息和合法权益； （六）管理本行政区域内的域名解析服务； （七）管理本行政区域内其他与域名服务相关的活动。"},{"i":5,"n":"第五条","txt":"中国互联网域名体系由工业和信息化部予以公告。根据域名发展的实际情况，工业和信息化部可以对中国互联网域名体系进行调整。"},{"i":6,"n":"第六条","txt":"“.CN”和“.中国”是中国的国家顶级域名。 中文域名是中国互联网域名体系的重要组成部分。国家鼓励和支持中文域名系统的技术研究和推广应用。"},{"i":7,"n":"第七条","txt":"提供域名服务，应当遵守国家相关法律法规，符合相关技术规范和标准。"},{"i":8,"n":"第八条","txt":"任何组织和个人不得妨碍互联网域名系统的安全和稳定运行。 第二章域名管理"},{"i":9,"n":"第九条","txt":"在境内设立域名根服务器及域名根服务器运行机构、域名注册管理机构和域名注册服务机构的，应当依据本办法取得工业和信息化部或者省、自治区、直辖市通信管理局（以下统称电信管理机构）的相应许可。"},{"i":10,"n":"第十条","txt":"申请设立域名根服务器及域名根服务器运行机构的，应当具备以下条件： （一）域名根服务器设置在境内，并且符合互联网发展相关规划及域名系统安全稳定运行要求； （二）是依法设立的法人，该法人及其主要出资者、主要经营管理人员具有良好的信用记录； （三）具有保障域名根服务器安全可靠运行的场地、资金、环境、专业人员和技术能力以及符合电信管理机构要求的信息管理系统； （四）具有健全的网络与信息安全保障措施，包括管理人员、网络与信息安全管理制度、应急处置预案和相关技术、管理措施等； （五）具有用户个人信息保护能力、提供长期服务的能力及健全的服务退出机制； （六）法律、行政法规规定的其他条件。"},{"i":11,"n":"第十一条","txt":"申请设立域名注册管理机构的，应当具备以下条件： （一）域名管理系统设置在境内，并且持有的顶级域名符合相关法律法规及域名系统安全稳定运行要求； （二）是依法设立的法人，该法人及其主要出资者、主要经营管理人员具有良好的信用记录； （三）具有完善的业务发展计划和技术方案以及与从事顶级域名运行管理相适应的场地、资金、专业人员以及符合电信管理机构要求的信息管理系统； （四）具有健全的网络与信息安全保障措施，包括管理人员、网络与信息安全管理制度、应急处置预案和相关技术、管理措施等； （五）具有进行真实身份信息核验和用户个人信息保护的能力、提供长期服务的能力及健全的服务退出机制； （六）具有健全的域名注册服务管理制度和对域名注册服务机构的监督机制； （七）法律、行政法规规定的其他条件。"},{"i":12,"n":"第十二条","txt":"申请设立域名注册服务机构的，应当具备以下条件： （一）在境内设置域名注册服务系统、注册数据库和相应的域名解析系统； （二）是依法设立的法人，该法人及其主要出资者、主要经营管理人员具有良好的信用记录； （三）具有与从事域名注册服务相适应的场地、资金和专业人员以及符合电信管理机构要求的信息管理系统； （四）具有进行真实身份信息核验和用户个人信息保护的能力、提供长期服务的能力及健全的服务退出机制； （五）具有健全的域名注册服务管理制度和对域名注册代理机构的监督机制； （六）具有健全的网络与信息安全保障措施，包括管理人员、网络与信息安全管理制度、应急处置预案和相关技术、管理措施等； （七）法律、行政法规规定的其他条件。"},{"i":13,"n":"第十三条","txt":"申请设立域名根服务器及域名根服务器运行机构、域名注册管理机构的，应当向工业和信息化部提交申请材料。申请设立域名注册服务机构的，应当向住所地省、自治区、直辖市通信管理局提交申请材料。 申请材料应当包括： （一）申请单位的基本情况及其法定代表人签署的依法诚信经营承诺书； （二）对域名服务实施有效管理的证明材料，包括相关系统及场所、服务能力的证明材料、管理制度、与其他机构签订的协议等； （三）网络与信息安全保障制度及措施； （四）证明申请单位信誉的材料。"},{"i":14,"n":"第十四条","txt":"申请材料齐全、符合法定形式的，电信管理机构应当向申请单位出具受理申请通知书；申请材料不齐全或者不符合法定形式的，电信管理机构应当场或者在5个工作日内一次性书面告知申请单位需要补正的全部内容；不予受理的，应当出具不予受理通知书并说明理由。"},{"i":15,"n":"第十五条","txt":"电信管理机构应当自受理之日起20个工作日内完成审查，作出予以许可或者不予许可的决定。20个工作日内不能作出决定的，经电信管理机构负责人批准，可以延长10个工作日，并将延长期限的理由告知申请单位。需要组织专家论证的，论证时间不计入审查期限。 予以许可的，应当颁发相应的许可文件；不予许可的，应当书面通知申请单位并说明理由。"},{"i":16,"n":"第十六条","txt":"域名根服务器运行机构、域名注册管理机构和域名注册服务机构的许可有效期为5年。"},{"i":17,"n":"第十七条","txt":"域名根服务器运行机构、域名注册管理机构和域名注册服务机构的名称、住所、法定代表人等信息发生变更的，应当自变更之日起20日内向原发证机关办理变更手续。"},{"i":18,"n":"第十八条","txt":"在许可有效期内，域名根服务器运行机构、域名注册管理机构、域名注册服务机构拟终止相关服务的，应当提前30日书面通知用户，提出可行的善后处理方案，并向原发证机关提交书面申请。 原发证机关收到申请后，应当向社会公示30日。公示期结束60日内，原发证机关应当完成审查并做出决定。"},{"i":19,"n":"第十九条","txt":"许可有效期届满需要继续从事域名服务的，应当提前90日向原发证机关申请延续；不再继续从事域名服务的，应当提前90日向原发证机关报告并做好善后工作。"},{"i":20,"n":"第二十条","txt":"域名注册服务机构委托域名注册代理机构开展市场销售等工作的，应当对域名注册代理机构的工作进行监督和管理。 域名注册代理机构受委托开展市场销售等工作的过程中，应当主动表明代理关系，并在域名注册服务合同中明示相关域名注册服务机构名称及代理关系。"},{"i":21,"n":"第二十一条","txt":"域名注册管理机构、域名注册服务机构应当在境内设立相应的应急备份系统并定期备份域名注册数据。"},{"i":22,"n":"第二十二条","txt":"域名根服务器运行机构、域名注册管理机构、域名注册服务机构应当在其网站首页和经营场所显著位置标明其许可相关信息。域名注册管理机构还应当标明与其合作的域名注册服务机构名单。 域名注册代理机构应当在其网站首页和经营场所显著位置标明其代理的域名注册服务机构名称。"},{"i":23,"n":"第二十三条","txt":"域名根服务器运行机构、域名注册管理机构和域名注册服务机构应当向用户提供安全、方便、稳定的服务。"},{"i":24,"n":"第二十四条","txt":"域名注册管理机构应当根据本办法制定域名注册实施细则并向社会公开。"},{"i":25,"n":"第二十五条","txt":"域名注册管理机构应当通过电信管理机构许可的域名注册服务机构开展域名注册服务。 域名注册服务机构应当按照电信管理机构许可的域名注册服务项目提供服务，不得为未经电信管理机构许可的域名注册管理机构提供域名注册服务。"},{"i":26,"n":"第二十六条","txt":"域名注册服务原则上实行“先申请先注册”，相应域名注册实施细则另有规定的，从其规定。"},{"i":27,"n":"第二十七条","txt":"为维护国家利益和社会公众利益，域名注册管理机构应当建立域名注册保留字制度。"},{"i":28,"n":"第二十八条","txt":"任何组织或者个人注册、使用的域名中，不得含有下列内容： （一）反对宪法所确定的基本原则的 （二）危害国家安全，泄露国家秘密，颠覆国家政权，破坏国家统一的 （三）损害国家荣誉和利益的 （四）煽动民族仇恨、民族歧视，破坏民族团结的 （五）破坏国家宗教政策，宣扬邪教和封建迷信的 （六）散布谣言，扰乱社会秩序，破坏社会稳定的 （七）散布淫秽、色情、赌博、暴力、凶杀、恐怖或者教唆犯罪的 （八）侮辱或者诽谤他人，侵害他人合法权益的 （九）含有法律、行政法规禁止的其他内容的。 域名注册管理机构、域名注册服务机构不得为含有前款所列内容的域名提供服务。"},{"i":29,"n":"第二十九条","txt":"域名注册服务机构不得采用欺诈、胁迫等不正当手段要求他人注册域名。"},{"i":30,"n":"第三十条","txt":"域名注册服务机构提供域名注册服务，应当要求域名注册申请者提供域名持有者真实、准确、完整的身份信息等域名注册信息。 域名注册管理机构和域名注册服务机构应当对域名注册信息的真实性、完整性进行核验。 域名注册申请者提供的域名注册信息不准确、不完整的，域名注册服务机构应当要求其予以补正。申请者不补正或者提供不真实的域名注册信息的，域名注册服务机构不得为其提供域名注册服务。"},{"i":31,"n":"第三十一条","txt":"域名注册服务机构应当公布域名注册服务的内容、时限、费用，保证服务质量，提供域名注册信息的公共查询服务。"},{"i":32,"n":"第三十二条","txt":"域名注册管理机构、域名注册服务机构应当依法存储、保护用户个人信息。未经用户同意不得将用户个人信息提供给他人，但法律、行政法规另有规定的除外。"},{"i":33,"n":"第三十三条","txt":"域名持有者的联系方式等信息发生变更的，应当在变更后30日内向域名注册服务机构办理域名注册信息变更手续。 域名持有者将域名转让给他人的，受让人应当遵守域名注册的相关要求。"},{"i":34,"n":"第三十四条","txt":"域名持有者有权选择、变更域名注册服务机构。变更域名注册服务机构的，原域名注册服务机构应当配合域名持有者转移其域名注册相关信息。 无正当理由的，域名注册服务机构不得阻止域名持有者变更域名注册服务机构。 电信管理机构依法要求停止解析的域名，不得变更域名注册服务机构。"},{"i":35,"n":"第三十五条","txt":"域名注册管理机构和域名注册服务机构应当设立投诉受理机制，并在其网站首页和经营场所显著位置公布投诉受理方式。 域名注册管理机构和域名注册服务机构应当及时处理投诉；不能及时处理的，应当说明理由和处理时限。"},{"i":36,"n":"第三十六条","txt":"提供域名解析服务，应当遵守有关法律、法规、标准，具备相应的技术、服务和网络与信息安全保障能力，落实网络与信息安全保障措施，依法记录并留存域名解析日志、维护日志和变更记录，保障解析服务质量和解析系统安全。涉及经营电信业务的，应当依法取得电信业务经营许可。"},{"i":37,"n":"第三十七条","txt":"提供域名解析服务，不得擅自篡改解析信息。 任何组织或者个人不得恶意将域名解析指向他人的IP地址。"},{"i":38,"n":"第三十八条","txt":"提供域名解析服务，不得为含有本办法第二十八条第一款所列内容的域名提供域名跳转。"},{"i":39,"n":"第三十九条","txt":"从事互联网信息服务的，其使用域名应当符合法律法规和电信管理机构的有关规定，不得将域名用于实施违法行为。"},{"i":40,"n":"第四十条","txt":"域名注册管理机构、域名注册服务机构应当配合国家有关部门依法开展的检查工作，并按照电信管理机构的要求对存在违法行为的域名采取停止解析等处置措施。 域名注册管理机构、域名注册服务机构发现其提供服务的域名发布、传输法律和行政法规禁止发布或者传输的信息的，应当立即采取消除、停止解析等处置措施，防止信息扩散，保存有关记录，并向有关部门报告。"},{"i":41,"n":"第四十一条","txt":"域名根服务器运行机构、域名注册管理机构和域名注册服务机构应当遵守国家相关法律、法规和标准，落实网络与信息安全保障措施，配置必要的网络通信应急设备，建立健全网络与信息安全监测技术手段和应急制度。域名系统出现网络与信息安全事件时，应当在24小时内向电信管理机构报告。 因国家安全和处置紧急事件的需要，域名根服务器运行机构、域名注册管理机构和域名注册服务机构应当服从电信管理机构的统一指挥与协调，遵守电信管理机构的管理要求。"},{"i":42,"n":"第四十二条","txt":"任何组织或者个人认为他人注册或者使用的域名侵害其合法权益的，可以向域名争议解决机构申请裁决或者依法向人民法院提起诉讼。"},{"i":43,"n":"第四十三条","txt":"已注册的域名有下列情形之一的，域名注册服务机构应当予以注销，并通知域名持有者： （一）域名持有者申请注销域名的； （二）域名持有者提交虚假域名注册信息的； （三）依据人民法院的判决、域名争议解决机构的裁决，应当注销的； （四）法律、行政法规规定予以注销的其他情形。"},{"i":44,"n":"第四十四条","txt":"电信管理机构应当加强对域名服务的监督检查。域名根服务器运行机构、域名注册管理机构、域名注册服务机构应当接受、配合电信管理机构的监督检查。 鼓励域名服务行业自律管理，鼓励公众监督域名服务。"},{"i":45,"n":"第四十五条","txt":"域名根服务器运行机构、域名注册管理机构、域名注册服务机构应当按照电信管理机构的要求，定期报送业务开展情况、安全运行情况、网络与信息安全责任落实情况、投诉和争议处理情况等信息。"},{"i":46,"n":"第四十六条","txt":"电信管理机构实施监督检查时，应当对域名根服务器运行机构、域名注册管理机构和域名注册服务机构报送的材料进行审核，并对其执行法律法规和电信管理机构有关规定的情况进行检查。 电信管理机构可以委托第三方专业机构开展有关监督检查活动。"},{"i":47,"n":"第四十七条","txt":"电信管理机构应当建立域名根服务器运行机构、域名注册管理机构和域名注册服务机构的信用记录制度，将其违反本办法并受到行政处罚的行为记入信用档案。"},{"i":48,"n":"第四十八条","txt":"电信管理机构开展监督检查，不得妨碍域名根服务器运行机构、域名注册管理机构和域名注册服务机构正常的经营和服务活动，不得收取任何费用，不得泄露所知悉的域名注册信息。"},{"i":49,"n":"第四十九条","txt":"违反本办法第九条规定，未经许可擅自设立域名根服务器及域名根服务器运行机构、域名注册管理机构、域名注册服务机构的，电信管理机构应当根据《中华人民共和国行政许可法》第八十一条的规定，采取措施予以制止，并视情节轻重，予以警告或者处一万元以上三万元以下罚款。"},{"i":50,"n":"第五十条","txt":"违反本办法规定，域名注册管理机构或者域名注册服务机构有下列行为之一的，由电信管理机构依据职权责令限期改正，并视情节轻重，处一万元以上三万元以下罚款，向社会公告: （一）为未经许可的域名注册管理机构提供域名注册服务,或者通过未经许可的域名注册服务机构开展域名注册服务的； （二）未按照许可的域名注册服务项目提供服务的； （三）未对域名注册信息的真实性、完整性进行核验的； （四）无正当理由阻止域名持有者变更域名注册服务机构的。"},{"i":51,"n":"第五十一条","txt":"违反本办法规定，提供域名解析服务，有下列行为之一的，由电信管理机构责令限期改正，可以视情节轻重处一万元以上三万元以下罚款，向社会公告： （一）擅自篡改域名解析信息或者恶意将域名解析指向他人IP地址的； （二）为含有本办法第二十八条第一款所列内容的域名提供域名跳转的； （三）未落实网络与信息安全保障措施的； （四）未依法记录并留存域名解析日志、维护日志和变更记录的； （五）未按照要求对存在违法行为的域名进行处置的。"},{"i":52,"n":"第五十二条","txt":"违反本办法第十七条、第十八条第一款、第二十一条、第二十二条、第二十八条第二款、第二十九条、第三十一条、第三十二条、第三十五条第一款、第四十条第二款、第四十一条规定的，由电信管理机构依据职权责令限期改正,可以并处一万元以上三万元以下罚款，向社会公告。"},{"i":53,"n":"第五十三条","txt":"法律、行政法规对有关违法行为的处罚另有规定的，依照有关法律、行政法规的规定执行。"},{"i":54,"n":"第五十四条","txt":"任何组织或者个人违反本办法第二十八条第一款规定注册、使用域名，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，由有关部门依法予以处罚。"},{"i":55,"n":"第五十五条","txt":"本办法下列用语的含义是： （一）域名：指互联网上识别和定位计算机的层次结构式的字符标识，与该计算机的IP地址相对应。 （二）中文域名：指含有中文文字的域名。 （三）顶级域名：指域名体系中根节点下的第一级域的名称。 （四）域名根服务器：指承担域名体系中根节点功能的服务器（含镜像服务器）。 （五）域名根服务器运行机构：指依法获得许可并承担域名根服务器运行、维护和管理工作的机构。 （六）域名注册管理机构：指依法获得许可并承担顶级域名运行和管理工作的机构。 （七）域名注册服务机构：指依法获得许可、受理域名注册申请并完成域名在顶级域名数据库中注册的机构。 （八）域名注册代理机构：指受域名注册服务机构的委托，受理域名注册申请，间接完成域名在顶级域名数据库中注册的机构。 （九）域名管理系统：指域名注册管理机构在境内开展顶级域名运行和管理所需的主要信息系统，包括注册管理系统、注册数据库、域名解析系统、"},{"i":56,"n":"第五十六条","txt":"本办法中规定的日期，除明确为工作日的以外，均为自然日。"},{"i":57,"n":"第五十七条","txt":"在本办法施行前未取得相应许可开展域名服务的，应当自本办法施行之日起十二个月内，按照本办法规定办理许可手续。 在本办法施行前已取得许可的域名根服务器运行机构、域名注册管理机构和域名注册服务机构，其许可有效期适用本办法第十六条的规定，有效期自本办法施行之日起计算。"},{"i":58,"n":"第五十八条","txt":"本办法自2017年11月1日起施行。2004年11月5日公布的《中国互联网络域名管理办法》（原信息产业部令第30号）同时废止。本办法施行前公布的有关规定与本办法不一致的，按照本办法执行。"}],"hulianwangwenhuaguanlizanxingguiding-2":[{"i":1,"n":"第一条","txt":"为了加强对互联网文化的管理，保障互联网文化单位的合法权益，促进我国互联网文化健康、有序地发展，根据《全国人民代表大会常务委员会关于维护互联网安全的决定》和《互联网信息服务管理办法》以及国家法律法规有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称互联网文化产品是指通过互联网生产、传播和流通的文化产品，主要包括： （一）专门为互联网而生产的网络音乐娱乐、网络游戏、网络演出剧（节）目、网络表演、网络艺术品、网络动漫等互联网文化产品； （二）将音乐娱乐、游戏、演出剧（节）目、表演、艺术品、动漫等文化产品以一定的技术手段制作、复制到互联网上传播的互联网文化产品。"},{"i":3,"n":"第三条","txt":"本规定所称互联网文化活动是指提供互联网文化产品及其服务的活动，主要包括： （一）互联网文化产品的制作、复制、进口、发行、播放等活动； （二）将文化产品登载在互联网上，或者通过互联网、移动通信网等信息网络发送到计算机、固定电话机、移动电话机、电视机、游戏机等用户端以及网吧等互联网上网服务营业场所，供用户浏览、欣赏、使用或者下载的在线传播行为； （三）互联网文化产品的展览、比赛等活动。 互联网文化活动分为经营性和非经营性两类。经营性互联网文化活动是指以营利为目的，通过向上网用户收费或者以电子商务、广告、赞助等方式获 取利益，提供互联网文化产品及其服务的活动。非经营性互联网文化活动是指不以营利为目的向上网用户提供互联网文化产品及其服务的活动。"},{"i":4,"n":"第四条","txt":"本规定所称互联网文化单位，是指经文化行政部门和电信管理机构批准或者备案，从事互联网文化活动的互联网信息服务提供者。 在中华人民共和国境内从事互联网文化活动，适用本规定。"},{"i":5,"n":"第五条","txt":"从事互联网文化活动应当遵守宪法和有关法律、法规，坚持为人民服务、为社会主义服务的方向，弘扬民族优秀文化，传播有益于提高公众文化素质、推动经济发展、促进社会进步的思想道德、科学技术和文化知识，丰富人民的精神生活。"},{"i":6,"n":"第六条","txt":"文化部负责制定互联网文化发展与管理的方针、政策和规划，监督管理全国互联网文化活动。 省、自治区、直辖市人民政府文化行政部门对申请从事经营性互联网文化活动的单位进行审批，对从事非经营性互联网文化活动的单位进行备案。 县级以上人民政府文化行政部门负责本行政区域内互联网文化活动的监督管理工作。县级以上人民政府文化行政部门或者文化市场综合执法机构对从事互联网文化活动违反国家有关法规的行为实施处罚。"},{"i":7,"n":"第七条","txt":"申请设立经营性互联网文化单位，应当符合《互联网信息服务管理办法》的有关规定，并具备以下条件： (一)单位的名称、住所、组织机构和章程； (二)确定的互联网文化活动范围； (三)适应互联网文化活动需要并取得相应从业资格的8名以上业务管理人员和专业技术人员； (四)适应互联网文化活动需要的设备、工作场所以及相应的经营管理技术措施； (五)不低于100万元的注册资金，其中申请从事网络游戏经营活动的应当具备不低于1000万元的注册资金； (六)符合法律、行政法规和国家有关规定的条件。 审批设立经营性互联网文化单位，除依照前款所列条件外，还应当符合互联网文化单位总量、结构和布局的规划。"},{"i":8,"n":"第八条","txt":"申请设立经营性互联网文化单位，应当向所在地省、自治区、直辖市人民政府文化行政部门提出申请，由省、自治区、直辖市人民政府文化行政部门审核批准。"},{"i":9,"n":"第九条","txt":"申请设立经营性互联网文化单位，应当提交下列文件： (一)申请书； (二)企业名称预先核准通知书或者营业执照和章程； (三)资金来源、数额及其信用证明文件； (四)法定代表人、主要负责人及主要经营管理人员、专业技术人员的资格证明和身份证明文件； (五)工作场所使用权证明文件； (六)业务发展报告； (七)依法需要提交的其他文件。 对申请设立经营性互联网文化单位的，省、自治区、直辖市人民政府文化行政部门应当自受理申请之日起20日内做出批准或者不批准的决定。批准的，核发《网络文化经营许可证》，并向社会公告；不批准的，应当书面通知申请人并说明理由。 《网络文化经营许可证》有效期为3年。有效期届满，需继续从事经营的，应当于有效期届满30日前申请续办。"},{"i":10,"n":"第十条","txt":"非经营性互联网文化单位，应当自设立之日起60日内向所在地省、自治区、直辖市人民政府文化行政部门备案，并提交下列文件： (一)备案报告书； (二)章程； (三)资金来源、数额及其信用证明文件； (四)法定代表人或者主要负责人、主要经营管理人员、专业技术人员的资格证明和身份证明文件； (五)工作场所使用权证明文件； (六)需要提交的其他文件。"},{"i":11,"n":"第十一条","txt":"申请设立经营性互联网文化单位经批准后，应当持《网络文化经营许可证》，按照《互联网信息服务管理办法》的有关规定，到所在地电信管理机构或者国务院信息产业主管部门办理相关手续。"},{"i":12,"n":"第十二条","txt":"互联网文化单位应当在其网站主页的显著位置标明文化行政部门颁发的《网络文化经营许可证》编号或者备案编号，标明国务院信息产业主管部门或者省、自治区、直辖市电信管理机构颁发的经营许可证编号或者备案编号。"},{"i":13,"n":"第十三条","txt":"经营性互联网文化单位变更单位名称、网站名称、网站域名、法定代表人、注册地址、经营地址、注册资金、股权结构以及许可经营范围的，应当自变更之日起20日内到所在地省、自治区、直辖市人民政府文化行政部门办理变更手续。 非经营性互联网文化单位变更名称、地址、法定代表人或者主要负责人、业务范围的，应当自变更之日起60日内到所在地省、自治区、直辖市人民政府文化行政部门办理备案手续。"},{"i":14,"n":"第十四条","txt":"经营性互联网文化单位终止互联网文化活动的，应当自终止之日起30日内到所在地省、自治区、直辖市人民政府文化行政部门办理注销手续。 经营性互联网文化单位自取得《网络文化经营许可证》并依法办理企业登记之日起满180日未开展互联网文化活动的，由原审核的省、自治区、直辖市人民政府文化行政部门注销《网络文化经营许可证》，同时通知相关省、自治区、直辖市电信管理机构。 非经营性互联网文化单位停止互联网文化活动的，由原备案的省、自治区、直辖市人民政府文化行政部门注销备案，同时通知相关省、自治区、直辖市电信管理机构。"},{"i":15,"n":"第十五条","txt":"经营进口互联网文化产品的活动应当由取得文化行政部门核发的《网络文化经营许可证》的经营性互联网文化单位实施，进口互联网文化产品应当报文化部进行内容审查。 文化部应当自受理内容审查申请之日起20日内（不包括专家评审所需时间）做出批准或者不批准的决定。批准的，发给批准文件；不批准的，应当说明理由。 经批准的进口互联网文化产品应当在其显著位置标明文化部的批准文号，不得擅自变更产品名称或者增删产品内容。自批准之日起一年内未在国内经营的，进口单位应当报文化部备案并说明原因；决定终止进口的，文化部撤销其批准文号。 经营性互联网文化单位经营的国产互联网文化产品应当自正式经营起30日内报省级以上文化行政部门备案，并在其显著位置标明文化部备案编号，具体办法另行规定。"},{"i":16,"n":"第十六条","txt":"互联网文化单位不得提供载有以下内容的文化产品： (一)反对宪法确定的基本原则的； (二)危害国家统一、主权和领土完整的； (三)泄露国家秘密、危害国家安全或者损害国家荣誉和利益的； (四)煽动民族仇恨、民族歧视，破坏民族团结，或者侵害民族风俗、习惯的； (五)宣扬邪教、迷信的； (六)散布谣言，扰乱社会秩序，破坏社会稳定的； (七)宣扬淫秽、赌博、暴力或者教唆犯罪的； (八)侮辱或者诽谤他人，侵害他人合法权益的； (九)危害社会公德或者民族优秀文化传统的； (十)有法律、行政法规和国家规定禁止的其他内容的。"},{"i":17,"n":"第十七条","txt":"互联网文化单位提供的文化产品，使公民、法人或者其他组织的合法利益受到侵害的，互联网文化单位应当依法承担民事责任。"},{"i":18,"n":"第十八条","txt":"互联网文化单位应当建立自审制度，明确专门部门，配备专业人员负责互联网文化产品内容和活动的自查与管理，保障互联网文化产品内容和活动的合法性。"},{"i":19,"n":"第十九条","txt":"互联网文化单位发现所提供的互联网文化产品含有本规定第十六条所列内容之一的，应当立即停止提供，保存有关记录，向所在地省、自治区、直辖市人民政府文化行政部门报告并抄报文化部。"},{"i":20,"n":"第二十条","txt":"互联网文化单位应当记录备份所提供的文化产品内容及其时间、互联网地址或者域名；记录备份应当保存60日，并在国家有关部门依法查询时予以提供。"},{"i":21,"n":"第二十一条","txt":"未经批准，擅自从事经营性互联网文化活动的，由县级以上人民政府文化行政部门或者文化市场综合执法机构依据《无照经营查处取缔办法》的规定予以查处。"},{"i":22,"n":"第二十二条","txt":"非经营性互联网文化单位违反本规定第十条，逾期未办理备案手续的，由县级以上人民政府文化行政部门或者文化市场综合执法机构责令限期改正；拒不改正的，责令停止互联网文化活动，并处1000元以下罚款。"},{"i":23,"n":"第二十三条","txt":"经营性互联网文化单位违反本规定第十二条的，由县级以上人民政府文化行政部门或者文化市场综合执法机构责令限期改正，并可根据情节轻重处10000元以下罚款。 非经营性互联网文化单位违反本规定第十二条的，由县级以上人民政府文化行政部门或者文化市场综合执法机构责令限期改正；拒不改正的，责令停止互联网文化活动，并处500元以下罚款。"},{"i":24,"n":"第二十四条","txt":"经营性互联网文化单位违反本规定第十三条的，由县级以上人民政府文化行政部门或者文化市场综合执法机构责令改正，没收违法所 得，并处10000元以上30000元以下罚款；情节严重的，责令停业整顿直至吊销《网络文化经营许可证》；构成犯罪的，依法追究刑事责任。 非经营性互联网文化单位违反本规定第十三条的，由县级以上人民政府文化行政部门或者文化市场综合执法机构责令限期改正；拒不改正的，责令停止互联网文化活动，并处1000元以下罚款。"},{"i":25,"n":"第二十五条","txt":"经营性互联网文化单位违反本规定第十五条，经营进口互联网文化产品未在其显著位置标明文化部批准文号、经营国产互联网文化产品 未在其显著位置标明文化部备案编号的，由县级以上人民政府文化行政部门或者文化市场综合执法机构责令改正，并可根据情节轻重处10000元以下罚款。"},{"i":26,"n":"第二十六条","txt":"经营性互联网文化单位违反本规定第十五条，擅自变更进口互联网文化产品的名称或者增删内容的，由县级以上人民政府文化行政部门 或者文化市场综合执法机构责令停止提供，没收违法所得，并处10000元以上30000元以下罚款；情节严重的，责令停业整顿直至吊销《网络文化经营许可 证》；构成犯罪的，依法追究刑事责任。"},{"i":27,"n":"第二十七条","txt":"经营性互联网文化单位违反本规定第十五条，经营国产互联网文化产品逾期未报文化行政部门备案的，由县级以上人民政府文化行政部门或者文化市场综合执法机构责令改正，并可根据情节轻重处20000元以下罚款。"},{"i":28,"n":"第二十八条","txt":"经营性互联网文化单位提供含有本规定第十六条禁止内容的互联网文化产品，或者提供未经文化部批准进口的互联网文化产品的，由县 级以上人民政府文化行政部门或者文化市场综合执法机构责令停止提供，没收违法所得，并处10000元以上30000元以下罚款；情节严重的，责令停业整顿 直至吊销《网络文化经营许可证》；构成犯罪的，依法追究刑事责任。 非经营性互联网文化单位，提供含有本规定第十六条禁止内容的互联网文化产品，或者提供未经文化部批准进口的互联网文化产品的，由县级以上人民政府文化行政部门或者文化市场综合执法机构责令停止提供，处1000元以下罚款；构成犯罪的，依法追究刑事责任。"},{"i":29,"n":"第二十九条","txt":"经营性互联网文化单位违反本规定第十八条的，由县级以上人民政府文化行政部门或者文化市场综合执法机构责令改正，并可根据情节轻重处20000元以下罚款。"},{"i":30,"n":"第三十条","txt":"经营性互联网文化单位违反本规定第十九条的，由县级以上人民政府文化行政部门或者文化市场综合执法机构予以警告，责令限期改正，并处10000元以下罚款。"},{"i":31,"n":"第三十一条","txt":"违反本规定第二十条的，由省、自治区、直辖市电信管理机构责令改正；情节严重的，由省、自治区、直辖市电信管理机构责令停业整顿或者责令暂时关闭网站。"},{"i":32,"n":"第三十二条","txt":"本规定所称文化市场综合执法机构是指依照国家有关法律、法规和规章的规定，相对集中地行使文化领域行政处罚权以及相关监督检查权、行政强制权的行政执法机构。"},{"i":33,"n":"第三十三条","txt":"文化行政部门或者文化市场综合执法机构查处违法经营活动，依照实施违法经营行为的企业注册地或者企业实际经营地进行管辖；企业 注册地和实际经营地无法确定的，由从事违法经营活动网站的信息服务许可地或者备案地进行管辖；没有许可或者备案的，由该网站服务器所在地管辖；网站服务器 设置在境外的，由违法行为发生地进行管辖。"},{"i":34,"n":"第三十四条","txt":"本规定自2011年4月1日起施行。2003年5月10日发布、2004年7月1日修订的《互联网文化管理暂行规定》同时废止。"}],"hulianwangxinwenxinxifuwuguanliguiding":[{"i":1,"n":"第一条","txt":"为加强互联网信息内容管理，促进互联网新闻信息服务健康有序发展，根据《中华人民共和国网络安全法》、《互联网信息服务管理办法》、《国务院关于授权国家互联网信息办公室负责互联网信息内容管理工作的通知》，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内提供互联网新闻信息服务，适用本规定。 本规定所称新闻信息，包括有关政治、经济、军事、外交等社会公共事务的报道、评论，以及有关社会突发事件的报道、评论。"},{"i":3,"n":"第三条","txt":"提供互联网新闻信息服务，应当遵守宪法、法律和行政法规，坚持为人民服务、为社会主义服务的方向，坚持正确舆论导向，发挥舆论监督作用，促进形成积极健康、向上向善的网络文化，维护国家利益和公共利益。"},{"i":4,"n":"第四条","txt":"国家互联网信息办公室负责全国互联网新闻信息服务的监督管理执法工作。地方互联网信息办公室依据职责负责本行政区域内互联网新闻信息服务的监督管理执法工作。"},{"i":5,"n":"第五条","txt":"通过互联网站、应用程序、论坛、博客、微博客、公众账号、即时通信工具、网络直播等形式向社会公众提供互联网新闻信息服务，应当取得互联网新闻信息服务许可，禁止未经许可或超越许可范围开展互联网新闻信息服务活动。 前款所称互联网新闻信息服务，包括互联网新闻信息采编发布服务、转载服务、传播平台服务。"},{"i":6,"n":"第六条","txt":"申请互联网新闻信息服务许可，应当具备下列条件： （一）在中华人民共和国境内依法设立的法人； （二）主要负责人、总编辑是中国公民； （三）有与服务相适应的专职新闻编辑人员、内容审核人员和技术保障人员； （四）有健全的互联网新闻信息服务管理制度； （五）有健全的信息安全管理制度和安全可控的技术保障措施； （六）有与服务相适应的场所、设施和资金。 申请互联网新闻信息采编发布服务许可的，应当是新闻单位（含其控股的单位）或新闻宣传部门主管的单位。 符合条件的互联网新闻信息服务提供者实行特殊管理股制度，具体实施办法由国家互联网信息办公室另行制定。 提供互联网新闻信息服务，还应当依法向电信主管部门办理互联网信息服务许可或备案手续。"},{"i":7,"n":"第七条","txt":"任何组织不得设立中外合资经营、中外合作经营和外资经营的互联网新闻信息服务单位。 互联网新闻信息服务单位与境内外中外合资经营、中外合作经营和外资经营的企业进行涉及互联网新闻信息服务业务的合作，应当报经国家互联网信息办公室进行安全评估。"},{"i":8,"n":"第八条","txt":"互联网新闻信息服务提供者的采编业务和经营业务应当分开，非公有资本不得介入互联网新闻信息采编业务。"},{"i":9,"n":"第九条","txt":"申请互联网新闻信息服务许可，申请主体为中央新闻单位（含其控股的单位）或中央新闻宣传部门主管的单位的，由国家互联网信息办公室受理和决定；申请主体为地方新闻单位（含其控股的单位）或地方新闻宣传部门主管的单位的，由省、自治区、直辖市互联网信息办公室受理和决定；申请主体为其他单位的，经所在地省、自治区、直辖市互联网信息办公室受理和初审后，由国家互联网信息办公室决定。 国家或省、自治区、直辖市互联网信息办公室决定批准的，核发《互联网新闻信息服务许可证》。《互联网新闻信息服务许可证》有效期为3年。有效期届满，需继续从事互联网新闻信息服务活动的，应当于有效期届满30日前申请续办。 省、自治区、直辖市互联网信息办公室应当定期向国家互联网信息办公室报告许可受理和决定情况。"},{"i":10,"n":"第十条","txt":"申请互联网新闻信息服务许可，应当提交下列材料： （一）主要负责人、总编辑为中国公民的证明； （二）专职新闻编辑人员、内容审核人员和技术保障人员的资质情况； （三）互联网新闻信息服务管理制度； （四）信息安全管理制度和技术保障措施； （五）互联网新闻信息服务安全评估报告； （六）法人资格、场所、资金和股权结构等证明； （七）法律法规规定的其他材料。"},{"i":11,"n":"第十一条","txt":"互联网新闻信息服务提供者应当设立总编辑，总编辑对互联网新闻信息内容负总责。总编辑人选应当具有相关从业经验，符合相关条件，并报国家或省、自治区、直辖市互联网信息办公室备案。 互联网新闻信息服务相关从业人员应当依法取得相应资质，接受专业培训、考核。互联网新闻信息服务相关从业人员从事新闻采编活动，应当具备新闻采编人员职业资格，持有国家新闻出版广电总局统一颁发的新闻记者证。"},{"i":12,"n":"第十二条","txt":"互联网新闻信息服务提供者应当健全信息发布审核、公共信息巡查、应急处置等信息安全管理制度，具有安全可控的技术保障措施。"},{"i":13,"n":"第十三条","txt":"互联网新闻信息服务提供者为用户提供互联网新闻信息传播平台服务，应当按照《中华人民共和国网络安全法》的规定，要求用户提供真实身份信息。用户不提供真实身份信息的，互联网新闻信息服务提供者不得为其提供相关服务。 互联网新闻信息服务提供者对用户身份信息和日志信息负有保密的义务，不得泄露、篡改、毁损，不得出售或非法向他人提供。 互联网新闻信息服务提供者及其从业人员不得通过采编、发布、转载、删除新闻信息，干预新闻信息呈现或搜索结果等手段谋取不正当利益。"},{"i":14,"n":"第十四条","txt":"互联网新闻信息服务提供者提供互联网新闻信息传播平台服务，应当与在其平台上注册的用户签订协议，明确双方权利义务。 对用户开设公众账号的，互联网新闻信息服务提供者应当审核其账号信息、服务资质、服务范围等信息，并向所在地省、自治区、直辖市互联网信息办公室分类备案。"},{"i":15,"n":"第十五条","txt":"互联网新闻信息服务提供者转载新闻信息，应当转载中央新闻单位或省、自治区、直辖市直属新闻单位等国家规定范围内的单位发布的新闻信息，注明新闻信息来源、原作者、原标题、编辑真实姓名等，不得歪曲、篡改标题原意和新闻信息内容，并保证新闻信息来源可追溯。 互联网新闻信息服务提供者转载新闻信息，应当遵守著作权相关法律法规的规定，保护著作权人的合法权益。"},{"i":16,"n":"第十六条","txt":"互联网新闻信息服务提供者和用户不得制作、复制、发布、传播法律、行政法规禁止的信息内容。 互联网新闻信息服务提供者提供服务过程中发现含有违反本规定第三条或前款规定内容的，应当依法立即停止传输该信息、采取消除等处置措施，保存有关记录，并向有关主管部门报告。"},{"i":17,"n":"第十七条","txt":"互联网新闻信息服务提供者变更主要负责人、总编辑、主管单位、股权结构等影响许可条件的重大事项，应当向原许可机关办理变更手续。 互联网新闻信息服务提供者应用新技术、调整增设具有新闻舆论属性或社会动员能力的应用功能，应当报国家或省、自治区、直辖市互联网信息办公室进行互联网新闻信息服务安全评估。"},{"i":18,"n":"第十八条","txt":"互联网新闻信息服务提供者应当在明显位置明示互联网新闻信息服务许可证编号。 互联网新闻信息服务提供者应当自觉接受社会监督，建立社会投诉举报渠道，设置便捷的投诉举报入口，及时处理公众投诉举报。"},{"i":19,"n":"第十九条","txt":"国家和地方互联网信息办公室应当建立日常检查和定期检查相结合的监督管理制度，依法对互联网新闻信息服务活动实施监督检查，有关单位、个人应当予以配合。 国家和地方互联网信息办公室应当健全执法人员资格管理制度。执法人员开展执法活动，应当依法出示执法证件。"},{"i":20,"n":"第二十条","txt":"任何组织和个人发现互联网新闻信息服务提供者有违反本规定行为的，可以向国家和地方互联网信息办公室举报。 国家和地方互联网信息办公室应当向社会公开举报受理方式，收到举报后，应当依法予以处置。互联网新闻信息服务提供者应当予以配合。"},{"i":21,"n":"第二十一条","txt":"国家和地方互联网信息办公室应当建立互联网新闻信息服务网络信用档案，建立失信黑名单制度和约谈制度。 国家互联网信息办公室会同国务院电信、公安、新闻出版广电等部门建立信息共享机制，加强工作沟通和协作配合，依法开展联合执法等专项监督检查活动。"},{"i":22,"n":"第二十二条","txt":"违反本规定第五条规定，未经许可或超越许可范围开展互联网新闻信息服务活动的，由国家和省、自治区、直辖市互联网信息办公室依据职责责令停止相关服务活动，处1万元以上3万元以下罚款。"},{"i":23,"n":"第二十三条","txt":"互联网新闻信息服务提供者运行过程中不再符合许可条件的，由原许可机关责令限期改正；逾期仍不符合许可条件的，暂停新闻信息更新；《互联网新闻信息服务许可证》有效期届满仍不符合许可条件的，不予换发许可证。"},{"i":24,"n":"第二十四条","txt":"互联网新闻信息服务提供者违反本规定第七条第二款、第八条、第十一条、第十二条、第十三条第三款、第十四条、第十五条第一款、第十七条、第十八条规定的，由国家和地方互联网信息办公室依据职责给予警告，责令限期改正；情节严重或拒不改正的，暂停新闻信息更新，处5000元以上3万元以下罚款；构成犯罪的，依法追究刑事责任。"},{"i":25,"n":"第二十五条","txt":"互联网新闻信息服务提供者违反本规定第三条、第十六条第一款、第十九条第一款、第二十条第二款规定的，由国家和地方互联网信息办公室依据职责给予警告，责令限期改正；情节严重或拒不改正的，暂停新闻信息更新，处2万元以上3万元以下罚款；构成犯罪的，依法追究刑事责任。"},{"i":26,"n":"第二十六条","txt":"互联网新闻信息服务提供者违反本规定第十三条第一款、第十六条第二款规定的，由国家和地方互联网信息办公室根据《中华人民共和国网络安全法》的规定予以处理。"},{"i":27,"n":"第二十七条","txt":"本规定所称新闻单位，是指依法设立的报刊社、广播电台、电视台、通讯社和新闻电影制片厂。"},{"i":28,"n":"第二十八条","txt":"违反本规定，同时违反互联网信息服务管理规定的，由国家和地方互联网信息办公室根据本规定处理后，转由电信主管部门依法处置。 国家对互联网视听节目服务、网络出版服务等另有规定的，应当同时符合其规定。"},{"i":29,"n":"第二十九条","txt":"本规定自2017年6月1日起施行。本规定施行之前颁布的有关规定与本规定不一致的，按照本规定执行。"}],"hulianwangyonghuzhanghaoxinxiguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强对互联网用户账号信息的管理，弘扬社会主义核心价值观，维护国家安全和社会公共利益，保护公民、法人和其他组织的合法权益，根据《中华人民共和国网络安全法》、《中华人民共和国个人信息保护法》、《互联网信息服务管理办法》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"互联网用户在中华人民共和国境内的互联网信息服务提供者注册、使用互联网用户账号信息及其管理工作，适用本规定。法律、行政法规另有规定的，依照其规定。"},{"i":3,"n":"第三条","txt":"国家网信部门负责全国互联网用户账号信息的监督管理工作。 地方网信部门依据职责负责本行政区域内的互联网用户账号信息的监督管理工作。"},{"i":4,"n":"第四条","txt":"互联网用户注册、使用和互联网信息服务提供者管理互联网用户账号信息，应当遵守法律法规，遵循公序良俗，诚实信用，不得损害国家安全、社会公共利益或者他人合法权益。"},{"i":5,"n":"第五条","txt":"鼓励相关行业组织加强行业自律，建立健全行业标准、行业准则和自律管理制度，督促指导互联网信息服务提供者制定完善服务规范、加强互联网用户账号信息安全管理、依法提供服务并接受社会监督。"},{"i":6,"n":"第六条","txt":"互联网信息服务提供者应当依照法律、行政法规和国家有关规定，制定和公开互联网用户账号管理规则、平台公约，与互联网用户签订服务协议，明确账号信息注册、使用和管理相关权利义务。"},{"i":7,"n":"第七条","txt":"互联网个人用户注册、使用账号信息，含有职业信息的，应当与个人真实职业信息相一致。 互联网机构用户注册、使用账号信息，应当与机构名称、标识等相一致，与机构性质、经营范围和所属行业类型等相符合。"},{"i":8,"n":"第八条","txt":"互联网用户注册、使用账号信息，不得有下列情形： （一）违反《网络信息内容生态治理规定》第六条、第七条规定； （二）假冒、仿冒、捏造政党、党政军机关、企事业单位、人民团体和社会组织的名称、标识等； （三）假冒、仿冒、捏造国家（地区）、国际组织的名称、标识等； （四）假冒、仿冒、捏造新闻网站、报刊社、广播电视机构、通讯社等新闻媒体的名称、标识等，或者擅自使用“新闻”、“报道”等具有新闻属性的名称、标识等； （五）假冒、仿冒、恶意关联国家行政区域、机构所在地、标志性建筑物等重要空间的地理名称、标识等； （六）以损害公共利益或者谋取不正当利益等为目的，故意夹带二维码、网址、邮箱、联系方式等，或者使用同音、谐音、相近的文字、数字、符号和字母等； （七）含有名不副实、夸大其词等可能使公众受骗或者产生误解的内容； （八）含有法律、行政法规和国家有关规定禁止的其他内容。"},{"i":9,"n":"第九条","txt":"互联网信息服务提供者为互联网用户提供信息发布、即时通讯等服务的，应当对申请注册相关账号信息的用户进行基于移动电话号码、身份证件号码或者统一社会信用代码等方式的真实身份信息认证。用户不提供真实身份信息，或者冒用组织机构、他人身份信息进行虚假注册的，不得为其提供相关服务。"},{"i":10,"n":"第十条","txt":"互联网信息服务提供者应当对互联网用户在注册时提交的和使用中拟变更的账号信息进行核验，发现违反本规定第七条、第八条规定的，应当不予注册或者变更账号信息。 对账号信息中含有“中国”、“中华”、“中央”、“全国”、“国家”等内容，或者含有党旗、党徽、国旗、国歌、国徽等党和国家象征和标志的，应当依照法律、行政法规和国家有关规定从严核验。 互联网信息服务提供者应当采取必要措施，防止被依法依约关闭的账号重新注册；对注册与其关联度高的账号信息，应当对相关信息从严核验。"},{"i":11,"n":"第十一条","txt":"对于互联网用户申请注册提供互联网新闻信息服务、网络出版服务等依法需要取得行政许可的互联网信息服务的账号，或者申请注册从事经济、教育、医疗卫生、司法等领域信息内容生产的账号，互联网信息服务提供者应当要求其提供服务资质、职业资格、专业背景等相关材料，予以核验并在账号信息中加注专门标识。"},{"i":12,"n":"第十二条","txt":"互联网信息服务提供者应当在互联网用户账号信息页面展示合理范围内的互联网用户账号的互联网协议（IP）地址归属地信息，便于公众为公共利益实施监督。"},{"i":13,"n":"第十三条","txt":"互联网信息服务提供者应当在互联网用户公众账号信息页面，展示公众账号的运营主体、注册运营地址、内容生产类别、统一社会信用代码、有效联系方式、互联网协议（IP）地址归属地等信息。"},{"i":14,"n":"第十四条","txt":"互联网信息服务提供者应当履行互联网用户账号信息管理主体责任，配备与服务规模相适应的专业人员和技术能力，建立健全并严格落实真实身份信息认证、账号信息核验、信息内容安全、生态治理、应急处置、个人信息保护等管理制度。"},{"i":15,"n":"第十五条","txt":"互联网信息服务提供者应当建立账号信息动态核验制度，适时核验存量账号信息，发现不符合本规定要求的，应当暂停提供服务并通知用户限期改正；拒不改正的，应当终止提供服务。"},{"i":16,"n":"第十六条","txt":"互联网信息服务提供者应当依法保护和处理互联网用户账号信息中的个人信息，并采取措施防止未经授权的访问以及个人信息泄露、篡改、丢失。"},{"i":17,"n":"第十七条","txt":"互联网信息服务提供者发现互联网用户注册、使用账号信息违反法律、行政法规和本规定的，应当依法依约采取警示提醒、限期改正、限制账号功能、暂停使用、关闭账号、禁止重新注册等处置措施，保存有关记录，并及时向网信等有关主管部门报告。"},{"i":18,"n":"第十八条","txt":"互联网信息服务提供者应当建立健全互联网用户账号信用管理体系，将账号信息相关信用评价作为账号信用管理的重要参考指标，并据以提供相应服务。"},{"i":19,"n":"第十九条","txt":"互联网信息服务提供者应当在显著位置设置便捷的投诉举报入口，公布投诉举报方式，健全受理、甄别、处置、反馈等机制，明确处理流程和反馈时限，及时处理用户和公众投诉举报。"},{"i":20,"n":"第二十条","txt":"网信部门会同有关主管部门，建立健全信息共享、会商通报、联合执法、案件督办等工作机制，协同开展互联网用户账号信息监督管理工作。"},{"i":21,"n":"第二十一条","txt":"网信部门依法对互联网信息服务提供者管理互联网用户注册、使用账号信息情况实施监督检查。互联网信息服务提供者应当予以配合，并提供必要的技术、数据等支持和协助。 发现互联网信息服务提供者存在较大网络信息安全风险的，省级以上网信部门可以要求其采取暂停信息更新、用户账号注册或者其他相关服务等措施。互联网信息服务提供者应当按照要求采取措施，进行整改，消除隐患。"},{"i":22,"n":"第二十二条","txt":"互联网信息服务提供者违反本规定的，依照有关法律、行政法规的规定处罚。法律、行政法规没有规定的，由省级以上网信部门依据职责给予警告、通报批评，责令限期改正，并可以处一万元以上十万元以下罚款。构成违反治安管理行为的，移交公安机关处理；构成犯罪的，移交司法机关处理。"},{"i":23,"n":"第二十三条","txt":"本规定下列用语的含义是： （一）互联网用户账号信息，是指互联网用户在互联网信息服务中注册、使用的名称、头像、封面、简介、签名、认证信息等用于标识用户账号的信息。 （二）互联网信息服务提供者，是指向用户提供互联网信息发布和应用平台服务，包括但不限于互联网新闻信息服务、网络出版服务、搜索引擎、即时通讯、交互式信息服务、网络直播、应用软件下载等互联网服务的主体。"},{"i":24,"n":"第二十四条","txt":"本规定自2022年8月1日施行。本规定施行之前颁布的有关规定与本规定不一致的，按照本规定执行。"}],"hulianwangdengxinxiwangluochuanboshitingjiemuguanlc9b031":[{"i":1,"n":"第一条","txt":"为规范互联网等信息网络传播视听节目秩序，加强监督管理，促进社会主义精神文明建设，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于以互联网协议（IP）作为主要技术形态，以计算机、电视机、手机等各类电子设备为接收终端，通过移动通信网、固定通信网、微波通信网、有线电视网、卫星或其他城域网、广域网、局域网等信息网络，从事开办、播放（含点播、转播、直播）、集成、传输、下载视听节目服务等活动。 本办法所称视听节目（包括影视类音像制品），是指利用摄影机、摄像机、录音机和其它视音频摄制设备拍摄、录制的，由可连续运动的图像或可连续收听的声音组成的视音频节目。"},{"i":3,"n":"第三条","txt":"国家广播电影电视总局（以下简称广电总局）负责全国互联网等信息网络传播视听节目（以下简称信息网络传播视听节目）的管理工作。县级以上地方广播电视行政部门负责本辖区内互联网等信息网络传播视听节目的管理工作。"},{"i":4,"n":"第四条","txt":"国家对从事信息网络传播视听节目业务实行许可制度。"},{"i":5,"n":"第五条","txt":"国家鼓励地（市）级以上广播电台、电视台通过国际互联网传播视听节目。"},{"i":6,"n":"第六条","txt":"从事信息网络传播视听节目业务，应取得《信息网络传播视听节目许可证》。 《信息网络传播视听节目许可证》由广电总局按照信息网络传播视听节目的业务类别、接收终端、传输网络等项目分类核发。 业务类别分为播放自办节目、转播节目和提供节目集成运营服务等。 接收终端分为计算机、电视机、手机及其它各类电子设备。 传输网络分为移动通信网、固定通信网、微波通信网、有线电视网、卫星或其他城域网、广域网、局域网等。"},{"i":7,"n":"第七条","txt":"外商独资、中外合资、中外合作机构，不得从事信息网络传播视听节目业务。 经广电总局批准设立的广播电台、电视台或依法享有互联网新闻发布资格的网站可以申请开办信息网络传播新闻类视听节目业务，其他机构和个人不得开办信息网络传播新闻类视听节目业务。 经广电总局批准设立的省、自治区、直辖市及省会市、计划单列市级以上广播电台、电视台、广播影视集团（总台），可以申请自行或设立机构从事以电视机作为接收终端的信息网络传播视听节目集成运营服务。其他机构和个人不得开办此类业务。"},{"i":8,"n":"第八条","txt":"申请《信息网络传播视听节目许可证》，应当具备下列条件： （一）符合广电总局确定的信息网络传播视听节目的总体规划和布局； （二）符合国家规定的行业规范和技术标准； （三）有与业务规模相适应的自有资金、设备、场所及必要的专业人员； （四）拥有与业务规模相适应并符合国家规定的视听节目资源； （五）拥有与业务规模相适应的服务信誉、技术能力和网络资源； （六）有健全的节目内容审查制度、播出管理制度； （七）有可行的节目监控方案； （八）其他法律、行政法规规定的条件。"},{"i":9,"n":"第九条","txt":"申请《信息网络传播视听节目许可证》，须提交以下材料： （一）申请报告，内容应包括：业务类别（自办节目、转播、集成等）、播出标识（从事信息网络传播视听节目业务的专用标识）、传播方式（频道播出、点播、下载定制、轮播、数据广播等）、传输网络、传播载体、传播范围、接收终端、节目类别、集成内容等； （二）《信息网络传播视听节目许可证》申请表； （三）从事信息网络传播视听节目业务的内容规划、技术方案、运营方案、管理制度； （四）向政府监管部门提供监控信号的监控方案； （五）人员、设备、场所的证明资料； （六）申办机构的基本情况及与开展业务有关的证明（网站注册文件、广播电台、电视台许可证、广播电视节目制作经营许可证、从事登载新闻业务许可文件等）； （七）公司章程、营业执照、验资证明（申请人为企业的）。"},{"i":10,"n":"第十条","txt":"申请《信息网络传播视听节目许可证》的机构，应向所在地县级以上广播电视行政部门提出申请，并提交符合第九条规定的书面材料，经逐级审核同意后，报广电总局审批。中央所属企事业单位，可直接向广电总局提出申请。符合条件的，广电总局予以颁发《信息网络传播视听节目许可证》。"},{"i":11,"n":"第十一条","txt":"负责受理的广播电视行政部门应按照行政许可法规定的期限和权限，履行受理、审核职责。申请人的申请符合法定标准的，有权作出决定的广播电视行政部门应作出准予行政许可的书面决定。依法作出不予行政许可决定的，应当书面通知申请人并说明理由。"},{"i":12,"n":"第十二条","txt":"《信息网络传播视听节目许可证》有效期为二年。有效期届满，需继续从事信息网络传播视听节目业务的，应于期满六个月前按本办法规定的审批程序办理续办手续。"},{"i":13,"n":"第十三条","txt":"获得《信息网络传播视听节目许可证》的机构（以下简称持证机构）应当按照《信息网络传播视听节目许可证》载明的开办主体、业务类别、标识、传播方式、传输网络、传播载体、传播范围、接收终端、节目类别和集成内容等事项从事信息网络传播视听节目业务。"},{"i":14,"n":"第十四条","txt":"持证机构变更注册资本、股东和持股比例及许可证载明的开办主体、业务类别、标识、传播方式、传播载体、传播范围、接收终端、节目类别和集成内容等事项的，应提前六十日报广电总局批准并办理许可证登载事项变更手续。 持证机构地址、网址、网站名、法定代表人等事项发生变更的，应当在变更后三十日内向广电总局备案并办理许可证登载事项变更手续。"},{"i":15,"n":"第十五条","txt":"持证机构应当在领取《信息网络传播视听节目许可证》九十日内开通业务。如因特殊理由不能如期开通，应经发证机关同意，否则按终止业务处理。"},{"i":16,"n":"第十六条","txt":"持有《信息网络传播视听节目许可证》的机构需终止业务的，应提前六十日向原发证机关申报，其《信息网络传播视听节目许可证》由原发证机关予以公告注销。"},{"i":17,"n":"第十七条","txt":"用于通过信息网络向公众传播的新闻类视听节目，限于境内广播电台、电视台、广播电视台以及经批准的新闻网站制作、播放的节目。 用于通过信息网络向公众传播的影视剧类视听节目，必须取得《电视剧发行许可证》、《电影公映许可证》。"},{"i":18,"n":"第十八条","txt":"通过信息网络传播视听节目，应符合《著作权法》的规定。"},{"i":19,"n":"第十九条","txt":"禁止通过信息网络传播有以下内容的视听节目： （一）反对宪法确定的基本原则的； （二）危害国家统一、主权和领土完整的； （三）泄露国家秘密、危害国家安全或者损害国家荣誉和利益的； （四）煽动民族仇恨、民族歧视，破坏民族团结，或者侵害民族风俗、习惯的； （五）宣扬邪教、迷信的； （六）扰乱社会秩序，破坏社会稳定的； （七）宣扬淫秽、赌博、暴力或者教唆犯罪的； （八）侮辱或者诽谤他人，侵害他人合法权益的； （九）危害社会公德或者民族优秀文化传统的； （十）有法律、行政法规和国家规定禁止的其他内容的。"},{"i":20,"n":"第二十条","txt":"持证机构应建立健全节目审查、安全播出的管理制度，实行节目总编负责制，配备节目审查员，对其播放的节目内容进行审查。"},{"i":21,"n":"第二十一条","txt":"信息网络的经营机构不得向未持有《信息网络传播视听节目许可证》的机构提供与传播视听节目业务有关的服务。"},{"i":22,"n":"第二十二条","txt":"传播视听节目的名称、内容概要、播出时间、时长、来源等信息，持证机构应当至少保留三十日。"},{"i":23,"n":"第二十三条","txt":"利用信息网络转播视听节目，只能转播广播电台、电视台播出的广播电视节目，不得转播非法开办的广播电视节目，不得转播境外广播电视节目。 利用信息网络链接或集成视听节目，只能链接或集成取得《信息网络传播视听节目许可证》机构开办的视听节目，不得链接或集成境外互联网站的视听节目。"},{"i":24,"n":"第二十四条","txt":"省级以上广播电视行政部门应设立视听节目监控系统、建立公众监督举报制度，加强对信息网络传播视听节目的监督管理。 持证机构应当为视听节目监控系统提供必要的信号接入条件。"},{"i":25,"n":"第二十五条","txt":"违反本办法规定，未经批准，擅自从事信息网络传播视听节目业务的，由县级以上广播电视行政部门予以取缔，可以并处一万元以上三万元以下的罚款；构成犯罪的，依法追究刑事责任。"},{"i":26,"n":"第二十六条","txt":"违反本办法规定，有下列行为之一的，由县级以上广播电视行政部门责令停止违法活动、给予警告、限期整改，可以并处三万元以下的罚款：构成犯罪的，依法追究刑事责任。 （一）未按《信息网络传播视听节目许可证》载明的事项从事信息网络传播视听节目业务的； （二）未经批准，擅自变更许可证载明事项、持证机构注册资本、股东和持股比例； （三）违反本办法第十六条、第十八条规定的； （四）传播本办法第十九条规定禁止传播的视听节目的； （五）向未持有《信息网络传播视听节目许可证》的机构提供与传播视听节目业务有关服务的； （六）未按规定保留视听节目播放记录的； （七）利用信息网络转播境外广播电视节目，转播非法开办的广播电视节目的； （八）非法链接、集成境外广播电视节目以及非法链接、集成境外网站传播的视听节目的。"},{"i":27,"n":"第二十七条","txt":"违反本办法规定，开办机构的法定代表人、节目总编或节目审查员未履行应尽职责，出现三次以上违规内容的，省级以上广播电视行政部门对开办机构予以警告，可以并处一千元以下罚款。"},{"i":28,"n":"第二十八条","txt":"本办法实施前已领取《网上传播视听节目许可证》的机构，应在本办法实施之日起六个月内按照本办法规定申换许可证。"},{"i":29,"n":"第二十九条","txt":"本办法自2004年10月11日起施行。广电总局《互联网等信息网络传播视听节目管理办法》（广电总局令第15号）同时废止。"}],"hulianwangshitingjiemufuwuguanliguiding-2":[{"i":1,"n":"第一条","txt":"为维护国家利益和公共利益，保护公众和互联网视听节目服务单位的合法权益，规范互联网视听节目服务秩序，促进健康有序发展，根据国家有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内向公众提供互联网（含移动互联网，以下简称互联网）视听节目服务活动，适用本规定。 本规定所称互联网视听节目服务，是指制作、编辑、集成并通过互联网向公众提供视音频节目，以及为他人提供上载传播视听节目服务的活动。"},{"i":3,"n":"第三条","txt":"国务院广播电影电视主管部门作为互联网视听节目服务的行业主管部门，负责对互联网视听节目服务实施监督管理，统筹互联网视听节目服务的产业发展、行业管理、内容建设和安全监管。国务院信息产业主管部门作为互联网行业主管部门，依据电信行业管理职责对互联网视听节目服务实施相应的监督管理。 地方人民政府广播电影电视主管部门和地方电信管理机构依据各自职责对本行政区域内的互联网视听节目服务单位及接入服务实施相应的监督管理。"},{"i":4,"n":"第四条","txt":"互联网视听节目服务单位及其相关网络运营单位，是重要的网络文化建设力量，承担建设中国特色网络文化和维护网络文化信息安全的责任,应自觉遵守宪法、法律和行政法规，接受互联网视听节目服务行业主管部门和互联网行业主管部门的管理。"},{"i":5,"n":"第五条","txt":"互联网视听节目服务单位组成的全国性社会团体，负责制定行业自律规范，倡导文明上网、文明办网，营造文明健康的网络环境，传播健康有益视听节目，抵制腐朽落后思想文化传播，并在国务院广播电影电视主管部门指导下开展活动。"},{"i":6,"n":"第六条","txt":"发展互联网视听节目服务要有益于传播社会主义先进文化，推动社会全面进步和人的全面发展、促进社会和谐。从事互联网视听节目服务，应当坚持为人民服务、为社会主义服务，坚持正确导向，把社会效益放在首位，建设社会主义核心价值体系，遵守社会主义道德规范，大力弘扬体现时代发展和社会进步的思想文化，大力弘扬民族优秀文化传统，提供更多更好的互联网视听节目服务，满足人民群众日益增长的需求，不断丰富人民群众的精神文化生活，充分发挥文化滋润心灵、陶冶情操、愉悦身心的作用，为青少年成长创造良好的网上空间，形成共建共享的精神家园。"},{"i":7,"n":"第七条","txt":"从事互联网视听节目服务，应当依照本规定取得广播电影电视主管部门颁发的《信息网络传播视听节目许可证》（以下简称《许可证》）或履行备案手续。 未按照本规定取得广播电影电视主管部门颁发的《许可证》或履行备案手续，任何单位和个人不得从事互联网视听节目服务。 互联网视听节目服务业务指导目录由国务院广播电影电视主管部门商国务院信息产业主管部门制定。"},{"i":8,"n":"第八条","txt":"申请从事互联网视听节目服务的，应当同时具备以下条件： （一）具备法人资格，为国有独资或国有控股单位，且在申请之日前三年内无违法违规记录； （二）有健全的节目安全传播管理制度和安全保护技术措施； （三）有与其业务相适应并符合国家规定的视听节目资源； （四）有与其业务相适应的技术能力、网络资源和资金，且资金来源合法； （五）有与其业务相适应的专业人员，且主要出资者和经营者在申请之日前三年内无违法违规记录； （六）技术方案符合国家标准、行业标准和技术规范； （七）符合国务院广播电影电视主管部门确定的互联网视听节目服务总体规划、布局和业务指导目录； （八）符合法律、行政法规和国家有关规定的条件。"},{"i":9,"n":"第九条","txt":"从事广播电台、电视台形态服务和时政类视听新闻服务的，除符合本规定第八条规定外，还应当持有广播电视播出机构许可证或互联网新闻信息服务许可证。其中，以自办频道方式播放视听节目的，由地（市）级以上广播电台、电视台、中央新闻单位提出申请。 从事主持、访谈、报道类视听服务的，除符合本规定第八条规定外，还应当持有广播电视节目制作经营许可证和互联网新闻信息服务许可证；从事自办网络剧（片）类服务的，还应当持有广播电视节目制作经营许可证。 未经批准，任何组织和个人不得在互联网上使用广播电视专有名称开展业务。"},{"i":10,"n":"第十条","txt":"申请《许可证》，应当通过省、自治区、直辖市人民政府广播电影电视主管部门向国务院广播电影电视主管部门提出申请，中央直属单位可以直接向国务院广播电影电视主管部门提出申请。 省、自治区、直辖市人民政府广播电影电视主管部门应当提供便捷的服务，自收到申请之日起20日内提出初审意见，报国务院广播电影电视主管部门审批；国务院广播电影电视主管部门应当自收到申请或者初审意见之日起40日内作出许可或者不予许可的决定，其中专家评审时间为20日。予以许可的，向申请人颁发《许可证》，并向社会公告；不予许可的，应当书面通知申请人并说明理由。《许可证》应当载明互联网视听节目服务的播出标识、名称、服务类别等事项。 《许可证》有效期为3年。有效期届满，需继续从事互联网视听节目服务的，应于有效期届满前30日内，持符合本办法第八条规定条件的相关材料，向原发证机关申请办理续办手续。 地（市）级以上广播电台、电视台从事互联网视"},{"i":11,"n":"第十一条","txt":"取得《许可证》的单位，应当依据《互联网信息服务管理办法》，向省（自治区、直辖市）电信管理机构或国务院信息产业主管部门（以下简称电信主管部门）申请办理电信业务经营许可或者履行相关备案手续，并依法到工商行政管理部门办理注册登记或变更登记手续。电信主管部门应根据广播电影电视主管部门许可，严格互联网视听节目服务单位的域名和IP地址管理。"},{"i":12,"n":"第十二条","txt":"互联网视听节目服务单位变更注册资本、股东、股权结构，有重大资产变动或有上市等重大融资行为的，以及业务项目超出《许可证》载明范围的，应按本规定办理审批手续。互联网视听节目服务单位的办公场所、法定代表人以及互联网信息服务单位的网址、网站名依法变更的，应当在变更后15日内向省级以上广播电影电视主管部门和电信主管部门备案,变更事项涉及工商登记的，应当依法到工商行政管理部门办理变更登记手续。"},{"i":13,"n":"第十三条","txt":"互联网视听节目服务单位应当在取得《许可证》90日内提供互联网视听节目服务。未按期提供服务的，其《许可证》由原发证机关予以注销。如因特殊原因，应经发证机关同意。申请终止服务的，应提前60日向原发证机关申报，其《许可证》由原发证机关予以注销。连续停止业务超过60日的，由原发证机关按终止业务处理，其《许可证》由原发证机关予以注销。"},{"i":14,"n":"第十四条","txt":"互联网视听节目服务单位应当按照《许可证》载明或备案的事项开展互联网视听节目服务，并在播出界面显著位置标注国务院广播电影电视主管部门批准的播出标识、名称、《许可证》或备案编号。 任何单位不得向未持有《许可证》或备案的单位提供与互联网视听节目服务有关的代收费及信号传输、服务器托管等金融和技术服务。"},{"i":15,"n":"第十五条","txt":"鼓励国有战略投资者投资互联网视听节目服务企业；鼓励互联网视听节目服务单位积极开发适应新一代互联网和移动通信特点的新业务，为移动多媒体、多媒体网站生产积极健康的视听节目，努力提高互联网视听节目的供给能力；鼓励影视生产基地、电视节目制作单位多生产适合在网上传播的影视剧（片）、娱乐节目，积极发展民族网络影视产业；鼓励互联网视听节目服务单位传播公益性视听节目。 互联网视听节目服务单位应当遵守著作权法律、行政法规的规定，采取版权保护措施，保护著作权人的合法权益。"},{"i":16,"n":"第十六条","txt":"互联网视听节目服务单位提供的、网络运营单位接入的视听节目应当符合法律、行政法规、部门规章的规定。已播出的视听节目应至少完整保留60日。视听节目不得含有以下内容： （一）反对宪法确定的基本原则的； （二）危害国家统一、主权和领土完整的； （三）泄露国家秘密、危害国家安全或者损害国家荣誉和利益的； （四）煽动民族仇恨、民族歧视，破坏民族团结，或者侵害民族风俗、习惯的； （五）宣扬邪教、迷信的； （六）扰乱社会秩序，破坏社会稳定的； （七）诱导未成年人违法犯罪和渲染暴力、色情、赌博、恐怖活动的； （八）侮辱或者诽谤他人，侵害公民个人隐私等他人合法权益的； （九）危害社会公德，损害民族优秀文化传统的； （十）有关法律、行政法规和国家规定禁止的其他内容。"},{"i":17,"n":"第十七条","txt":"用于互联网视听节目服务的电影电视剧类节目和其它节目，应当符合国家有关广播电影电视节目的管理规定。互联网视听节目服务单位播出时政类视听新闻节目，应当是地（市）级以上广播电台、电视台制作、播出的节目和中央新闻单位网站登载的时政类视听新闻节目。 未持有《许可证》的单位不得为个人提供上载传播视听节目服务。互联网视听节目服务单位不得允许个人上载时政类视听新闻节目，在提供播客、视频分享等上载传播视听节目服务时，应当提示上载者不得上载违反本规定的视听节目。任何单位和个人不得转播、链接、聚合、集成非法的广播电视频道、视听节目网站的节目。"},{"i":18,"n":"第十八条","txt":"广播电影电视主管部门发现互联网视听节目服务单位传播违反本规定的视听节目，应当采取必要措施予以制止。互联网视听节目服务单位对含有违反本规定内容的视听节目，应当立即删除，并保存有关记录，履行报告义务，落实有关主管部门的管理要求。 互联网视听节目服务单位主要出资者和经营者应对播出和上载的视听节目内容负责。"},{"i":19,"n":"第十九条","txt":"互联网视听节目服务单位应当选择依法取得互联网接入服务电信业务经营许可证或广播电视节目传送业务经营许可证的网络运营单位提供服务;应当依法维护用户权利，履行对用户的承诺，对用户信息保密,不得进行虚假宣传或误导用户、做出对用户不公平不合理的规定、损害用户的合法权益；提供有偿服务时，应当以显著方式公布所提供服务的视听节目种类、范围、资费标准和时限，并告知用户中止或者取消互联网视听节目服务的条件和方式。"},{"i":20,"n":"第二十条","txt":"网络运营单位提供互联网视听节目信号传输服务时，应当保障视听节目服务单位的合法权益，保证传输安全，不得擅自插播、截留视听节目信号;在提供服务前应当查验视听节目服务单位的《许可证》或备案证明材料，按照《许可证》载明事项或备案范围提供接入服务。"},{"i":21,"n":"第二十一条","txt":"广播电影电视和电信主管部门应建立公众监督举报制度。公众有权举报视听节目服务单位的违法违规行为，有关主管部门应当及时处理，不得推诿。广播电影电视、电信等监督管理部门发现违反本规定的行为，不属于本部门职责的，应当移交有权处理的部门处理。 电信主管部门应当依照国家有关规定向广播电影电视主管部门提供必要的技术系统接口和网站数据查询资料。"},{"i":22,"n":"第二十二条","txt":"广播电影电视主管部门依法对互联网视听节目服务单位进行实地检查，有关单位和个人应当予以配合。广播电影电视主管部门工作人员依法进行实地检查时应当主动出示有关证件。"},{"i":23,"n":"第二十三条","txt":"违反本规定有下列行为之一的，由县级以上广播电影电视主管部门予以警告、责令改正，可并处3万元以下罚款；同时，可对其主要出资者和经营者予以警告，可并处2万元以下罚款： （一）擅自在互联网上使用广播电视专有名称开展业务的； （二）变更注册资本、股东、股权结构，或上市融资，或重大资产变动时，未办理审批手续的； （三）未建立健全节目运营规范，未采取版权保护措施，或对传播有害内容未履行提示、删除、报告义务的； （四）未在播出界面显著位置标注播出标识、名称、《许可证》和备案编号的； （五）未履行保留节目记录、向主管部门如实提供查询义务的； （六）向未持有《许可证》或备案的单位提供代收费及信号传输、服务器托管等与互联网视听节目服务有关的服务的； （七）未履行查验义务，或向互联网视听节目服务单位提供其《许可证》或备案载明事项范围以外的接入服务的； （八）进行虚假宣传或者误导用户的； （九）未经用户同意，"},{"i":24,"n":"第二十四条","txt":"擅自从事互联网视听节目服务的，由县级以上广播电影电视主管部门予以警告、责令改正，可并处3万元以下罚款；情节严重的，根据《广播电视管理条例》第四十七条的规定予以处罚。 传播的视听节目内容违反本规定的，由县级以上广播电影电视主管部门予以警告、责令改正，可并处3万元以下罚款；情节严重的，根据《广播电视管理条例》第四十九条的规定予以处罚。 未按照许可证载明或备案的事项从事互联网视听节目服务的或违规播出时政类视听新闻节目的，由县级以上广播电影电视主管部门予以警告、责令改正，可并处3万元以下罚款；情节严重的，根据《广播电视管理条例》第五十条之规定予以处罚。 转播、链接、聚合、集成非法的广播电视频道和视听节目网站内容的，擅自插播、截留视听节目信号的，由县级以上广播电影电视主管部门予以警告、责令改正，可并处3万元以下罚款；情节严重的，根据《广播电视管理条例》第五十一条之规定予以处罚。"},{"i":25,"n":"第二十五条","txt":"对违反本规定的互联网视听节目服务单位，电信主管部门应根据广播电影电视主管部门的书面意见，按照电信管理和互联网管理的法律、行政法规的规定，关闭其网站，吊销其相应许可证或撤销备案，责令为其提供信号接入服务的网络运营单位停止接入；拒不执行停止接入服务决定，违反《电信条例》第五十七条规定的，由电信主管部门依据《电信条例》第七十八条的规定吊销其许可证。 违反治安管理规定的，由公安机关依法予以处罚；构成犯罪的，由司法机关依法追究刑事责任。"},{"i":26,"n":"第二十六条","txt":"广播电影电视、电信等主管部门不履行规定的职责，或滥用职权的，要依法给予有关责任人处分，构成犯罪的，由司法机关依法追究刑事责任。"},{"i":27,"n":"第二十七条","txt":"互联网视听节目服务单位出现重大违法违规行为的，除按有关规定予以处罚外，其主要出资者和经营者自互联网视听节目服务单位受到处罚之日起5年内不得投资和从事互联网视听节目服务。"},{"i":28,"n":"第二十八条","txt":"通过互联网提供视音频即时通讯服务，由国务院信息产业主管部门按照国家有关规定进行监督管理。 利用局域网络及利用互联网架设虚拟专网向公众提供网络视听节目服务，须向行业主管部门提出申请，由国务院信息产业主管部门前置审批，国务院广播电影电视主管部门审核批准，按照国家有关规定进行监督管理。"},{"i":29,"n":"第二十九条","txt":"本规定自2008年1月31日起施行。此前发布的规定与本规定不一致之处，依本规定执行。"}],"renlianshibiejishuyingyonganquanguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范应用人脸识别技术处理人脸信息活动，保护个人信息权益，根据《中华人民共和国网络安全法》、《中华人民共和国数据安全法》、《中华人民共和国个人信息保护法》、《网络数据安全管理条例》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内应用人脸识别技术处理人脸信息的活动，适用本办法。 在中华人民共和国境内为从事人脸识别技术研发、算法训练活动应用人脸识别技术处理人脸信息的，不适用本办法的规定。"},{"i":3,"n":"第三条","txt":"应用人脸识别技术处理人脸信息活动，应当遵守法律法规，尊重社会公德和伦理，遵守商业道德和职业道德，诚实守信，履行个人信息保护义务，承担社会责任，不得危害国家安全、损害公共利益、侵害个人合法权益。"},{"i":4,"n":"第四条","txt":"应用人脸识别技术处理人脸信息，应当具有特定的目的和充分的必要性，采取对个人权益影响最小的方式，并实施严格保护措施。"},{"i":5,"n":"第五条","txt":"个人信息处理者应用人脸识别技术处理人脸信息前，应当以显著方式、清晰易懂的语言真实、准确、完整地向个人告知下列事项： （一）个人信息处理者的名称或者姓名和联系方式； （二）人脸信息的处理目的、处理方式，处理的人脸信息保存期限； （三）处理人脸信息的必要性以及对个人权益的影响； （四）个人依法行使权利的方式和程序； （五）法律、行政法规规定应当告知的其他事项。 前款规定事项发生变更的，应当将变更部分告知个人。 法律、行政法规规定可以不向个人告知的，从其规定。 处理残疾人、老年人人脸信息的，还应当符合国家有关无障碍环境建设的规定。"},{"i":6,"n":"第六条","txt":"基于个人同意处理人脸信息的，应当取得个人在充分知情的前提下自愿、明确作出的单独同意。法律、行政法规规定处理人脸信息应当取得个人书面同意的，从其规定。 基于个人同意处理人脸信息的，个人有权撤回同意，个人信息处理者应当提供便捷的撤回同意的方式。个人撤回同意，不影响撤回前基于个人同意已进行的个人信息处理活动的效力。"},{"i":7,"n":"第七条","txt":"基于个人同意处理不满十四周岁未成年人人脸信息的，应当取得未成年人的父母或者其他监护人的同意。 个人信息处理者应用人脸识别技术处理不满十四周岁未成年人人脸信息的，应当在存储、使用、转移、披露等方面制定专门的处理规则，依法保护未成年人个人信息安全。"},{"i":8,"n":"第八条","txt":"除法律、行政法规另有规定或者取得个人单独同意外，人脸信息应当存储于人脸识别设备内，不得通过互联网对外传输。 除法律、行政法规另有规定外，人脸信息的保存期限不得超过实现处理目的所必需的最短时间。"},{"i":9,"n":"第九条","txt":"个人信息处理者应用人脸识别技术处理人脸信息，应当事前进行个人信息保护影响评估，并对处理情况进行记录。个人信息保护影响评估主要包括下列内容： （一）人脸信息的处理目的、处理方式是否合法、正当、必要； （二）对个人权益带来的影响，以及降低不利影响的措施是否有效； （三）发生人脸信息泄露、篡改、丢失、毁损或者被非法获取、出售、使用的风险以及可能造成的危害； （四）所采取的保护措施是否合法、有效并与风险程度相适应。 个人信息保护影响评估报告和处理情况记录应当至少保存3年。处理人脸信息的目的、方式发生变化，或者发生重大安全事件的，应当重新进行个人信息保护影响评估。"},{"i":10,"n":"第十条","txt":"实现相同目的或者达到同等业务要求，存在其他非人脸识别技术方式的，不得将人脸识别技术作为唯一验证方式。个人不同意通过人脸信息进行身份验证的，应当提供其他合理、便捷的方式。 国家对应用人脸识别技术验证个人身份另有规定的，从其规定。"},{"i":11,"n":"第十一条","txt":"应用人脸识别技术验证个人身份、辨识特定个人的，鼓励优先使用国家人口基础信息库、国家网络身份认证公共服务等渠道实施，减少人脸信息收集、存储，保护人脸信息安全。"},{"i":12,"n":"第十二条","txt":"任何组织和个人不得以办理业务、提升服务质量等为由，误导、欺诈、胁迫个人接受人脸识别技术验证个人身份。"},{"i":13,"n":"第十三条","txt":"在公共场所安装人脸识别设备，应当为维护公共安全所必需，依法合理确定人脸信息采集区域，并设置显著提示标识。 任何组织和个人不得在宾馆客房、公共浴室、公共更衣室、公共卫生间等公共场所中的私密空间内部安装人脸识别设备。"},{"i":14,"n":"第十四条","txt":"人脸识别技术应用系统应当采取数据加密、安全审计、访问控制、授权管理、入侵检测和防御等措施保护人脸信息安全。涉及网络安全等级保护、关键信息基础设施的，应当按照国家有关规定履行网络安全等级保护、关键信息基础设施保护义务。"},{"i":15,"n":"第十五条","txt":"个人信息处理者应当在应用人脸识别技术处理的人脸信息存储数量达到10万人之日起30个工作日内向所在地省级以上网信部门履行备案手续。申请备案应当提交下列材料： （一）个人信息处理者的基本情况； （二）人脸信息处理目的和处理方式； （三）人脸信息存储数量和安全保护措施； （四）人脸信息的处理规则和操作规程； （五）个人信息保护影响评估报告。 备案信息发生实质性变更的，应当在变更之日起30个工作日内办理备案变更手续。终止应用人脸识别技术的，应当在终止之日起30个工作日内办理注销备案手续，并依法处理人脸信息。"},{"i":16,"n":"第十六条","txt":"网信部门会同公安机关和其他履行个人信息保护职责的部门，建立健全信息共享和通报工作机制，协同开展相关工作。 网信部门、公安机关和其他履行个人信息保护职责的部门依法对应用人脸识别技术处理个人信息活动实施监督检查，个人信息处理者应当依法予以配合。"},{"i":17,"n":"第十七条","txt":"任何组织、个人有权对违法应用人脸识别技术处理人脸信息的活动向履行个人信息保护职责的部门进行投诉、举报。收到投诉、举报的部门应当依法及时处理，并将处理结果告知投诉人、举报人。"},{"i":18,"n":"第十八条","txt":"违反本办法规定的，依照有关法律、行政法规的规定处理；构成犯罪的，依法追究刑事责任。"},{"i":19,"n":"第十九条","txt":"本办法下列术语的含义： （一）个人信息处理者，是指在个人信息处理活动中自主决定处理目的、处理方式的组织、个人。 （二）人脸信息，是指以电子或者其他方式记录的与已识别或者可识别的自然人有关的面部特征生物识别信息，不包括匿名化处理后的信息。 （三）人脸识别技术，是指以人脸信息作为识别个体身份的个体生物特征识别技术。 （四）人脸识别设备，是指应用人脸识别技术识别个体身份的终端设备。 （五）验证个人身份，是指通过收集获得的人脸信息与信息系统存储的特定人脸信息进行“一对一”比对，确认和核对两者是否为同一人。 （六）辨识特定个人，是指通过收集获得的人脸信息与信息系统存储的特定范围内人脸信息进行“一对多”比对，发现和识别具有特定身份的个人。"},{"i":20,"n":"第二十条","txt":"本办法自2025年6月1日起施行。"}],"cujinheguifanshujukuajingliudongguiding":[{"i":1,"n":"第一条","txt":"为了保障数据安全，保护个人信息权益，促进数据依法有序自由流动，根据《中华人民共和国网络安全法》、《中华人民共和国数据安全法》、《中华人民共和国个人信息保护法》等法律法规，对于数据出境安全评估、个人信息出境标准合同、个人信息保护认证等数据出境制度的施行，制定本规定。"},{"i":2,"n":"第二条","txt":"数据处理者应当按照相关规定识别、申报重要数据。未被相关部门、地区告知或者公开发布为重要数据的，数据处理者不需要作为重要数据申报数据出境安全评估。"},{"i":3,"n":"第三条","txt":"国际贸易、跨境运输、学术合作、跨国生产制造和市场营销等活动中收集和产生的数据向境外提供，不包含个人信息或者重要数据的，免予申报数据出境安全评估、订立个人信息出境标准合同、通过个人信息保护认证。"},{"i":4,"n":"第四条","txt":"数据处理者在境外收集和产生的个人信息传输至境内处理后向境外提供，处理过程中没有引入境内个人信息或者重要数据的，免予申报数据出境安全评估、订立个人信息出境标准合同、通过个人信息保护认证。"},{"i":5,"n":"第五条","txt":"数据处理者向境外提供个人信息，符合下列条件之一的，免予申报数据出境安全评估、订立个人信息出境标准合同、通过个人信息保护认证： （一）为订立、履行个人作为一方当事人的合同，如跨境购物、跨境寄递、跨境汇款、跨境支付、跨境开户、机票酒店预订、签证办理、考试服务等，确需向境外提供个人信息的； （二）按照依法制定的劳动规章制度和依法签订的集体合同实施跨境人力资源管理，确需向境外提供员工个人信息的； （三）紧急情况下为保护自然人的生命健康和财产安全，确需向境外提供个人信息的； （四）关键信息基础设施运营者以外的数据处理者自当年1月1日起累计向境外提供不满10万人个人信息（不含敏感个人信息）的。 前款所称向境外提供的个人信息，不包括重要数据。"},{"i":6,"n":"第六条","txt":"自由贸易试验区在国家数据分类分级保护制度框架下，可以自行制定区内需要纳入数据出境安全评估、个人信息出境标准合同、个人信息保护认证管理范围的数据清单（以下简称负面清单），经省级网络安全和信息化委员会批准后，报国家网信部门、国家数据管理部门备案。 自由贸易试验区内数据处理者向境外提供负面清单外的数据，可以免予申报数据出境安全评估、订立个人信息出境标准合同、通过个人信息保护认证。"},{"i":7,"n":"第七条","txt":"数据处理者向境外提供数据，符合下列条件之一的，应当通过所在地省级网信部门向国家网信部门申报数据出境安全评估： （一）关键信息基础设施运营者向境外提供个人信息或者重要数据； （二）关键信息基础设施运营者以外的数据处理者向境外提供重要数据，或者自当年1月1日起累计向境外提供100万人以上个人信息（不含敏感个人信息）或者1万人以上敏感个人信息。 属于本规定第三条、第四条、第五条、第六条规定情形的，从其规定。"},{"i":8,"n":"第八条","txt":"关键信息基础设施运营者以外的数据处理者自当年1月1日起累计向境外提供10万人以上、不满100万人个人信息（不含敏感个人信息）或者不满1万人敏感个人信息的，应当依法与境外接收方订立个人信息出境标准合同或者通过个人信息保护认证。 属于本规定第三条、第四条、第五条、第六条规定情形的，从其规定。"},{"i":9,"n":"第九条","txt":"通过数据出境安全评估的结果有效期为3年，自评估结果出具之日起计算。有效期届满，需要继续开展数据出境活动且未发生需要重新申报数据出境安全评估情形的，数据处理者可以在有效期届满前60个工作日内通过所在地省级网信部门向国家网信部门提出延长评估结果有效期申请。经国家网信部门批准，可以延长评估结果有效期3年。"},{"i":10,"n":"第十条","txt":"数据处理者向境外提供个人信息的，应当按照法律、行政法规的规定履行告知、取得个人单独同意、进行个人信息保护影响评估等义务。"},{"i":11,"n":"第十一条","txt":"数据处理者向境外提供数据的，应当遵守法律、法规的规定，履行数据安全保护义务，采取技术措施和其他必要措施，保障数据出境安全。发生或者可能发生数据安全事件的，应当采取补救措施，及时向省级以上网信部门和其他有关主管部门报告。"},{"i":12,"n":"第十二条","txt":"各地网信部门应当加强对数据处理者数据出境活动的指导监督，健全完善数据出境安全评估制度，优化评估流程；强化事前事中事后全链条全领域监管，发现数据出境活动存在较大风险或者发生数据安全事件的，要求数据处理者进行整改，消除隐患；对拒不改正或者造成严重后果的，依法追究法律责任。"},{"i":13,"n":"第十三条","txt":"2022年7月7日公布的《数据出境安全评估办法》（国家互联网信息办公室令第11号）、2023年2月22日公布的《个人信息出境标准合同办法》（国家互联网信息办公室令第13号）等相关规定与本规定不一致的，适用本规定。"},{"i":14,"n":"第十四条","txt":"本规定自公布之日起施行。"}],"ertonggerenxinxiwangluobaohuguiding":[{"i":1,"n":"第一条","txt":"为了保护儿童个人信息安全，促进儿童健康成长，根据《中华人民共和国网络安全法》、《中华人民共和国未成年人保护法》等法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称儿童，是指不满十四周岁的未成年人。"},{"i":3,"n":"第三条","txt":"在中华人民共和国境内通过网络从事收集、存储、使用、转移、披露儿童个人信息等活动，适用本规定。"},{"i":4,"n":"第四条","txt":"任何组织和个人不得制作、发布、传播侵害儿童个人信息安全的信息。"},{"i":5,"n":"第五条","txt":"儿童监护人应当正确履行监护职责，教育引导儿童增强个人信息保护意识和能力，保护儿童个人信息安全。"},{"i":6,"n":"第六条","txt":"鼓励互联网行业组织指导推动网络运营者制定儿童个人信息保护的行业规范、行为准则等，加强行业自律，履行社会责任。"},{"i":7,"n":"第七条","txt":"网络运营者收集、存储、使用、转移、披露儿童个人信息的，应当遵循正当必要、知情同意、目的明确、安全保障、依法利用的原则。"},{"i":8,"n":"第八条","txt":"网络运营者应当设置专门的儿童个人信息保护规则和用户协议，并指定专人负责儿童个人信息保护。"},{"i":9,"n":"第九条","txt":"网络运营者收集、使用、转移、披露儿童个人信息的，应当以显著、清晰的方式告知儿童监护人，并应当征得儿童监护人的同意。"},{"i":10,"n":"第十条","txt":"网络运营者征得同意时，应当同时提供拒绝选项，并明确告知以下事项： （一）收集、存储、使用、转移、披露儿童个人信息的目的、方式和范围； （二）儿童个人信息存储的地点、期限和到期后的处理方式； （三）儿童个人信息的安全保障措施； （四）拒绝的后果； （五）投诉、举报的渠道和方式； （六）更正、删除儿童个人信息的途径和方法； （七）其他应当告知的事项。 前款规定的告知事项发生实质性变化的，应当再次征得儿童监护人的同意。"},{"i":11,"n":"第十一条","txt":"网络运营者不得收集与其提供的服务无关的儿童个人信息，不得违反法律、行政法规的规定和双方的约定收集儿童个人信息。"},{"i":12,"n":"第十二条","txt":"网络运营者存储儿童个人信息，不得超过实现其收集、使用目的所必需的期限。"},{"i":13,"n":"第十三条","txt":"网络运营者应当采取加密等措施存储儿童个人信息，确保信息安全。"},{"i":14,"n":"第十四条","txt":"网络运营者使用儿童个人信息，不得违反法律、行政法规的规定和双方约定的目的、范围。因业务需要，确需超出约定的目的、范围使用的，应当再次征得儿童监护人的同意。"},{"i":15,"n":"第十五条","txt":"网络运营者对其工作人员应当以最小授权为原则，严格设定信息访问权限，控制儿童个人信息知悉范围。工作人员访问儿童个人信息的，应当经过儿童个人信息保护负责人或者其授权的管理人员审批，记录访问情况，并采取技术措施，避免违法复制、下载儿童个人信息。"},{"i":16,"n":"第十六条","txt":"网络运营者委托第三方处理儿童个人信息的，应当对受委托方及委托行为等进行安全评估，签署委托协议，明确双方责任、处理事项、处理期限、处理性质和目的等，委托行为不得超出授权范围。 前款规定的受委托方，应当履行以下义务： （一）按照法律、行政法规的规定和网络运营者的要求处理儿童个人信息； （二）协助网络运营者回应儿童监护人提出的申请； （三）采取措施保障信息安全，并在发生儿童个人信息泄露安全事件时，及时向网络运营者反馈； （四）委托关系解除时及时删除儿童个人信息; （五）不得转委托； （六）其他依法应当履行的儿童个人信息保护义务。"},{"i":17,"n":"第十七条","txt":"网络运营者向第三方转移儿童个人信息的，应当自行或者委托第三方机构进行安全评估。"},{"i":18,"n":"第十八条","txt":"网络运营者不得披露儿童个人信息，但法律、行政法规规定应当披露或者根据与儿童监护人的约定可以披露的除外。"},{"i":19,"n":"第十九条","txt":"儿童或者其监护人发现网络运营者收集、存储、使用、披露的儿童个人信息有错误的，有权要求网络运营者予以更正。网络运营者应当及时采取措施予以更正。"},{"i":20,"n":"第二十条","txt":"儿童或者其监护人要求网络运营者删除其收集、存储、使用、披露的儿童个人信息的，网络运营者应当及时采取措施予以删除，包括但不限于以下情形： （一）网络运营者违反法律、行政法规的规定或者双方的约定收集、存储、使用、转移、披露儿童个人信息的； （二）超出目的范围或者必要期限收集、存储、使用、转移、披露儿童个人信息的； （三）儿童监护人撤回同意的； （四）儿童或者其监护人通过注销等方式终止使用产品或者服务的。"},{"i":21,"n":"第二十一条","txt":"网络运营者发现儿童个人信息发生或者可能发生泄露、毁损、丢失的，应当立即启动应急预案，采取补救措施；造成或者可能造成严重后果的，应当立即向有关主管部门报告，并将事件相关情况以邮件、信函、电话、推送通知等方式告知受影响的儿童及其监护人，难以逐一告知的，应当采取合理、有效的方式发布相关警示信息。"},{"i":22,"n":"第二十二条","txt":"网络运营者应当对网信部门和其他有关部门依法开展的监督检查予以配合。"},{"i":23,"n":"第二十三条","txt":"网络运营者停止运营产品或者服务的，应当立即停止收集儿童个人信息的活动，删除其持有的儿童个人信息，并将停止运营的通知及时告知儿童监护人。"},{"i":24,"n":"第二十四条","txt":"任何组织和个人发现有违反本规定行为的，可以向网信部门和其他有关部门举报。 网信部门和其他有关部门收到相关举报的，应当依据职责及时进行处理。"},{"i":25,"n":"第二十五条","txt":"网络运营者落实儿童个人信息安全管理责任不到位，存在较大安全风险或者发生安全事件的，由网信部门依据职责进行约谈，网络运营者应当及时采取措施进行整改，消除隐患。"},{"i":26,"n":"第二十六条","txt":"违反本规定的，由网信部门和其他有关部门依据职责，根据《中华人民共和国网络安全法》、《互联网信息服务管理办法》等相关法律法规规定处理；构成犯罪的，依法追究刑事责任。"},{"i":27,"n":"第二十七条","txt":"违反本规定被追究法律责任的，依照有关法律、行政法规的规定记入信用档案，并予以公示。"},{"i":28,"n":"第二十八条","txt":"通过计算机信息系统自动留存处理信息且无法识别所留存处理的信息属于儿童个人信息的，依照其他有关规定执行。"},{"i":29,"n":"第二十九条","txt":"本规定自2019年10月1日起施行。"}],"qukuailianxinxifuwuguanliguiding":[{"i":1,"n":"第一条","txt":"为了规范区块链信息服务活动，维护国家安全和社会公共利益，保护公民、法人和其他组织的合法权益，促进区块链技术及相关服务的健康发展，根据《中华人民共和国网络安全法》、《互联网信息服务管理办法》和《国务院关于授权国家互联网信息办公室负责互联网信息内容管理工作的通知》，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事区块链信息服务，应当遵守本规定。法律、行政法规另有规定的，遵照其规定。 本规定所称区块链信息服务，是指基于区块链技术或者系统，通过互联网站、应用程序等形式，向社会公众提供信息服务。 本规定所称区块链信息服务提供者，是指向社会公众提供区块链信息服务的主体或者节点，以及为区块链信息服务的主体提供技术支持的机构或者组织；本规定所称区块链信息服务使用者，是指使用区块链信息服务的组织或者个人。"},{"i":3,"n":"第三条","txt":"国家互联网信息办公室依据职责负责全国区块链信息服务的监督管理执法工作。省、自治区、直辖市互联网信息办公室依据职责负责本行政区域内区块链信息服务的监督管理执法工作。"},{"i":4,"n":"第四条","txt":"鼓励区块链行业组织加强行业自律，建立健全行业自律制度和行业准则，指导区块链信息服务提供者建立健全服务规范，推动行业信用评价体系建设，督促区块链信息服务提供者依法提供服务、接受社会监督，提高区块链信息服务从业人员的职业素养，促进行业健康有序发展。"},{"i":5,"n":"第五条","txt":"区块链信息服务提供者应当落实信息内容安全管理责任，建立健全用户注册、信息审核、应急处置、安全防护等管理制度。"},{"i":6,"n":"第六条","txt":"区块链信息服务提供者应当具备与其服务相适应的技术条件，对于法律、行政法规禁止的信息内容，应当具备对其发布、记录、存储、传播的即时和应急处置能力，技术方案应当符合国家相关标准规范。"},{"i":7,"n":"第七条","txt":"区块链信息服务提供者应当制定并公开管理规则和平台公约，与区块链信息服务使用者签订服务协议，明确双方权利义务，要求其承诺遵守法律规定和平台公约。"},{"i":8,"n":"第八条","txt":"区块链信息服务提供者应当按照《中华人民共和国网络安全法》的规定，对区块链信息服务使用者进行基于组织机构代码、身份证件号码或者移动电话号码等方式的真实身份信息认证。用户不进行真实身份信息认证的，区块链信息服务提供者不得为其提供相关服务。"},{"i":9,"n":"第九条","txt":"区块链信息服务提供者开发上线新产品、新应用、新功能的，应当按照有关规定报国家和省、自治区、直辖市互联网信息办公室进行安全评估。"},{"i":10,"n":"第十条","txt":"区块链信息服务提供者和使用者不得利用区块链信息服务从事危害国家安全、扰乱社会秩序、侵犯他人合法权益等法律、行政法规禁止的活动，不得利用区块链信息服务制作、复制、发布、传播法律、行政法规禁止的信息内容。"},{"i":11,"n":"第十一条","txt":"区块链信息服务提供者应当在提供服务之日起十个工作日内通过国家互联网信息办公室区块链信息服务备案管理系统填报服务提供者的名称、服务类别、服务形式、应用领域、服务器地址等信息，履行备案手续。 区块链信息服务提供者变更服务项目、平台网址等事项的，应当在变更之日起五个工作日内办理变更手续。 区块链信息服务提供者终止服务的，应当在终止服务三十个工作日前办理注销手续，并作出妥善安排。"},{"i":12,"n":"第十二条","txt":"国家和省、自治区、直辖市互联网信息办公室收到备案人提交的备案材料后，材料齐全的，应当在二十个工作日内予以备案，发放备案编号，并通过国家互联网信息办公室区块链信息服务备案管理系统向社会公布备案信息；材料不齐全的，不予备案，在二十个工作日内通知备案人并说明理由。"},{"i":13,"n":"第十三条","txt":"完成备案的区块链信息服务提供者应当在其对外提供服务的互联网站、应用程序等的显著位置标明其备案编号。"},{"i":14,"n":"第十四条","txt":"国家和省、自治区、直辖市互联网信息办公室对区块链信息服务备案信息实行定期查验，区块链信息服务提供者应当在规定时间内登录区块链信息服务备案管理系统，提供相关信息。"},{"i":15,"n":"第十五条","txt":"区块链信息服务提供者提供的区块链信息服务存在信息安全隐患的，应当进行整改，符合法律、行政法规等相关规定和国家相关标准规范后方可继续提供信息服务。"},{"i":16,"n":"第十六条","txt":"区块链信息服务提供者应当对违反法律、行政法规规定和服务协议的区块链信息服务使用者，依法依约采取警示、限制功能、关闭账号等处置措施，对违法信息内容及时采取相应的处理措施，防止信息扩散，保存有关记录，并向有关主管部门报告。"},{"i":17,"n":"第十七条","txt":"区块链信息服务提供者应当记录区块链信息服务使用者发布内容和日志等信息，记录备份应当保存不少于六个月，并在相关执法部门依法查询时予以提供。"},{"i":18,"n":"第十八条","txt":"区块链信息服务提供者应当配合网信部门依法实施的监督检查，并提供必要的技术支持和协助。 区块链信息服务提供者应当接受社会监督，设置便捷的投诉举报入口，及时处理公众投诉举报。"},{"i":19,"n":"第十九条","txt":"区块链信息服务提供者违反本规定第五条、第六条、第七条、第九条、第十一条第二款、第十三条、第十五条、第十七条、第十八条规定的，由国家和省、自治区、直辖市互联网信息办公室依据职责给予警告，责令限期改正，改正前应当暂停相关业务；拒不改正或者情节严重的，并处五千元以上三万元以下罚款；构成犯罪的，依法追究刑事责任。"},{"i":20,"n":"第二十条","txt":"区块链信息服务提供者违反本规定第八条、第十六条规定的，由国家和省、自治区、直辖市互联网信息办公室依据职责，按照《中华人民共和国网络安全法》的规定予以处理。"},{"i":21,"n":"第二十一条","txt":"区块链信息服务提供者违反本规定第十条的规定，制作、复制、发布、传播法律、行政法规禁止的信息内容的，由国家和省、自治区、直辖市互联网信息办公室依据职责给予警告，责令限期改正，改正前应当暂停相关业务；拒不改正或者情节严重的，并处二万元以上三万元以下罚款；构成犯罪的，依法追究刑事责任。 区块链信息服务使用者违反本规定第十条的规定，制作、复制、发布、传播法律、行政法规禁止的信息内容的，由国家和省、自治区、直辖市互联网信息办公室依照有关法律、行政法规的规定予以处理。"},{"i":22,"n":"第二十二条","txt":"区块链信息服务提供者违反本规定第十一条第一款的规定，未按照本规定履行备案手续或者填报虚假备案信息的，由国家和省、自治区、直辖市互联网信息办公室依据职责责令限期改正；拒不改正或者情节严重的，给予警告，并处一万元以上三万元以下罚款。"},{"i":23,"n":"第二十三条","txt":"在本规定公布前从事区块链信息服务的，应当自本规定生效之日起二十个工作日内依照本规定补办有关手续。"},{"i":24,"n":"第二十四条","txt":"本规定自2019年2月15日起施行。"}],"guojiawangluoshenfenrenzhenggonggongfuwuguanlibanf9de600":[{"i":1,"n":"第一条","txt":"为实施可信数字身份战略，推进国家网络身份认证公共服务建设，保护公民身份信息安全，支撑数字经济健康有序发展，根据《网络安全法》、《数据安全法》、《个人信息保护法》、《反电信网络诈骗法》、《未成年人保护法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称国家网络身份认证公共服务（以下简称“公共服务”），是指国家根据法定身份证件信息，依托国家统一建设的网络身份认证公共服务平台（以下简称“公共服务平台”），为自然人提供申领网号、网证以及进行身份核验等服务。 本办法所称网号，是指与自然人身份信息相对应，由字母和数字组成、不含明文身份信息的网络身份符号；网证，是指承载网号及自然人非明文身份信息的网络身份认证凭证。网号、网证可用于在互联网服务及有关部门、行业管理、服务中非明文登记、核验自然人真实身份信息。"},{"i":3,"n":"第三条","txt":"国务院公安部门、国家网信部门会同国务院民政、文化和旅游、卫生健康、广播电视等部门依照本办法和有关法律、行政法规的规定，在各自职责范围内负责网络身份认证公共服务有关工作。"},{"i":4,"n":"第四条","txt":"持有有效法定身份证件的自然人，可以自愿向公共服务平台申领网号、网证。 不满十四周岁的自然人申领网号、网证的，应当取得其父母或者其他监护人同意，并由其父母或者其他监护人代为申领。 已满十四周岁未满十八周岁的自然人申领网号、网证的，应当在其父母或者其他监护人的监护下申领。"},{"i":5,"n":"第五条","txt":"根据法律、行政法规规定，在互联网服务中需要登记、核验用户真实身份信息的，可以使用网号、网证依法进行登记、核验。 不满十四周岁的自然人使用网号、网证登记、核验真实身份信息的，应当取得其父母或者其他监护人同意。"},{"i":6,"n":"第六条","txt":"鼓励有关主管部门、重点行业按照自愿原则推广应用网号、网证，为用户提供安全、便捷的身份登记和核验服务，通过公共服务培育网络身份认证应用生态。 有关主管部门、重点行业在管理、服务中，应当保留、提供现有的或者其他合法方式进行登记、核验真实身份。"},{"i":7,"n":"第七条","txt":"鼓励互联网平台按照自愿原则接入公共服务，用以支持用户使用网号、网证登记、核验用户真实身份信息，依法履行个人信息保护和核验用户真实身份信息的义务。 互联网平台接入公共服务后，用户选择使用网号、网证登记、核验真实身份信息并通过验证的，互联网平台不得要求用户另行提供明文身份信息，法律、行政法规另有规定或者用户同意提供的除外。 互联网平台应当保障未使用网号、网证但通过其他方式登记、核验真实身份的用户与使用网号、网证的用户享有同等服务。"},{"i":8,"n":"第八条","txt":"互联网平台需要依法核验用户真实身份信息但无需留存用户法定身份证件信息的，公共服务平台应当仅提供用户身份核验结果。 根据法律、行政法规规定，互联网平台确需获取、留存用户法定身份证件信息的，经用户授权或者单独同意，公共服务平台应当按照最小化原则提供。 未经自然人单独同意，互联网平台不得擅自处理或者对外提供相关数据、信息，法律、行政法规另有规定的除外。"},{"i":9,"n":"第九条","txt":"公共服务平台仅限收集网络身份认证所必需的信息，处理个人信息或者向自然人提供公共服务，应当依法履行告知义务并取得其同意。处理敏感个人信息，应当取得个人的单独同意，法律、行政法规规定应当取得书面同意的，从其规定。 未经自然人单独同意，公共服务平台不得擅自处理或者对外提供相关数据、信息，不得将相关数据用于用户登记、核验真实身份以外的目的，法律、行政法规另有规定的除外。 公共服务平台应当依照法律、行政法规规定或者用户要求，及时删除用户个人信息。"},{"i":10,"n":"第十条","txt":"涉及未成年人、老年人等用户的，公共服务平台可以依法向互联网平台提供年龄标识信息，用于支持互联网平台履行相应的法律义务。"},{"i":11,"n":"第十一条","txt":"公共服务平台在处理用户个人信息前，应当通过用户协议等书面形式，以显著方式、清晰易懂的语言真实、准确、完整地向用户告知下列事项： （一）公共服务平台的名称和联系方式； （二）用户个人信息的处理目的、处理方式，处理的个人信息种类、保存期限； （三）用户依法行使其个人信息相关权利的方式和程序； （四）法律、行政法规规定应当告知的其他事项。 处理敏感个人信息的，还应当向个人告知处理的必要性以及对个人权益的影响，法律另有规定的除外。 公共服务平台处理个人信息，有法律、行政法规规定应当保密或者不需要告知的情形的，可以不向个人告知本条第一款规定的事项。 紧急情况下为保护自然人的生命健康和财产安全无法及时向个人告知的，公共服务平台应当在紧急情况消除后及时告知。"},{"i":12,"n":"第十二条","txt":"公共服务平台应当加强网络运行安全、数据安全和个人信息保护，建立并落实安全管理制度与技术防护措施，完善监督制度，有效保护网络运行安全、数据安全和个人信息权益。 公共服务平台处理的重要数据和个人信息应当在境内存储；因业务需要确需向境外提供的，应当按照国家有关规定进行安全评估。 公共服务平台发生网络运行安全、数据安全事件的，应当按照国家有关规定，立即启动应急预案，采取必要措施消除安全隐患，及时告知用户并向有关部门报告。"},{"i":13,"n":"第十三条","txt":"公共服务平台的建设和服务涉及密码的，应当符合国家密码管理有关要求。"},{"i":14,"n":"第十四条","txt":"违反本办法第七条、第八条、第九条、第十一条、第十二条规定，依照《网络安全法》、《数据安全法》、《个人信息保护法》，由国务院公安部门、国家网信部门在各自职责范围内依法予以处罚、处分；构成犯罪的，依法追究刑事责任。 有关主管部门、重点行业在网络身份认证公共服务有关工作中玩忽职守、滥用职权的，依法追究责任。"},{"i":15,"n":"第十五条","txt":"本办法所称法定身份证件，包括居民身份证、定居国外的中国公民的护照、港澳居民来往内地通行证、台湾居民来往大陆通行证、港澳居民居住证、台湾居民居住证、外国人永久居留身份证等身份证件。"},{"i":16,"n":"第十六条","txt":"本办法自2025年7月15日起施行。"}],"waiguojigouzaizhongguojingneitigongjinrongxinxifuw845771-2":[{"i":1,"n":"第一条","txt":"为便于外国机构在中国境内依法提供金融信息服务，满足国内用户对金融信息的需求，促进金融信息服务业健康、有序发展，根据《国务院关于修改〈国务院对确需保留的行政审批项目设定行政许可的决定〉的决定》（国务院第548号令），制定本规定。"},{"i":2,"n":"第二条","txt":"外国机构在中国境内提供金融信息服务，适用本规定。 本规定所称外国机构，是指外国金融信息服务提供者。 本规定所称金融信息服务，是指向从事金融分析、金融交易、金融决策或者其他金融活动的用户提供可能影响金融市场的信息和/或者金融数据的服务。该服务不同于通讯社服务。"},{"i":3,"n":"第三条","txt":"中国依法保障外国机构在中国境内提供金融信息服务的合法权益，为其依法提供金融信息服务提供便利。 外国机构在中国境内提供金融信息服务，应当遵守中国法律、法规和规章。"},{"i":4,"n":"第四条","txt":"国务院新闻办公室为外国机构在中国境内提供金融信息服务的监督管理机关。外国机构在中国境内提供金融信息服务，必须经国务院新闻办公室批准。 未经国务院新闻办公室批准的外国机构，不得在中国境内提供金融信息服务。"},{"i":5,"n":"第五条","txt":"外国机构申请在中国境内提供金融信息服务，应当具备以下条件： （一）在所在国家（地区）有相应的合法资质； （二）在金融信息服务领域有良好信誉； （三）有确定的金融信息服务业务； （四）有良好的传播手段和技术服务； （五）中国法律、法规规定的其他条件。"},{"i":6,"n":"第六条","txt":"外国机构在中国境内提供金融信息服务，需向国务院新闻办公室申请，提交下列材料： （一）该机构主要负责人签署的书面申请； （二）该机构情况介绍； （三）该机构在所在国家（地区）设立的证明文本副本； （四）拟提供金融信息服务的产品、栏目、说明、信息来源和样品的概述； （五）传播手段及技术服务说明材料。"},{"i":7,"n":"第七条","txt":"国务院新闻办公室应当自受理申请之日起20个工作日内作出批准或者不批准决定。予以批准的，发给批准文件；不予批准的，书面通知申请人并说明理由。"},{"i":8,"n":"第八条","txt":"外国机构在中国境内提供金融信息服务，应当与用户签订书面合同。 外国机构应当在首次收到本规定第七条所述批准文件后30日内，就获得批准文件前与国内用户签订的任何合同，向国务院新闻办公室备案。获得批准的外国机构与国内用户签订、终止任何合同，应当在该合同签订、终止后30日内，向国务院新闻办公室备案。备案内容包括：合同所涉信息产品、提供方式、用户相关身份信息、合同期限等。已备案内容发生变更的，外国机构应当在变更后30日内向国务院新闻办公室变更备案。"},{"i":9,"n":"第九条","txt":"外国机构在中国境内提供金融信息服务，拟变更机构名称、产品种类或者传播手段的，应当至少提前30日向国务院新闻办公室办理变更手续。"},{"i":10,"n":"第十条","txt":"外国机构拟终止在中国境内提供金融信息服务的，应当在终止业务前书面告知国务院新闻办公室，并自终止业务之日起7日内到国务院新闻办公室办理注销手续。"},{"i":11,"n":"第十一条","txt":"外国机构在中国境内提供金融信息服务批准文件有效期为2年。批准文件到期并拟继续提供服务的，应当在批准文件到期前至少30日，持原批准文件和本规定第六条所述材料向国务院新闻办公室申请更新批准文件。国务院新闻办公室将依照本规定第七条的规定办理。"},{"i":12,"n":"第十二条","txt":"国务院新闻办公室依法保护外国机构依照本规定提交材料中包含的具有商业价值的信息，上述信息将仅用于监管。"},{"i":13,"n":"第十三条","txt":"外国机构在中国境内投资设立金融信息服务企业，应当依照中国有关法律向国务院商务主管部门提出申请，并提交下列材料： （一）国务院新闻办公室的批准文件； （二）该机构主要负责人签署的在中国境内投资设立金融信息服务企业的书面申请； （三）由各方投资者法定代表人或者其授权的代表签署的金融信息服务企业的合同、章程； （四）拟投资设立金融信息服务企业的董事会成员名单及证明文件； （五）工商行政管理部门出具的企业名称预先核准通知书； （六）中国法律、法规规定的其他文件。"},{"i":14,"n":"第十四条","txt":"国务院商务主管部门应当自受理申请之日起30个工作日内作出批准或者不批准决定。予以批准的，发给《外商投资企业批准证书》；不予批准的，书面通知申请人并说明理由。"},{"i":15,"n":"第十五条","txt":"获得批准投资设立金融信息服务企业的外国机构应当自收到《外商投资企业批准证书》之日起30日内，依法向工商行政管理部门申请设立登记。 外商投资的金融信息服务企业变更登记事项或者终止的，应当依法办理变更登记或者注销登记。"},{"i":16,"n":"第十六条","txt":"外国机构应当严格按照批准的经营范围提供金融信息服务。国务院新闻办公室对外国机构提供金融信息服务进行监督检查，外国机构应当予以配合。"},{"i":17,"n":"第十七条","txt":"外国机构在中国境内向用户提供的金融信息，不得含有下列内容： （一）违反中华人民共和国宪法基本原则的； （二）破坏中国国家统一、主权和领土完整的； （三）危害中国国家安全和损害国家利益的； （四）违反中国的民族、宗教政策，破坏民族团结，宣扬邪教的； （五）散布虚假金融信息，扰乱经济秩序，破坏经济、金融、资本市场和社会稳定的； （六）宣扬淫秽、色情、暴力、恐怖或者教唆犯罪的； （七）侮辱或者诽谤他人，侵害他人合法权益的； （八）中国法律、法规和规章禁止的其他内容。"},{"i":18,"n":"第十八条","txt":"国务院新闻办公室对外国机构在中国境内提供的金融信息进行同步审视，发现含有本规定第十七条所列内容的，予以调查、处理。外国机构应当向国务院新闻办公室无偿提供同步审视其所提供金融信息的必要条件。"},{"i":19,"n":"第十九条","txt":"在中国境内设立的外商投资金融信息服务企业应当严格按照登记注册的经营范围从事业务活动，不得开展新闻采集业务，不得从事通讯社业务。"},{"i":20,"n":"第二十条","txt":"国内金融信息用户发现外国机构提供的金融信息中含有本规定第十七条所列内容的，应当向国务院新闻办公室举报，并不得使用和传播。"},{"i":21,"n":"第二十一条","txt":"外国机构在中国境内提供金融信息服务违反本规定的，由国务院新闻办公室和有关部门责令改正，给予警告，并处罚款。违反其他法律法规的，由相关行政、司法机关依法处理。"},{"i":22,"n":"第二十二条","txt":"国内金融信息用户向社会传播外国机构提供的金融信息中含有本规定第十七条所列内容的，由国务院新闻办公室和有关部门依法处罚。"},{"i":23,"n":"第二十三条","txt":"国务院新闻办公室工作人员，因玩忽职守、滥用职权、徇私舞弊或者收受贿赂，造成严重后果并构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分。"},{"i":24,"n":"第二十四条","txt":"香港特别行政区、澳门特别行政区、台湾地区有关机构，在内地提供金融信息服务，参照适用本规定。"},{"i":25,"n":"第二十五条","txt":"本规定自2009年6月1日起施行。本规定发布前，有关部门发布的关于金融信息服务的规定与本规定不一致的，以本规定为准。 本规定施行前已获得批准在中国境内提供金融信息服务的外国机构，拟继续在中国境内提供金融信息服务的，应当在本规定施行之日起30日内持本规定第六条所述材料向国务院新闻办公室提出申请。在国务院新闻办公室根据本规定第七条做出决定之日前，允许其继续提供该服务。"}],"shujuchujinganquanpinggubanfa":[{"i":1,"n":"第一条","txt":"为了规范数据出境活动，保护个人信息权益，维护国家安全和社会公共利益，促进数据跨境安全、自由流动，根据《中华人民共和国网络安全法》、《中华人民共和国数据安全法》、《中华人民共和国个人信息保护法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"数据处理者向境外提供在中华人民共和国境内运营中收集和产生的重要数据和个人信息的安全评估，适用本办法。法律、行政法规另有规定的，依照其规定。"},{"i":3,"n":"第三条","txt":"数据出境安全评估坚持事前评估和持续监督相结合、风险自评估与安全评估相结合，防范数据出境安全风险，保障数据依法有序自由流动。"},{"i":4,"n":"第四条","txt":"数据处理者向境外提供数据，有下列情形之一的，应当通过所在地省级网信部门向国家网信部门申报数据出境安全评估： （一）数据处理者向境外提供重要数据； （二）关键信息基础设施运营者和处理100万人以上个人信息的数据处理者向境外提供个人信息； （三）自上年1月1日起累计向境外提供10万人个人信息或者1万人敏感个人信息的数据处理者向境外提供个人信息； （四）国家网信部门规定的其他需要申报数据出境安全评估的情形。"},{"i":5,"n":"第五条","txt":"数据处理者在申报数据出境安全评估前，应当开展数据出境风险自评估，重点评估以下事项： （一）数据出境和境外接收方处理数据的目的、范围、方式等的合法性、正当性、必要性； （二）出境数据的规模、范围、种类、敏感程度，数据出境可能对国家安全、公共利益、个人或者组织合法权益带来的风险； （三）境外接收方承诺承担的责任义务，以及履行责任义务的管理和技术措施、能力等能否保障出境数据的安全； （四）数据出境中和出境后遭到篡改、破坏、泄露、丢失、转移或者被非法获取、非法利用等的风险，个人信息权益维护的渠道是否通畅等； （五）与境外接收方拟订立的数据出境相关合同或者其他具有法律效力的文件等（以下统称法律文件）是否充分约定了数据安全保护责任义务； （六）其他可能影响数据出境安全的事项。"},{"i":6,"n":"第六条","txt":"申报数据出境安全评估，应当提交以下材料： （一）申报书； （二）数据出境风险自评估报告； （三）数据处理者与境外接收方拟订立的法律文件； （四）安全评估工作需要的其他材料。"},{"i":7,"n":"第七条","txt":"省级网信部门应当自收到申报材料之日起5个工作日内完成完备性查验。申报材料齐全的，将申报材料报送国家网信部门；申报材料不齐全的，应当退回数据处理者并一次性告知需要补充的材料。 国家网信部门应当自收到申报材料之日起7个工作日内，确定是否受理并书面通知数据处理者。"},{"i":8,"n":"第八条","txt":"数据出境安全评估重点评估数据出境活动可能对国家安全、公共利益、个人或者组织合法权益带来的风险，主要包括以下事项： （一）数据出境的目的、范围、方式等的合法性、正当性、必要性； （二）境外接收方所在国家或者地区的数据安全保护政策法规和网络安全环境对出境数据安全的影响；境外接收方的数据保护水平是否达到中华人民共和国法律、行政法规的规定和强制性国家标准的要求； （三）出境数据的规模、范围、种类、敏感程度，出境中和出境后遭到篡改、破坏、泄露、丢失、转移或者被非法获取、非法利用等的风险； （四）数据安全和个人信息权益是否能够得到充分有效保障； （五）数据处理者与境外接收方拟订立的法律文件中是否充分约定了数据安全保护责任义务； （六）遵守中国法律、行政法规、部门规章情况； （七）国家网信部门认为需要评估的其他事项。"},{"i":9,"n":"第九条","txt":"数据处理者应当在与境外接收方订立的法律文件中明确约定数据安全保护责任义务，至少包括以下内容： （一）数据出境的目的、方式和数据范围，境外接收方处理数据的用途、方式等； （二）数据在境外保存地点、期限，以及达到保存期限、完成约定目的或者法律文件终止后出境数据的处理措施； （三）对于境外接收方将出境数据再转移给其他组织、个人的约束性要求； （四）境外接收方在实际控制权或者经营范围发生实质性变化，或者所在国家、地区数据安全保护政策法规和网络安全环境发生变化以及发生其他不可抗力情形导致难以保障数据安全时，应当采取的安全措施； （五）违反法律文件约定的数据安全保护义务的补救措施、违约责任和争议解决方式； （六）出境数据遭到篡改、破坏、泄露、丢失、转移或者被非法获取、非法利用等风险时，妥善开展应急处置的要求和保障个人维护其个人信息权益的途径和方式。"},{"i":10,"n":"第十条","txt":"国家网信部门受理申报后，根据申报情况组织国务院有关部门、省级网信部门、专门机构等进行安全评估。"},{"i":11,"n":"第十一条","txt":"安全评估过程中，发现数据处理者提交的申报材料不符合要求的，国家网信部门可以要求其补充或者更正。数据处理者无正当理由不补充或者更正的，国家网信部门可以终止安全评估。 数据处理者对所提交材料的真实性负责，故意提交虚假材料的，按照评估不通过处理，并依法追究相应法律责任。"},{"i":12,"n":"第十二条","txt":"国家网信部门应当自向数据处理者发出书面受理通知书之日起45个工作日内完成数据出境安全评估；情况复杂或者需要补充、更正材料的，可以适当延长并告知数据处理者预计延长的时间。 评估结果应当书面通知数据处理者。"},{"i":13,"n":"第十三条","txt":"数据处理者对评估结果有异议的，可以在收到评估结果15个工作日内向国家网信部门申请复评，复评结果为最终结论。"},{"i":14,"n":"第十四条","txt":"通过数据出境安全评估的结果有效期为2年，自评估结果出具之日起计算。在有效期内出现以下情形之一的，数据处理者应当重新申报评估： （一）向境外提供数据的目的、方式、范围、种类和境外接收方处理数据的用途、方式发生变化影响出境数据安全的，或者延长个人信息和重要数据境外保存期限的； （二）境外接收方所在国家或者地区数据安全保护政策法规和网络安全环境发生变化以及发生其他不可抗力情形、数据处理者或者境外接收方实际控制权发生变化、数据处理者与境外接收方法律文件变更等影响出境数据安全的； （三）出现影响出境数据安全的其他情形。 有效期届满，需要继续开展数据出境活动的，数据处理者应当在有效期届满60个工作日前重新申报评估。"},{"i":15,"n":"第十五条","txt":"参与安全评估工作的相关机构和人员对在履行职责中知悉的国家秘密、个人隐私、个人信息、商业秘密、保密商务信息等数据应当依法予以保密，不得泄露或者非法向他人提供、非法使用。"},{"i":16,"n":"第十六条","txt":"任何组织和个人发现数据处理者违反本办法向境外提供数据的，可以向省级以上网信部门举报。"},{"i":17,"n":"第十七条","txt":"国家网信部门发现已经通过评估的数据出境活动在实际处理过程中不再符合数据出境安全管理要求的，应当书面通知数据处理者终止数据出境活动。数据处理者需要继续开展数据出境活动的，应当按照要求整改，整改完成后重新申报评估。"},{"i":18,"n":"第十八条","txt":"违反本办法规定的，依据《中华人民共和国网络安全法》、《中华人民共和国数据安全法》、《中华人民共和国个人信息保护法》等法律法规处理；构成犯罪的，依法追究刑事责任。"},{"i":19,"n":"第十九条","txt":"本办法所称重要数据，是指一旦遭到篡改、破坏、泄露或者非法获取、非法利用等，可能危害国家安全、经济运行、社会稳定、公共健康和安全等的数据。"},{"i":20,"n":"第二十条","txt":"本办法自2022年9月1日起施行。本办法施行前已经开展的数据出境活动，不符合本办法规定的，应当自本办法施行之日起6个月内完成整改。"}],"qicheshujuanquanguanliruoganguiding":[{"i":1,"n":"第一条","txt":"为了规范汽车数据处理活动，保护个人、组织的合法权益，维护国家安全和社会公共利益，促进汽车数据合理开发利用，根据《中华人民共和国网络安全法》、《中华人民共和国数据安全法》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内开展汽车数据处理活动及其安全监管，应当遵守相关法律、行政法规和本规定的要求。"},{"i":3,"n":"第三条","txt":"本规定所称汽车数据，包括汽车设计、生产、销售、使用、运维等过程中的涉及个人信息数据和重要数据。 汽车数据处理，包括汽车数据的收集、存储、使用、加工、传输、提供、公开等。 汽车数据处理者，是指开展汽车数据处理活动的组织，包括汽车制造商、零部件和软件供应商、经销商、维修机构以及出行服务企业等。 个人信息，是指以电子或者其他方式记录的与已识别或者可识别的车主、驾驶人、乘车人、车外人员等有关的各种信息，不包括匿名化处理后的信息。 敏感个人信息，是指一旦泄露或者非法使用，可能导致车主、驾驶人、乘车人、车外人员等受到歧视或者人身、财产安全受到严重危害的个人信息，包括车辆行踪轨迹、音频、视频、图像和生物识别特征等信息。 重要数据是指一旦遭到篡改、破坏、泄露或者非法获取、非法利用，可能危害国家安全、公共利益或者个人、组织合法权益的数据，包括： （一）军事管理区、国防科工单位以及县级以上党政机关等重要敏"},{"i":4,"n":"第四条","txt":"汽车数据处理者处理汽车数据应当合法、正当、具体、明确，与汽车的设计、生产、销售、使用、运维等直接相关。"},{"i":5,"n":"第五条","txt":"利用互联网等信息网络开展汽车数据处理活动，应当落实网络安全等级保护等制度，加强汽车数据保护，依法履行数据安全义务。"},{"i":6,"n":"第六条","txt":"国家鼓励汽车数据依法合理有效利用，倡导汽车数据处理者在开展汽车数据处理活动中坚持： （一）车内处理原则，除非确有必要不向车外提供； （二）默认不收集原则，除非驾驶人自主设定，每次驾驶时默认设定为不收集状态； （三）精度范围适用原则，根据所提供功能服务对数据精度的要求确定摄像头、雷达等的覆盖范围、分辨率； （四）脱敏处理原则，尽可能进行匿名化、去标识化等处理。"},{"i":7,"n":"第七条","txt":"汽车数据处理者处理个人信息应当通过用户手册、车载显示面板、语音、汽车使用相关应用程序等显著方式，告知个人以下事项： （一）处理个人信息的种类，包括车辆行踪轨迹、驾驶习惯、音频、视频、图像和生物识别特征等； （二）收集各类个人信息的具体情境以及停止收集的方式和途径； （三）处理各类个人信息的目的、用途、方式； （四）个人信息保存地点、保存期限，或者确定保存地点、保存期限的规则； （五）查阅、复制其个人信息以及删除车内、请求删除已经提供给车外的个人信息的方式和途径； （六）用户权益事务联系人的姓名和联系方式； （七）法律、行政法规规定的应当告知的其他事项。"},{"i":8,"n":"第八条","txt":"汽车数据处理者处理个人信息应当取得个人同意或者符合法律、行政法规规定的其他情形。 因保证行车安全需要，无法征得个人同意采集到车外个人信息且向车外提供的，应当进行匿名化处理，包括删除含有能够识别自然人的画面，或者对画面中的人脸信息等进行局部轮廓化处理等。"},{"i":9,"n":"第九条","txt":"汽车数据处理者处理敏感个人信息，应当符合以下要求或者符合法律、行政法规和强制性国家标准等其他要求： （一）具有直接服务于个人的目的，包括增强行车安全、智能驾驶、导航等； （二）通过用户手册、车载显示面板、语音以及汽车使用相关应用程序等显著方式告知必要性以及对个人的影响； （三）应当取得个人单独同意，个人可以自主设定同意期限； （四）在保证行车安全的前提下，以适当方式提示收集状态，为个人终止收集提供便利； （五）个人要求删除的，汽车数据处理者应当在十个工作日内删除。 汽车数据处理者具有增强行车安全的目的和充分的必要性，方可收集指纹、声纹、人脸、心律等生物识别特征信息。"},{"i":10,"n":"第十条","txt":"汽车数据处理者开展重要数据处理活动，应当按照规定开展风险评估，并向省、自治区、直辖市网信部门和有关部门报送风险评估报告。 风险评估报告应当包括处理的重要数据的种类、数量、范围、保存地点与期限、使用方式，开展数据处理活动情况以及是否向第三方提供，面临的数据安全风险及其应对措施等。"},{"i":11,"n":"第十一条","txt":"重要数据应当依法在境内存储，因业务需要确需向境外提供的，应当通过国家网信部门会同国务院有关部门组织的安全评估。未列入重要数据的涉及个人信息数据的出境安全管理，适用法律、行政法规的有关规定。 我国缔结或者参加的国际条约、协定有不同规定的，适用该国际条约、协定，但我国声明保留的条款除外。"},{"i":12,"n":"第十二条","txt":"汽车数据处理者向境外提供重要数据，不得超出出境安全评估时明确的目的、范围、方式和数据种类、规模等。 国家网信部门会同国务院有关部门以抽查等方式核验前款规定事项，汽车数据处理者应当予以配合，并以可读等便利方式予以展示。"},{"i":13,"n":"第十三条","txt":"汽车数据处理者开展重要数据处理活动，应当在每年十二月十五日前向省、自治区、直辖市网信部门和有关部门报送以下年度汽车数据安全管理情况： （一）汽车数据安全管理负责人、用户权益事务联系人的姓名和联系方式； （二）处理汽车数据的种类、规模、目的和必要性； （三）汽车数据的安全防护和管理措施，包括保存地点、期限等； （四）向境内第三方提供汽车数据情况； （五）汽车数据安全事件和处置情况； （六）汽车数据相关的用户投诉和处理情况； （七）国家网信部门会同国务院工业和信息化、公安、交通运输等有关部门明确的其他汽车数据安全管理情况。"},{"i":14,"n":"第十四条","txt":"向境外提供重要数据的汽车数据处理者应当在本规定第十三条要求的基础上，补充报告以下情况： （一）接收者的基本情况； （二）出境汽车数据的种类、规模、目的和必要性； （三）汽车数据在境外的保存地点、期限、范围和方式； （四）涉及向境外提供汽车数据的用户投诉和处理情况； （五）国家网信部门会同国务院工业和信息化、公安、交通运输等有关部门明确的向境外提供汽车数据需要报告的其他情况。"},{"i":15,"n":"第十五条","txt":"国家网信部门和国务院发展改革、工业和信息化、公安、交通运输等有关部门依据职责，根据处理数据情况对汽车数据处理者进行数据安全评估，汽车数据处理者应当予以配合。 参与安全评估的机构和人员不得披露评估中获悉的汽车数据处理者商业秘密、未公开信息，不得将评估中获悉的信息用于评估以外目的。"},{"i":16,"n":"第十六条","txt":"国家加强智能（网联）汽车网络平台建设，开展智能（网联）汽车入网运行和安全保障服务等，协同汽车数据处理者加强智能（网联）汽车网络和汽车数据安全防护。"},{"i":17,"n":"第十七条","txt":"汽车数据处理者开展汽车数据处理活动，应当建立投诉举报渠道，设置便捷的投诉举报入口，及时处理用户投诉举报。 开展汽车数据处理活动造成用户合法权益或者公共利益受到损害的，汽车数据处理者应当依法承担相应责任。"},{"i":18,"n":"第十八条","txt":"汽车数据处理者违反本规定的，由省级以上网信、工业和信息化、公安、交通运输等有关部门依照《中华人民共和国网络安全法》、《中华人民共和国数据安全法》等法律、行政法规的规定进行处罚；构成犯罪的，依法追究刑事责任。"},{"i":19,"n":"第十九条","txt":"本规定自2021年10月1日起施行。"}],"shengchengshirengongzhinengfuwuguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为了促进生成式人工智能健康发展和规范应用，维护国家安全和社会公共利益，保护公民、法人和其他组织的合法权益，根据《中华人民共和国网络安全法》、《中华人民共和国数据安全法》、《中华人民共和国个人信息保护法》、《中华人民共和国科学技术进步法》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"利用生成式人工智能技术向中华人民共和国境内公众提供生成文本、图片、音频、视频等内容的服务（以下称生成式人工智能服务），适用本办法。 国家对利用生成式人工智能服务从事新闻出版、影视制作、文艺创作等活动另有规定的，从其规定。 行业组织、企业、教育和科研机构、公共文化机构、有关专业机构等研发、应用生成式人工智能技术，未向境内公众提供生成式人工智能服务的，不适用本办法的规定。"},{"i":3,"n":"第三条","txt":"国家坚持发展和安全并重、促进创新和依法治理相结合的原则，采取有效措施鼓励生成式人工智能创新发展，对生成式人工智能服务实行包容审慎和分类分级监管。"},{"i":4,"n":"第四条","txt":"提供和使用生成式人工智能服务，应当遵守法律、行政法规，尊重社会公德和伦理道德，遵守以下规定： （一）坚持社会主义核心价值观，不得生成煽动颠覆国家政权、推翻社会主义制度，危害国家安全和利益、损害国家形象，煽动分裂国家、破坏国家统一和社会稳定，宣扬恐怖主义、极端主义，宣扬民族仇恨、民族歧视，暴力、淫秽色情，以及虚假有害信息等法律、行政法规禁止的内容； （二）在算法设计、训练数据选择、模型生成和优化、提供服务等过程中，采取有效措施防止产生民族、信仰、国别、地域、性别、年龄、职业、健康等歧视； （三）尊重知识产权、商业道德，保守商业秘密，不得利用算法、数据、平台等优势，实施垄断和不正当竞争行为； （四）尊重他人合法权益，不得危害他人身心健康，不得侵害他人肖像权、名誉权、荣誉权、隐私权和个人信息权益； （五）基于服务类型特点，采取有效措施，提升生成式人工智能服务的透明度，提高生成内容的准确性和可"},{"i":5,"n":"第五条","txt":"鼓励生成式人工智能技术在各行业、各领域的创新应用，生成积极健康、向上向善的优质内容，探索优化应用场景，构建应用生态体系。 支持行业组织、企业、教育和科研机构、公共文化机构、有关专业机构等在生成式人工智能技术创新、数据资源建设、转化应用、风险防范等方面开展协作。"},{"i":6,"n":"第六条","txt":"鼓励生成式人工智能算法、框架、芯片及配套软件平台等基础技术的自主创新，平等互利开展国际交流与合作，参与生成式人工智能相关国际规则制定。 推动生成式人工智能基础设施和公共训练数据资源平台建设。促进算力资源协同共享，提升算力资源利用效能。推动公共数据分类分级有序开放，扩展高质量的公共训练数据资源。鼓励采用安全可信的芯片、软件、工具、算力和数据资源。"},{"i":7,"n":"第七条","txt":"生成式人工智能服务提供者（以下称提供者）应当依法开展预训练、优化训练等训练数据处理活动，遵守以下规定： （一）使用具有合法来源的数据和基础模型； （二）涉及知识产权的，不得侵害他人依法享有的知识产权； （三）涉及个人信息的，应当取得个人同意或者符合法律、行政法规规定的其他情形； （四）采取有效措施提高训练数据质量，增强训练数据的真实性、准确性、客观性、多样性； （五）《中华人民共和国网络安全法》、《中华人民共和国数据安全法》、《中华人民共和国个人信息保护法》等法律、行政法规的其他有关规定和有关主管部门的相关监管要求。"},{"i":8,"n":"第八条","txt":"在生成式人工智能技术研发过程中进行数据标注的，提供者应当制定符合本办法要求的清晰、具体、可操作的标注规则；开展数据标注质量评估，抽样核验标注内容的准确性；对标注人员进行必要培训，提升尊法守法意识，监督指导标注人员规范开展标注工作。"},{"i":9,"n":"第九条","txt":"提供者应当依法承担网络信息内容生产者责任，履行网络信息安全义务。涉及个人信息的，依法承担个人信息处理者责任，履行个人信息保护义务。 提供者应当与注册其服务的生成式人工智能服务使用者（以下称使用者）签订服务协议，明确双方权利义务。"},{"i":10,"n":"第十条","txt":"提供者应当明确并公开其服务的适用人群、场合、用途，指导使用者科学理性认识和依法使用生成式人工智能技术，采取有效措施防范未成年人用户过度依赖或者沉迷生成式人工智能服务。"},{"i":11,"n":"第十一条","txt":"提供者对使用者的输入信息和使用记录应当依法履行保护义务，不得收集非必要个人信息，不得非法留存能够识别使用者身份的输入信息和使用记录，不得非法向他人提供使用者的输入信息和使用记录。 提供者应当依法及时受理和处理个人关于查阅、复制、更正、补充、删除其个人信息等的请求。"},{"i":12,"n":"第十二条","txt":"提供者应当按照《互联网信息服务深度合成管理规定》对图片、视频等生成内容进行标识。"},{"i":13,"n":"第十三条","txt":"提供者应当在其服务过程中，提供安全、稳定、持续的服务，保障用户正常使用。"},{"i":14,"n":"第十四条","txt":"提供者发现违法内容的，应当及时采取停止生成、停止传输、消除等处置措施，采取模型优化训练等措施进行整改，并向有关主管部门报告。 提供者发现使用者利用生成式人工智能服务从事违法活动的，应当依法依约采取警示、限制功能、暂停或者终止向其提供服务等处置措施，保存有关记录，并向有关主管部门报告。"},{"i":15,"n":"第十五条","txt":"提供者应当建立健全投诉、举报机制，设置便捷的投诉、举报入口，公布处理流程和反馈时限，及时受理、处理公众投诉举报并反馈处理结果。"},{"i":16,"n":"第十六条","txt":"网信、发展改革、教育、科技、工业和信息化、公安、广播电视、新闻出版等部门，依据各自职责依法加强对生成式人工智能服务的管理。 国家有关主管部门针对生成式人工智能技术特点及其在有关行业和领域的服务应用，完善与创新发展相适应的科学监管方式，制定相应的分类分级监管规则或者指引。"},{"i":17,"n":"第十七条","txt":"提供具有舆论属性或者社会动员能力的生成式人工智能服务的，应当按照国家有关规定开展安全评估，并按照《互联网信息服务算法推荐管理规定》履行算法备案和变更、注销备案手续。"},{"i":18,"n":"第十八条","txt":"使用者发现生成式人工智能服务不符合法律、行政法规和本办法规定的，有权向有关主管部门投诉、举报。"},{"i":19,"n":"第十九条","txt":"有关主管部门依据职责对生成式人工智能服务开展监督检查，提供者应当依法予以配合，按要求对训练数据来源、规模、类型、标注规则、算法机制机理等予以说明，并提供必要的技术、数据等支持和协助。 参与生成式人工智能服务安全评估和监督检查的相关机构和人员对在履行职责中知悉的国家秘密、商业秘密、个人隐私和个人信息应当依法予以保密，不得泄露或者非法向他人提供。"},{"i":20,"n":"第二十条","txt":"对来源于中华人民共和国境外向境内提供生成式人工智能服务不符合法律、行政法规和本办法规定的，国家网信部门应当通知有关机构采取技术措施和其他必要措施予以处置。"},{"i":21,"n":"第二十一条","txt":"提供者违反本办法规定的，由有关主管部门依照《中华人民共和国网络安全法》、《中华人民共和国数据安全法》、《中华人民共和国个人信息保护法》、《中华人民共和国科学技术进步法》等法律、行政法规的规定予以处罚；法律、行政法规没有规定的，由有关主管部门依据职责予以警告、通报批评，责令限期改正；拒不改正或者情节严重的，责令暂停提供相关服务。 构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":22,"n":"第二十二条","txt":"本办法下列用语的含义是： （一）生成式人工智能技术，是指具有文本、图片、音频、视频等内容生成能力的模型及相关技术。 （二）生成式人工智能服务提供者，是指利用生成式人工智能技术提供生成式人工智能服务（包括通过提供可编程接口等方式提供生成式人工智能服务）的组织、个人。 （三）生成式人工智能服务使用者，是指使用生成式人工智能服务生成内容的组织、个人。"},{"i":23,"n":"第二十三条","txt":"法律、行政法规规定提供生成式人工智能服务应当取得相关行政许可的，提供者应当依法取得许可。 外商投资生成式人工智能服务，应当符合外商投资相关法律、行政法规的规定。"},{"i":24,"n":"第二十四条","txt":"本办法自2023年8月15日起施行。"}],"dianxinhehulianwangyonghugerenxinxibaohuguiding":[{"i":1,"n":"第一条","txt":"为了保护电信和互联网用户的合法权益，维护网络信息安全，根据《全国人民代表大会常务委员会关于加强网络信息保护的决定》、《中华人民共和国电信条例》和《互联网信息服务管理办法》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内提供电信服务和互联网信息服务过程中收集、使用用户个人信息的活动，适用本规定。"},{"i":3,"n":"第三条","txt":"工业和信息化部和各省、自治区、直辖市通信管理局（以下统称电信管理机构）依法对电信和互联网用户个人信息保护工作实施监督管理。"},{"i":4,"n":"第四条","txt":"本规定所称用户个人信息，是指电信业务经营者和互联网信息服务提供者在提供服务的过程中收集的用户姓名、出生日期、身份证件号码、住址、电话号码、账号和密码等能够单独或者与其他信息结合识别用户的信息以及用户使用服务的时间、地点等信息。"},{"i":5,"n":"第五条","txt":"电信业务经营者、互联网信息服务提供者在提供服务的过程中收集、使用用户个人信息，应当遵循合法、正当、必要的原则。"},{"i":6,"n":"第六条","txt":"电信业务经营者、互联网信息服务提供者对其在提供服务过程中收集、使用的用户个人信息的安全负责。"},{"i":7,"n":"第七条","txt":"国家鼓励电信和互联网行业开展用户个人信息保护自律工作。"},{"i":8,"n":"第八条","txt":"电信业务经营者、互联网信息服务提供者应当制定用户个人信息收集、使用规则，并在其经营或者服务场所、网站等予以公布。"},{"i":9,"n":"第九条","txt":"未经用户同意，电信业务经营者、互联网信息服务提供者不得收集、使用用户个人信息。 电信业务经营者、互联网信息服务提供者收集、使用用户个人信息的，应当明确告知用户收集、使用信息的目的、方式和范围，查询、更正信息的渠道以及拒绝提供信息的后果等事项。 电信业务经营者、互联网信息服务提供者不得收集其提供服务所必需以外的用户个人信息或者将信息用于提供服务之外的目的，不得以欺骗、误导或者强迫等方式或者违反法律、行政法规以及双方的约定收集、使用信息。 电信业务经营者、互联网信息服务提供者在用户终止使用电信服务或者互联网信息服务后，应当停止对用户个人信息的收集和使用，并为用户提供注销号码或者账号的服务。 法律、行政法规对本条第一款至第四款规定的情形另有规定的，从其规定。"},{"i":10,"n":"第十条","txt":"电信业务经营者、互联网信息服务提供者及其工作人员对在提供服务过程中收集、使用的用户个人信息应当严格保密，不得泄露、篡改或者毁损，不得出售或者非法向他人提供。"},{"i":11,"n":"第十一条","txt":"电信业务经营者、互联网信息服务提供者委托他人代理市场销售和技术服务等直接面向用户的服务性工作，涉及收集、使用用户个人信息的，应当对代理人的用户个人信息保护工作进行监督和管理，不得委托不符合本规定有关用户个人信息保护要求的代理人代办相关服务。"},{"i":12,"n":"第十二条","txt":"电信业务经营者、互联网信息服务提供者应当建立用户投诉处理机制，公布有效的联系方式，接受与用户个人信息保护有关的投诉，并自接到投诉之日起十五日内答复投诉人。"},{"i":13,"n":"第十三条","txt":"电信业务经营者、互联网信息服务提供者应当采取以下措施防止用户个人信息泄露、毁损、篡改或者丢失： （一）确定各部门、岗位和分支机构的用户个人信息安全管理责任； （二）建立用户个人信息收集、使用及其相关活动的工作流程和安全管理制度； （三）对工作人员及代理人实行权限管理，对批量导出、复制、销毁信息实行审查，并采取防泄密措施； （四）妥善保管记录用户个人信息的纸介质、光介质、电磁介质等载体，并采取相应的安全储存措施； （五）对储存用户个人信息的信息系统实行接入审查，并采取防入侵、防病毒等措施； （六）记录对用户个人信息进行操作的人员、时间、地点、事项等信息； （七）按照电信管理机构的规定开展通信网络安全防护工作； （八）电信管理机构规定的其他必要措施。"},{"i":14,"n":"第十四条","txt":"电信业务经营者、互联网信息服务提供者保管的用户个人信息发生或者可能发生泄露、毁损、丢失的，应当立即采取补救措施；造成或者可能造成严重后果的，应当立即向准予其许可或者备案的电信管理机构报告，配合相关部门进行的调查处理。 电信管理机构应当对报告或者发现的可能违反本规定的行为的影响进行评估；影响特别重大的，相关省、自治区、直辖市通信管理局应当向工业和信息化部报告。电信管理机构在依据本规定作出处理决定前，可以要求电信业务经营者和互联网信息服务提供者暂停有关行为，电信业务经营者和互联网信息服务提供者应当执行。"},{"i":15,"n":"第十五条","txt":"电信业务经营者、互联网信息服务提供者应当对其工作人员进行用户个人信息保护相关知识、技能和安全责任培训。"},{"i":16,"n":"第十六条","txt":"电信业务经营者、互联网信息服务提供者应当对用户个人信息保护情况每年至少进行一次自查，记录自查情况，及时消除自查中发现的安全隐患。"},{"i":17,"n":"第十七条","txt":"电信管理机构应当对电信业务经营者、互联网信息服务提供者保护用户个人信息的情况实施监督检查。 电信管理机构实施监督检查时，可以要求电信业务经营者、互联网信息服务提供者提供相关材料，进入其生产经营场所调查情况，电信业务经营者、互联网信息服务提供者应当予以配合。 电信管理机构实施监督检查，应当记录监督检查的情况，不得妨碍电信业务经营者、互联网信息服务提供者正常的经营或者服务活动，不得收取任何费用。"},{"i":18,"n":"第十八条","txt":"电信管理机构及其工作人员对在履行职责中知悉的用户个人信息应当予以保密，不得泄露、篡改或者毁损，不得出售或者非法向他人提供。"},{"i":19,"n":"第十九条","txt":"电信管理机构实施电信业务经营许可及经营许可证年检时，应当对用户个人信息保护情况进行审查。"},{"i":20,"n":"第二十条","txt":"电信管理机构应当将电信业务经营者、互联网信息服务提供者违反本规定的行为记入其社会信用档案并予以公布。"},{"i":21,"n":"第二十一条","txt":"鼓励电信和互联网行业协会依法制定有关用户个人信息保护的自律性管理制度，引导会员加强自律管理，提高用户个人信息保护水平。"},{"i":22,"n":"第二十二条","txt":"电信业务经营者、互联网信息服务提供者违反本规定第八条、第十二条规定的，由电信管理机构依据职权责令限期改正，予以警告，可以并处一万元以下的罚款。"},{"i":23,"n":"第二十三条","txt":"电信业务经营者、互联网信息服务提供者违反本规定第九条至第十一条、第十三条至第十六条、第十七条第二款规定的，由电信管理机构依据职权责令限期改正，予以警告，可以并处一万元以上三万元以下的罚款，向社会公告；构成犯罪的，依法追究刑事责任。"},{"i":24,"n":"第二十四条","txt":"电信管理机构工作人员在对用户个人信息保护工作实施监督管理的过程中玩忽职守、滥用职权、徇私舞弊的，依法给予处理；构成犯罪的，依法追究刑事责任。"},{"i":25,"n":"第二十五条","txt":"本规定自2013年9月1日起施行。"}],"wangxinbumenxingzhengzhifachengxuguiding":[{"i":1,"n":"第一条","txt":"为了规范和保障网信部门依法履行职责，保护公民、法人和其他组织的合法权益，维护国家安全和公共利益，根据《中华人民共和国行政处罚法》、《中华人民共和国行政强制法》、《中华人民共和国网络安全法》、《中华人民共和国数据安全法》、《中华人民共和国个人信息保护法》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"网信部门实施行政处罚等行政执法，适用本规定。 本规定所称网信部门，是指国家互联网信息办公室和地方互联网信息办公室。"},{"i":3,"n":"第三条","txt":"网信部门实施行政执法，应当坚持处罚与教育相结合，做到事实清楚、证据确凿、依据准确、程序合法。"},{"i":4,"n":"第四条","txt":"国家网信部门依法建立本系统的行政执法监督制度。 上级网信部门对下级网信部门实施的行政执法进行监督。"},{"i":5,"n":"第五条","txt":"网信部门应当加强执法队伍和执法能力建设，建立健全执法人员培训、考试考核、资格管理和持证上岗制度。"},{"i":6,"n":"第六条","txt":"网信部门及其执法人员对在执法过程中知悉的国家秘密、商业秘密或者个人隐私，应当依法予以保密。"},{"i":7,"n":"第七条","txt":"执法人员与案件有直接利害关系或者有其他关系可能影响公正执法的，应当回避。 当事人认为执法人员与案件有直接利害关系或者有其他关系可能影响公正执法的，有权申请回避。 当事人提出回避申请的，网信部门应当依法审查，由网信部门负责人决定。决定作出之前，不停止调查。"},{"i":8,"n":"第八条","txt":"行政处罚由违法行为发生地的网信部门管辖。法律、行政法规、部门规章另有规定的，从其规定。 违法行为发生地包括违法行为人相关服务许可地或者备案地，主营业地、登记地，网站建立者、管理者、使用者所在地，网络接入地，服务器所在地，计算机等终端设备所在地等。"},{"i":9,"n":"第九条","txt":"县级以上网信部门依职权管辖本行政区域内的行政处罚案件。法律、行政法规另有规定的，从其规定。"},{"i":10,"n":"第十条","txt":"对当事人的同一个违法行为，两个以上网信部门都有管辖权的，由最先立案的网信部门管辖。 两个以上网信部门对管辖权有争议的，应当协商解决，协商不成的，报请共同的上一级网信部门指定管辖；也可以直接由共同的上一级网信部门指定管辖。"},{"i":11,"n":"第十一条","txt":"上级网信部门认为必要的，可以直接办理下级网信部门管辖的案件，也可以将本部门管辖的案件交由下级网信部门办理。法律、行政法规、部门规章明确规定案件应当由上级网信部门管辖的，上级网信部门不得将案件交由下级网信部门管辖。 下级网信部门对其管辖的案件由于特殊原因不能行使管辖权的，可以报请上级网信部门管辖或者指定管辖。 设区的市级以下网信部门发现其所管辖的行政处罚案件涉及国家安全等情形的，应当及时报告上一级网信部门，必要时报请上一级网信部门管辖。"},{"i":12,"n":"第十二条","txt":"网信部门发现受理的案件不属于其管辖的，应当及时移送有管辖权的网信部门。 受移送的网信部门应当将案件查处结果及时函告移送案件的网信部门；认为移送不当的，应当报请共同的上一级网信部门指定管辖，不得再次自行移送。"},{"i":13,"n":"第十三条","txt":"上级网信部门接到管辖争议或者报请指定管辖的请示后，应当在十个工作日内作出指定管辖的决定，并书面通知下级网信部门。"},{"i":14,"n":"第十四条","txt":"网信部门发现案件属于其他行政机关管辖的，应当依法移送有关行政机关。 网信部门发现违法行为涉嫌犯罪的，应当及时将案件移送司法机关。司法机关决定立案的，网信部门应当及时办结移交手续。 网信部门应当与司法机关加强协调配合，建立健全案件移送制度，加强证据材料移交、接收衔接，完善案件处理信息通报机制。"},{"i":15,"n":"第十五条","txt":"网信部门对依法应当由原许可、批准的部门作出降低资质等级、吊销许可证件等行政处罚决定的，应当将取得的证据及相关材料送原许可、批准的部门，由其依法作出是否降低资质等级、吊销许可证件等决定。"},{"i":16,"n":"第十六条","txt":"对当事人的同一个违法行为，不得给予两次以上罚款的行政处罚。同一个违法行为违反多个法律规范应当给予罚款处罚的，按照罚款数额高的规定处罚。"},{"i":17,"n":"第十七条","txt":"网信部门对下列事项应当及时调查处理，并填写案件来源登记表： （一）在监督检查中发现案件线索的； （二）自然人、法人或者其他组织投诉、申诉、举报的； （三）上级网信部门交办或者下级网信部门报请查处的； （四）有关机关移送的； （五）经由其他方式、途径发现的。"},{"i":18,"n":"第十八条","txt":"行政处罚立案应当符合下列条件： （一）有涉嫌违反法律、行政法规和部门规章的行为，依法应当予以行政处罚； （二）属于本部门管辖； （三）在应当给予行政处罚的法定期限内。 符合立案条件的，应当填写立案审批表，连同相关材料，在七个工作日内报网信部门负责人批准立案，并指定两名以上执法人员为案件承办人。情况特殊的，可以延长至十五个工作日内立案。 对于不予立案的投诉、申诉、举报，应当将不予立案的相关情况作书面记录留存。 对于其他机关移送的案件，决定不予立案的，应当书面告知移送机关。 不予立案或者撤销立案的，承办人应当制作不予立案审批表或者撤销立案审批表，报网信部门负责人批准。"},{"i":19,"n":"第十九条","txt":"网信部门进行案件调查取证，应当由具有行政执法资格的执法人员实施。执法人员不得少于两人，并应当主动向当事人或者有关人员出示执法证件。必要时，可以聘请专业人员进行协助。 首次向案件当事人收集、调取证据的，应当告知其有申请执法人员回避的权利。 向有关单位、个人收集、调取证据时，应当告知其有如实提供证据的义务。被调查对象和有关人员应当如实回答询问，协助和配合调查，及时提供依法应予保存的网络运营者发布的信息、用户发布的信息、日志信息等相关材料，不得阻挠、干扰案件的调查。"},{"i":20,"n":"第二十条","txt":"网信部门在执法过程中确需有关机关或者其他行政区域网信部门协助调查取证的，应当出具协助调查函，协助调查函应当载明需要协助的具体事项、期限等内容。 收到协助调查函的网信部门对属于本部门职权范围的协助事项应当予以协助，在接到协助调查函之日起十五个工作日内完成相关工作；需要延期完成或者无法协助的，应当及时函告提出协助请求的网信部门。"},{"i":21,"n":"第二十一条","txt":"执法人员应当依法收集与案件有关的证据，包括书证、物证、视听资料、电子数据、证人证言、当事人的陈述、鉴定意见、勘验笔录、现场笔录等。 电子数据是指案件发生过程中形成的，存在于计算机设备、移动通信设备、互联网服务器、移动存储设备、云存储系统等电子设备或者存储介质中，以数字化形式存储、处理、传输的，能够证明案件事实的数据。视听资料包括录音资料和影像资料。存储在电子介质中的录音资料和影像资料，适用电子数据的规定。 证据应当经查证属实，方可作为认定案件事实的根据。 以非法手段取得的证据，不得作为认定案件事实的根据。"},{"i":22,"n":"第二十二条","txt":"立案前调查和监督检查过程中依法取得的证据材料，可以作为案件的证据使用。 对于移送的案件，移送机关依职权调查收集的证据材料，可以作为案件的证据使用。"},{"i":23,"n":"第二十三条","txt":"网信部门在立案前，可以采取询问、勘验、检查、检测、检验、鉴定、调取相关材料等措施，不得限制调查对象的人身、财产权利。 网信部门立案后，可以对涉案物品、设施、场所采取先行登记保存等措施。"},{"i":24,"n":"第二十四条","txt":"网信部门在执法过程中询问当事人或者其他有关人员，应当制作询问笔录，载明时间、地点、事实、经过等内容。询问笔录应当交询问对象或者其他有关人员核对确认，并由执法人员和询问对象或者其他有关人员签名。询问对象和其他有关人员拒绝签名或者无法签名的，应当注明原因。"},{"i":25,"n":"第二十五条","txt":"网信部门对于涉及违法行为的场所、物品、网络应当进行勘验、检查，及时收集、固定书证、物证、视听资料和电子数据。"},{"i":26,"n":"第二十六条","txt":"网信部门可以委托司法鉴定机构就案件中的专门性问题出具鉴定意见；不属于司法鉴定范围的，可以委托有能力或者有条件的机构出具检测报告或者检验报告。"},{"i":27,"n":"第二十七条","txt":"网信部门可以向有关单位、个人调取能够证明案件事实的证据材料，并可以根据需要拍照、录像、复印和复制。 调取的书证、物证应当是原件、原物。调取原件、原物确有困难的，可以由提交证据的有关单位、个人在复制品上签字或者盖章，注明“此件由×××提供，经核对与原件（物）无异”的字样或者文字说明，注明出证日期、证据出处，并签名或者盖章。 调取的视听资料、电子数据应当是原始载体或者备份介质。调取原始载体或者备份介质确有困难的，可以收集复制件，并注明制作方法、制作时间、制作人等情况。调取声音资料的，应当附有该声音内容的文字记录。"},{"i":28,"n":"第二十八条","txt":"在证据可能灭失或者以后难以取得的情况下，经网信部门负责人批准，执法人员可以依法对涉案计算机、服务器、硬盘、移动存储设备、存储卡等涉嫌实施违法行为的物品先行登记保存，制作登记保存物品清单，向当事人出具登记保存物品通知书。先行登记保存期间，当事人和其他有关人员不得损毁、销毁或者转移证据。 网信部门实施先行登记保存的，应当通知当事人或者持有人到场，并在现场笔录中对采取的相关措施情况予以记载。"},{"i":29,"n":"第二十九条","txt":"网信部门对先行登记保存的证据，应当在七个工作日内作出以下处理决定： （一）需要采取证据保全措施的，采取记录、复制、拍照、录像等证据保全措施后予以返还； （二）需要检验、检测、鉴定的，送交具有相应资质的机构检验、检测、鉴定； （三）违法事实不成立，或者先行登记保存的证据与违法事实不具有关联性的，解除先行登记保存。 逾期未作出处理决定的，应当解除先行登记保存。 违法事实成立，依法应当予以没收的，依照法定程序实施行政处罚。"},{"i":30,"n":"第三十条","txt":"网信部门收集、保全电子数据，可以采取现场取证、远程取证和责令有关单位、个人固定和提交等措施。 现场取证、远程取证结束后，应当制作电子取证工作记录。"},{"i":31,"n":"第三十一条","txt":"执法人员在调查取证过程中，应当要求当事人在笔录和其他相关材料上签字、捺指印、盖章或者以其他方式确认。 当事人拒绝到场，拒绝签字、捺指印、盖章或者以其他方式确认，或者无法找到当事人的，应当由两名执法人员在笔录或者其他材料上注明原因，并邀请其他有关人员作为见证人签字或者盖章，也可以采取录音、录像等方式记录。"},{"i":32,"n":"第三十二条","txt":"对有证据证明是用于违法个人信息处理活动的设备、物品，可以采取查封或者扣押措施。 采取或者解除查封、扣押措施，应当向网信部门主要负责人书面报告并经批准。情况紧急，需要当场采取查封、扣押措施的，执法人员应当在二十四小时内向网信部门主要负责人报告，并补办批准手续。网信部门主要负责人认为不应当采取查封、扣押措施的，应当立即解除。"},{"i":33,"n":"第三十三条","txt":"案件调查终结后，承办人认为违法事实成立，应当予以行政处罚的，撰写案件处理意见报告，草拟行政处罚建议书。 有下列情形之一的，承办人撰写案件处理意见报告，说明拟作处理的理由，报网信部门负责人批准后根据不同情况分别处理： （一）认为违法事实不能成立，不予行政处罚的； （二）违法行为情节轻微并及时改正，没有造成危害后果，不予行政处罚的； （三）初次违法且危害后果轻微并及时改正，可以不予行政处罚的； （四）当事人有证据足以证明没有主观过错，不予行政处罚的，法律、行政法规另有规定的，从其规定； （五）案件不属于本部门管辖，应当移送其他行政机关管辖的； （六）涉嫌犯罪，应当移送司法机关的。"},{"i":34,"n":"第三十四条","txt":"网信部门在进行监督检查或者案件调查时，对已有证据证明违法事实成立的，应当责令当事人立即改正或者限期改正违法行为。"},{"i":35,"n":"第三十五条","txt":"对事实清楚、当事人自愿认错认罚且对违法事实和法律适用没有异议的行政处罚案件，网信部门应当快速办理案件。"},{"i":36,"n":"第三十六条","txt":"网信部门作出下列行政处罚决定前，应当告知当事人有要求举行听证的权利。当事人要求听证的，应当在被告知后五个工作日内提出，网信部门应当组织听证。当事人逾期未要求听证的，视为放弃听证的权利： （一）较大数额罚款； （二）没收较大数额违法所得、没收较大价值非法财物； （三）降低资质等级、吊销许可证件； （四）责令停产停业、责令关闭、限制从业； （五）其他较重的行政处罚； （六）法律、行政法规、部门规章规定的其他情形。"},{"i":37,"n":"第三十七条","txt":"网信部门应当在听证的七个工作日前，将听证通知书送达当事人，告知当事人及有关人员举行听证的时间、地点。 听证应当制作听证笔录，交当事人或者其代理人核对无误后签字或者盖章。当事人或者其代理人拒绝签字或者盖章的，由听证主持人在笔录中注明。 除涉及国家秘密、商业秘密或者个人隐私依法予以保密外，听证公开举行。 听证结束后，网信部门应当根据听证笔录，依照本规定第四十二条的规定，作出决定。"},{"i":38,"n":"第三十八条","txt":"网信部门对当事人作出行政处罚决定前，可以根据有关规定对其实施约谈，谈话结束后制作执法约谈笔录。"},{"i":39,"n":"第三十九条","txt":"网信部门作出行政处罚决定前，应当填写行政处罚意见告知书，告知当事人拟作出的行政处罚内容及事实、理由、依据，并告知当事人依法享有的陈述、申辩等权利。"},{"i":40,"n":"第四十条","txt":"当事人有权进行陈述和申辩。网信部门应当充分听取当事人的意见，对当事人提出的事实、理由和证据，应当进行复核；当事人提出的事实、理由或者证据成立的，网信部门应当采纳。 网信部门不得因当事人陈述、申辩而给予更重的处罚。 网信部门及其执法人员在作出行政处罚决定前，未依照本规定向当事人告知拟作出的行政处罚内容及事实、理由、依据，或者拒绝听取当事人的陈述、申辩，不得作出行政处罚决定，但当事人明确放弃陈述或者申辩权利的除外。"},{"i":41,"n":"第四十一条","txt":"有下列情形之一，在网信部门负责人作出行政处罚的决定之前，应当由从事行政处罚决定法制审核的人员进行法制审核；未经法制审核或者审核未通过的，不得作出决定： （一）涉及重大公共利益的； （二）直接关系当事人或者第三人重大权益，经过听证程序的； （三）案件情况疑难复杂、涉及多个法律关系的； （四）法律、行政法规规定应当进行法制审核的其他情形。 法制审核由网信部门确定的负责法制审核的机构实施。网信部门中初次从事行政处罚决定法制审核的人员，应当通过国家统一法律职业资格考试取得法律职业资格。"},{"i":42,"n":"第四十二条","txt":"拟作出的行政处罚决定应当报网信部门负责人审查。网信部门负责人根据不同情况，分别作出如下决定： （一）确有应受行政处罚的违法行为的，根据情节轻重及具体情况，作出行政处罚决定； （二）违法行为轻微，依法可以不予行政处罚的，不予行政处罚； （三）违法事实不能成立的，不予行政处罚； （四）违法行为涉嫌犯罪的，移送司法机关。"},{"i":43,"n":"第四十三条","txt":"对情节复杂或者重大违法行为给予行政处罚，网信部门负责人应当集体讨论决定。集体讨论决定的过程应当书面记录。"},{"i":44,"n":"第四十四条","txt":"网信部门作出行政处罚决定，应当制作统一编号的行政处罚决定书。 行政处罚决定书应当载明下列事项： （一）当事人的姓名或者名称、地址等基本情况； （二）违反法律、行政法规、部门规章的事实和证据； （三）行政处罚的种类和依据； （四）行政处罚的履行方式和期限； （五）申请行政复议、提起行政诉讼的途径和期限； （六）作出行政处罚决定的网信部门名称和作出决定的日期。 行政处罚决定中涉及没收有关物品的，还应当附没收物品凭证。 行政处罚决定书必须盖有作出行政处罚决定的网信部门的印章。"},{"i":45,"n":"第四十五条","txt":"网信部门应当自行政处罚案件立案之日起九十日内作出行政处罚决定。 因案情复杂等原因不能在规定期限内作出处理决定的，经本部门负责人批准，可以延长六十日。案情特别复杂或者情况特殊，经延期仍不能作出处理决定的，由上一级网信部门负责人决定是否继续延期，决定继续延期的，应当同时确定延长的合理期限；国家网信部门办理的行政处罚案件需要延期的，由本部门主要负责人批准。 案件处理过程中，听证、检测、检验、鉴定、行政协助等时间不计入本条第一款、第二款规定的期限。"},{"i":46,"n":"第四十六条","txt":"行政处罚决定书应当在宣告后当场交付当事人；当事人不在场的，应当在七个工作日内依照《中华人民共和国民事诉讼法》的有关规定，将行政处罚决定书送达当事人。 当事人同意并签订确认书的，网信部门可以采用传真、电子邮件等方式，将行政处罚决定书等送达当事人。"},{"i":47,"n":"第四十七条","txt":"行政处罚决定书送达后，当事人应当在行政处罚决定书载明的期限内予以履行。 当事人确有经济困难，可以提出延期或者分期缴纳罚款的申请，并提交书面材料。经案件承办人审核，确定延期或者分期缴纳罚款的期限和金额，报网信部门负责人批准后，可以暂缓或者分期缴纳。"},{"i":48,"n":"第四十八条","txt":"网络运营者违反相关法律、行政法规、部门规章规定，需由电信主管部门关闭网站、吊销相关增值电信业务经营许可证或者取消备案的，转电信主管部门处理。"},{"i":49,"n":"第四十九条","txt":"当事人对行政处罚决定不服，可以依法申请行政复议或者提起行政诉讼。 当事人对行政处罚决定不服，申请行政复议或者提起行政诉讼的，行政处罚不停止执行，法律另有规定的除外。 当事人申请行政复议或者提起行政诉讼的，加处罚款的数额在行政复议或者行政诉讼期间不予计算。"},{"i":50,"n":"第五十条","txt":"当事人逾期不履行行政处罚决定的，作出行政处罚决定的网信部门可以采取下列措施： （一）到期不缴纳罚款的，每日按罚款数额的百分之三加处罚款，加处罚款的数额不得超出罚款的数额； （二）依照《中华人民共和国行政强制法》的规定申请人民法院强制执行。 网信部门批准延期、分期缴纳罚款的，申请人民法院强制执行的期限，自暂缓或者分期缴纳罚款期限结束之日起计算。"},{"i":51,"n":"第五十一条","txt":"网信部门申请人民法院强制执行的，申请前应当填写履行行政处罚决定催告书，书面催告当事人履行义务，并告知履行义务的期限和方式、依法享有的陈述和申辩权；涉及加处罚款的，应当有明确的金额和给付方式。 当事人进行陈述、申辩的，网信部门应当对当事人提出的事实、理由和证据进行记录、复核，并制作陈述申辩笔录、陈述申辩复核意见书。当事人提出的事实、理由或者证据成立的，网信部门应当采纳。 履行行政处罚决定催告书送达十个工作日后，当事人仍未履行处罚决定的，网信部门可以填写行政处罚强制执行申请书，向所在地有管辖权的人民法院申请强制执行。"},{"i":52,"n":"第五十二条","txt":"行政处罚决定履行或者执行后，有下列情形之一的，执法人员应当填写行政处罚结案报告，将有关案件材料进行整理装订，归档保存： （一）行政处罚决定履行或者执行完毕的； （二）人民法院裁定终结执行的； （三）案件终止调查的； （四）作出本规定第四十二条第二项至第四项决定的； （五）其他应当予以结案的情形。 结案后，执法人员应当将案件材料按照档案管理的有关规定立卷归档。案卷归档应当一案一卷、材料齐全、规范有序。"},{"i":53,"n":"第五十三条","txt":"网信部门应当依法以文字、音像等形式，对行政处罚的启动、调查取证、审核、决定、送达、执行等进行全过程记录，归档保存。"},{"i":54,"n":"第五十四条","txt":"网信部门实施行政处罚应当接受社会监督。公民、法人或者其他组织对网信部门实施行政处罚的行为，有权申诉或者检举；网信部门应当认真审查，发现有错误的，应当主动改正。"},{"i":55,"n":"第五十五条","txt":"本规定中的期限以时、日计算，开始的时和日不计算在内。期限届满的最后一日是法定节假日的，以法定节假日后的第一日为届满的日期。但是，法律、行政法规另有规定的除外。"},{"i":56,"n":"第五十六条","txt":"本规定中的“以上”、“以下”、“内”均包括本数、本级。"},{"i":57,"n":"第五十七条","txt":"国家网信部门负责制定行政执法相关文书格式范本。各省、自治区、直辖市网信部门可以参照文书格式范本，制定本行政区域行政执法所适用的文书格式并自行印制。"},{"i":58,"n":"第五十八条","txt":"本规定自2023年6月1日起施行。2017年5月2日公布的《互联网信息内容管理行政执法程序规定》（国家互联网信息办公室令第2号）同时废止。"}],"wangluoxinxineirongshengtaizhiliguiding":[{"i":1,"n":"第一条","txt":"为了营造良好网络生态，保障公民、法人和其他组织的合法权益，维护国家安全和公共利益，根据《中华人民共和国国家安全法》、《中华人民共和国网络安全法》、《互联网信息服务管理办法》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内的网络信息内容生态治理活动，适用本规定。 本规定所称网络信息内容生态治理，是指政府、企业、社会、网民等主体，以培育和践行社会主义核心价值观为根本，以网络信息内容为主要治理对象，以建立健全网络综合治理体系、营造清朗的网络空间、建设良好的网络生态为目标，开展的弘扬正能量、处置违法和不良信息等相关活动。"},{"i":3,"n":"第三条","txt":"国家网信部门负责统筹协调全国网络信息内容生态治理和相关监督管理工作，各有关主管部门依据各自职责做好网络信息内容生态治理工作。 地方网信部门负责统筹协调本行政区域内网络信息内容生态治理和相关监督管理工作，地方各有关主管部门依据各自职责做好本行政区域内网络信息内容生态治理工作。"},{"i":4,"n":"第四条","txt":"网络信息内容生产者应当遵守法律法规，遵循公序良俗，不得损害国家利益、公共利益和他人合法权益。"},{"i":5,"n":"第五条","txt":"鼓励网络信息内容生产者制作、复制、发布含有下列内容的信息： （一）宣传习近平新时代中国特色社会主义思想，全面准确生动解读中国特色社会主义道路、理论、制度、文化的； （二）宣传党的理论路线方针政策和中央重大决策部署的； （三）展示经济社会发展亮点，反映人民群众伟大奋斗和火热生活的； （四）弘扬社会主义核心价值观，宣传优秀道德文化和时代精神，充分展现中华民族昂扬向上精神风貌的； （五）有效回应社会关切，解疑释惑，析事明理，有助于引导群众形成共识的； （六）有助于提高中华文化国际影响力，向世界展现真实立体全面的中国的； （七）其他讲品味讲格调讲责任、讴歌真善美、促进团结稳定等的内容。"},{"i":6,"n":"第六条","txt":"网络信息内容生产者不得制作、复制、发布含有下列内容的违法信息： （一）反对宪法所确定的基本原则的； （二）危害国家安全，泄露国家秘密，颠覆国家政权，破坏国家统一的； （三）损害国家荣誉和利益的； （四）歪曲、丑化、亵渎、否定英雄烈士事迹和精神，以侮辱、诽谤或者其他方式侵害英雄烈士的姓名、肖像、名誉、荣誉的； （五）宣扬恐怖主义、极端主义或者煽动实施恐怖活动、极端主义活动的； （六）煽动民族仇恨、民族歧视，破坏民族团结的； （七）破坏国家宗教政策，宣扬邪教和封建迷信的； （八）散布谣言，扰乱经济秩序和社会秩序的； （九）散布淫秽、色情、赌博、暴力、凶杀、恐怖或者教唆犯罪的； （十）侮辱或者诽谤他人，侵害他人名誉、隐私和其他合法权益的； （十一）法律、行政法规禁止的其他内容。"},{"i":7,"n":"第七条","txt":"网络信息内容生产者应当采取措施，防范和抵制制作、复制、发布含有下列内容的不良信息： （一）使用夸张标题，内容与标题严重不符的； （二）炒作绯闻、丑闻、劣迹等的； （三）不当评述自然灾害、重大事故等灾难的； （四）带有性暗示、性挑逗等易使人产生性联想的； （五）展现血腥、惊悚、残忍等致人身心不适的； （六）煽动人群歧视、地域歧视等的； （七）宣扬低俗、庸俗、媚俗内容的； （八）可能引发未成年人模仿不安全行为和违反社会公德行为、诱导未成年人不良嗜好等的； （九）其他对网络生态造成不良影响的内容。"},{"i":8,"n":"第八条","txt":"网络信息内容服务平台应当履行信息内容管理主体责任，加强本平台网络信息内容生态治理，培育积极健康、向上向善的网络文化。"},{"i":9,"n":"第九条","txt":"网络信息内容服务平台应当建立网络信息内容生态治理机制，制定本平台网络信息内容生态治理细则，健全用户注册、账号管理、信息发布审核、跟帖评论审核、版面页面生态管理、实时巡查、应急处置和网络谣言、黑色产业链信息处置等制度。 网络信息内容服务平台应当设立网络信息内容生态治理负责人，配备与业务范围和服务规模相适应的专业人员，加强培训考核，提升从业人员素质。"},{"i":10,"n":"第十条","txt":"网络信息内容服务平台不得传播本规定第六条规定的信息，应当防范和抵制传播本规定第七条规定的信息。 网络信息内容服务平台应当加强信息内容的管理，发现本规定第六条、第七条规定的信息的，应当依法立即采取处置措施，保存有关记录，并向有关主管部门报告。"},{"i":11,"n":"第十一条","txt":"鼓励网络信息内容服务平台坚持主流价值导向，优化信息推荐机制，加强版面页面生态管理，在下列重点环节（包括服务类型、位置版块等）积极呈现本规定第五条规定的信息： （一）互联网新闻信息服务首页首屏、弹窗和重要新闻信息内容页面等； （二）互联网用户公众账号信息服务精选、热搜等； （三）博客、微博客信息服务热门推荐、榜单类、弹窗及基于地理位置的信息服务版块等； （四）互联网信息搜索服务热搜词、热搜图及默认搜索等； （五）互联网论坛社区服务首页首屏、榜单类、弹窗等； （六）互联网音视频服务首页首屏、发现、精选、榜单类、弹窗等； （七）互联网网址导航服务、浏览器服务、输入法服务首页首屏、榜单类、皮肤、联想词、弹窗等； （八）数字阅读、网络游戏、网络动漫服务首页首屏、精选、榜单类、弹窗等； （九）生活服务、知识服务平台首页首屏、热门推荐、弹窗等； （十）电子商务平台首页首屏、推荐区等； （十一）移动应"},{"i":12,"n":"第十二条","txt":"网络信息内容服务平台采用个性化算法推荐技术推送信息的，应当设置符合本规定第十条、第十一条规定要求的推荐模型，建立健全人工干预和用户自主选择机制。"},{"i":13,"n":"第十三条","txt":"鼓励网络信息内容服务平台开发适合未成年人使用的模式，提供适合未成年人使用的网络产品和服务，便利未成年人获取有益身心健康的信息。"},{"i":14,"n":"第十四条","txt":"网络信息内容服务平台应当加强对本平台设置的广告位和在本平台展示的广告内容的审核巡查，对发布违法广告的，应当依法予以处理。"},{"i":15,"n":"第十五条","txt":"网络信息内容服务平台应当制定并公开管理规则和平台公约，完善用户协议，明确用户相关权利义务，并依法依约履行相应管理职责。 网络信息内容服务平台应当建立用户账号信用管理制度，根据用户账号的信用情况提供相应服务。"},{"i":16,"n":"第十六条","txt":"网络信息内容服务平台应当在显著位置设置便捷的投诉举报入口，公布投诉举报方式，及时受理处置公众投诉举报并反馈处理结果。"},{"i":17,"n":"第十七条","txt":"网络信息内容服务平台应当编制网络信息内容生态治理工作年度报告，年度报告应当包括网络信息内容生态治理工作情况、网络信息内容生态治理负责人履职情况、社会评价情况等内容。"},{"i":18,"n":"第十八条","txt":"网络信息内容服务使用者应当文明健康使用网络，按照法律法规的要求和用户协议约定，切实履行相应义务，在以发帖、回复、留言、弹幕等形式参与网络活动时，文明互动，理性表达，不得发布本规定第六条规定的信息，防范和抵制本规定第七条规定的信息。"},{"i":19,"n":"第十九条","txt":"网络群组、论坛社区版块建立者和管理者应当履行群组、版块管理责任，依据法律法规、用户协议和平台公约等，规范群组、版块内信息发布等行为。"},{"i":20,"n":"第二十条","txt":"鼓励网络信息内容服务使用者积极参与网络信息内容生态治理，通过投诉、举报等方式对网上违法和不良信息进行监督，共同维护良好网络生态。"},{"i":21,"n":"第二十一条","txt":"网络信息内容服务使用者和网络信息内容生产者、网络信息内容服务平台不得利用网络和相关信息技术实施侮辱、诽谤、威胁、散布谣言以及侵犯他人隐私等违法行为，损害他人合法权益。"},{"i":22,"n":"第二十二条","txt":"网络信息内容服务使用者和网络信息内容生产者、网络信息内容服务平台不得通过发布、删除信息以及其他干预信息呈现的手段侵害他人合法权益或者谋取非法利益。"},{"i":23,"n":"第二十三条","txt":"网络信息内容服务使用者和网络信息内容生产者、网络信息内容服务平台不得利用深度学习、虚拟现实等新技术新应用从事法律、行政法规禁止的活动。"},{"i":24,"n":"第二十四条","txt":"网络信息内容服务使用者和网络信息内容生产者、网络信息内容服务平台不得通过人工方式或者技术手段实施流量造假、流量劫持以及虚假注册账号、非法交易账号、操纵用户账号等行为，破坏网络生态秩序。"},{"i":25,"n":"第二十五条","txt":"网络信息内容服务使用者和网络信息内容生产者、网络信息内容服务平台不得利用党旗、党徽、国旗、国徽、国歌等代表党和国家形象的标识及内容，或者借国家重大活动、重大纪念日和国家机关及其工作人员名义等，违法违规开展网络商业营销活动。"},{"i":26,"n":"第二十六条","txt":"鼓励行业组织发挥服务指导和桥梁纽带作用，引导会员单位增强社会责任感，唱响主旋律，弘扬正能量，反对违法信息，防范和抵制不良信息。"},{"i":27,"n":"第二十七条","txt":"鼓励行业组织建立完善行业自律机制，制定网络信息内容生态治理行业规范和自律公约，建立内容审核标准细则，指导会员单位建立健全服务规范、依法提供网络信息内容服务、接受社会监督。"},{"i":28,"n":"第二十八条","txt":"鼓励行业组织开展网络信息内容生态治理教育培训和宣传引导工作，提升会员单位、从业人员治理能力，增强全社会共同参与网络信息内容生态治理意识。"},{"i":29,"n":"第二十九条","txt":"鼓励行业组织推动行业信用评价体系建设，依据章程建立行业评议等评价奖惩机制，加大对会员单位的激励和惩戒力度，强化会员单位的守信意识。"},{"i":30,"n":"第三十条","txt":"各级网信部门会同有关主管部门，建立健全信息共享、会商通报、联合执法、案件督办、信息公开等工作机制，协同开展网络信息内容生态治理工作。"},{"i":31,"n":"第三十一条","txt":"各级网信部门对网络信息内容服务平台履行信息内容管理主体责任情况开展监督检查，对存在问题的平台开展专项督查。 网络信息内容服务平台对网信部门和有关主管部门依法实施的监督检查，应当予以配合。"},{"i":32,"n":"第三十二条","txt":"各级网信部门建立网络信息内容服务平台违法违规行为台账管理制度，并依法依规进行相应处理。"},{"i":33,"n":"第三十三条","txt":"各级网信部门建立政府、企业、社会、网民等主体共同参与的监督评价机制，定期对本行政区域内网络信息内容服务平台生态治理情况进行评估。"},{"i":34,"n":"第三十四条","txt":"网络信息内容生产者违反本规定第六条规定的，网络信息内容服务平台应当依法依约采取警示整改、限制功能、暂停更新、关闭账号等处置措施，及时消除违法信息内容，保存记录并向有关主管部门报告。"},{"i":35,"n":"第三十五条","txt":"网络信息内容服务平台违反本规定第十条、第三十一条第二款规定的，由网信等有关主管部门依据职责，按照《中华人民共和国网络安全法》、《互联网信息服务管理办法》等法律、行政法规的规定予以处理。"},{"i":36,"n":"第三十六条","txt":"网络信息内容服务平台违反本规定第十一条第二款规定的，由设区的市级以上网信部门依据职责进行约谈，给予警告，责令限期改正；拒不改正或者情节严重的，责令暂停信息更新，按照有关法律、行政法规的规定予以处理。"},{"i":37,"n":"第三十七条","txt":"网络信息内容服务平台违反本规定第九条、第十二条、第十五条、第十六条、第十七条规定的，由设区的市级以上网信部门依据职责进行约谈，给予警告，责令限期改正；拒不改正或者情节严重的，责令暂停信息更新，按照有关法律、行政法规的规定予以处理。"},{"i":38,"n":"第三十八条","txt":"违反本规定第十四条、第十八条、第十九条、第二十一条、第二十二条、第二十三条、第二十四条、第二十五条规定的，由网信等有关主管部门依据职责，按照有关法律、行政法规的规定予以处理。"},{"i":39,"n":"第三十九条","txt":"网信部门根据法律、行政法规和国家有关规定，会同有关主管部门建立健全网络信息内容服务严重失信联合惩戒机制，对严重违反本规定的网络信息内容服务平台、网络信息内容生产者和网络信息内容使用者依法依规实施限制从事网络信息服务、网上行为限制、行业禁入等惩戒措施。"},{"i":40,"n":"第四十条","txt":"违反本规定，给他人造成损害的，依法承担民事责任；构成犯罪的，依法追究刑事责任；尚不构成犯罪的，由有关主管部门依照有关法律、行政法规的规定予以处罚。"},{"i":41,"n":"第四十一条","txt":"本规定所称网络信息内容生产者，是指制作、复制、发布网络信息内容的组织或者个人。 本规定所称网络信息内容服务平台，是指提供网络信息内容传播服务的网络信息服务提供者。 本规定所称网络信息内容服务使用者，是指使用网络信息内容服务的组织或者个人。"},{"i":42,"n":"第四十二条","txt":"本规定自2020年3月1日起施行。"}],"wangluochubanfuwuguanliguiding-3":[{"i":1,"n":"第一条","txt":"为了规范网络出版服务秩序，促进网络出版服务业健康有序发展，根据《出版管理条例》、《互联网信息服务管理办法》及相关法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事网络出版服务，适用本规定。 本规定所称网络出版服务，是指通过信息网络向公众提供网络出版物。 本规定所称网络出版物，是指通过信息网络向公众提供的，具有编辑、制作、加工等出版特征的数字化作品，范围主要包括： （一）文学、艺术、科学等领域内具有知识性、思想性的文字、图片、地图、游戏、动漫、音视频读物等原创数字化作品； （二）与已出版的图书、报纸、期刊、音像制品、电子出版物等内容相一致的数字化作品； （三）将上述作品通过选择、编排、汇集等方式形成的网络文献数据库等数字化作品； （四）国家新闻出版广电总局认定的其他类型的数字化作品。 网络出版服务的具体业务分类另行制定。"},{"i":3,"n":"第三条","txt":"从事网络出版服务，应当遵守宪法和有关法律、法规，坚持为人民服务、为社会主义服务的方向，坚持社会主义先进文化的前进方向，弘扬社会主义核心价值观，传播和积累一切有益于提高民族素质、推动经济发展、促进社会进步的思想道德、科学技术和文化知识，满足人民群众日益增长的精神文化需要。"},{"i":4,"n":"第四条","txt":"国家新闻出版广电总局作为网络出版服务的行业主管部门，负责全国网络出版服务的前置审批和监督管理工作。工业和信息化部作为互联网行业主管部门，依据职责对全国网络出版服务实施相应的监督管理。 地方人民政府各级出版行政主管部门和各省级电信主管部门依据各自职责对本行政区域内网络出版服务及接入服务实施相应的监督管理工作并做好配合工作。"},{"i":5,"n":"第五条","txt":"出版行政主管部门根据已经取得的违法嫌疑证据或者举报，对涉嫌违法从事网络出版服务的行为进行查处时，可以检查与涉嫌违法行为有关的物品和经营场所；对有证据证明是与违法行为有关的物品，可以查封或者扣押。"},{"i":6,"n":"第六条","txt":"国家鼓励图书、音像、电子、报纸、期刊出版单位从事网络出版服务，加快与新媒体的融合发展。 国家鼓励组建网络出版服务行业协会，按照章程，在出版行政主管部门的指导下制定行业自律规范，倡导网络文明，传播健康有益内容，抵制不良有害内容。"},{"i":7,"n":"第七条","txt":"从事网络出版服务，必须依法经过出版行政主管部门批准，取得《网络出版服务许可证》。"},{"i":8,"n":"第八条","txt":"图书、音像、电子、报纸、期刊出版单位从事网络出版服务，应当具备以下条件： （一）有确定的从事网络出版业务的网站域名、智能终端应用程序等出版平台； （二）有确定的网络出版服务范围； （三）有从事网络出版服务所需的必要的技术设备，相关服务器和存储设备必须存放在中华人民共和国境内。"},{"i":9,"n":"第九条","txt":"其他单位从事网络出版服务，除第八条所列条件外，还应当具备以下条件： （一）有确定的、不与其他出版单位相重复的，从事网络出版服务主体的名称及章程； （二）有符合国家规定的法定代表人和主要负责人，法定代表人必须是在境内长久居住的具有完全行为能力的中国公民，法定代表人和主要负责人至少1人应当具有中级以上出版专业技术人员职业资格； （三）除法定代表人和主要负责人外，有适应网络出版服务范围需要的8名以上具有国家新闻出版广电总局认可的出版及相关专业技术职业资格的专职编辑出版人员，其中具有中级以上职业资格的人员不得少于3名； （四）有从事网络出版服务所需的内容审校制度； （五）有固定的工作场所； （六）法律、行政法规和国家新闻出版广电总局规定的其他条件。"},{"i":10,"n":"第十条","txt":"中外合资经营、中外合作经营和外资经营的单位不得从事网络出版服务。 网络出版服务单位与境内中外合资经营、中外合作经营、外资经营企业或境外组织及个人进行网络出版服务业务的项目合作，应当事前报国家新闻出版广电总局审批。"},{"i":11,"n":"第十一条","txt":"申请从事网络出版服务，应当向所在地省、自治区、直辖市出版行政主管部门提出申请，经审核同意后，报国家新闻出版广电总局审批。国家新闻出版广电总局应当自受理申请之日起60日内，作出批准或者不予批准的决定。不批准的，应当说明理由。"},{"i":12,"n":"第十二条","txt":"从事网络出版服务的申报材料，应该包括下列内容： （一）《网络出版服务许可证申请表》； （二）单位章程及资本来源性质证明； （三）网络出版服务可行性分析报告，包括资金使用、产品规划、技术条件、设备配备、机构设置、人员配备、市场分析、风险评估、版权保护措施等； （四）法定代表人和主要负责人的简历、住址、身份证明文件； （五）编辑出版等相关专业技术人员的国家认可的职业资格证明和主要从业经历及培训证明； （六）工作场所使用证明； （七）网站域名注册证明、相关服务器存放在中华人民共和国境内的承诺。 本规定第八条所列单位从事网络出版服务的，仅提交前款（一）、（六）、（七）项规定的材料。"},{"i":13,"n":"第十三条","txt":"设立网络出版服务单位的申请者应自收到批准决定之日起30日内办理注册登记手续： （一）持批准文件到所在地省、自治区、直辖市出版行政主管部门领取并填写《网络出版服务许可登记表》； （二）省、自治区、直辖市出版行政主管部门对《网络出版服务许可登记表》审核无误后，在10日内向申请者发放《网络出版服务许可证》； （三）《网络出版服务许可登记表》一式三份，由申请者和省、自治区、直辖市出版行政主管部门各存一份，另一份由省、自治区、直辖市出版行政主管部门在15日内报送国家新闻出版广电总局备案。"},{"i":14,"n":"第十四条","txt":"《网络出版服务许可证》有效期为5年。有效期届满，需继续从事网络出版服务活动的，应于有效期届满60日前按本规定第十一条的程序提出申请。出版行政主管部门应当在该许可有效期届满前作出是否准予延续的决定。批准的，换发《网络出版服务许可证》。"},{"i":15,"n":"第十五条","txt":"网络出版服务经批准后，申请者应持批准文件、《网络出版服务许可证》到所在地省、自治区、直辖市电信主管部门办理相关手续。"},{"i":16,"n":"第十六条","txt":"网络出版服务单位变更《网络出版服务许可证》许可登记事项、资本结构，合并或者分立，设立分支机构的，应依据本规定第十一条办理审批手续，并应持批准文件到所在地省、自治区、直辖市电信主管部门办理相关手续。"},{"i":17,"n":"第十七条","txt":"网络出版服务单位中止网络出版服务的，应当向所在地省、自治区、直辖市出版行政主管部门备案，并说明理由和期限；网络出版服务单位中止网络出版服务不得超过180日。 网络出版服务单位终止网络出版服务的，应当自终止网络出版服务之日起30日内，向所在地省、自治区、直辖市出版行政主管部门办理注销手续后到省、自治区、直辖市电信主管部门办理相关手续。省、自治区、直辖市出版行政主管部门将相关信息报国家新闻出版广电总局备案。"},{"i":18,"n":"第十八条","txt":"网络出版服务单位自登记之日起满180日未开展网络出版服务的，由原登记的出版行政主管部门注销登记，并报国家新闻出版广电总局备案。同时，通报相关省、自治区、直辖市电信主管部门。 因不可抗力或者其他正当理由发生上述所列情形的，网络出版服务单位可以向原登记的出版行政主管部门申请延期。"},{"i":19,"n":"第十九条","txt":"网络出版服务单位应当在其网站首页上标明出版行政主管部门核发的《网络出版服务许可证》编号。 互联网相关服务提供者在为网络出版服务单位提供人工干预搜索排名、广告、推广等服务时，应当查验服务对象的《网络出版服务许可证》及业务范围。"},{"i":20,"n":"第二十条","txt":"网络出版服务单位应当按照批准的业务范围从事网络出版服务，不得超出批准的业务范围从事网络出版服务。"},{"i":21,"n":"第二十一条","txt":"网络出版服务单位不得转借、出租、出卖《网络出版服务许可证》或以任何形式转让网络出版服务许可。 网络出版服务单位允许其他网络信息服务提供者以其名义提供网络出版服务，属于前款所称禁止行为。"},{"i":22,"n":"第二十二条","txt":"网络出版服务单位实行特殊管理股制度，具体办法由国家新闻出版广电总局另行制定。"},{"i":23,"n":"第二十三条","txt":"网络出版服务单位实行编辑责任制度，保障网络出版物内容合法。 网络出版服务单位实行出版物内容审核责任制度、责任编辑制度、责任校对制度等管理制度，保障网络出版物出版质量。 在网络上出版其他出版单位已在境内合法出版的作品且不改变原出版物内容的，须在网络出版物的相应页面显著标明原出版单位名称以及书号、刊号、网络出版物号或者网址信息。"},{"i":24,"n":"第二十四条","txt":"网络出版物不得含有以下内容： （一）反对宪法确定的基本原则的； （二）危害国家统一、主权和领土完整的； （三）泄露国家秘密、危害国家安全或者损害国家荣誉和利益的； （四）煽动民族仇恨、民族歧视，破坏民族团结，或者侵害民族风俗、习惯的； （五）宣扬邪教、迷信的； （六）散布谣言，扰乱社会秩序，破坏社会稳定的； （七）宣扬淫秽、色情、赌博、暴力或者教唆犯罪的； （八）侮辱或者诽谤他人，侵害他人合法权益的； （九）危害社会公德或者民族优秀文化传统的； （十）有法律、行政法规和国家规定禁止的其他内容的。"},{"i":25,"n":"第二十五条","txt":"为保护未成年人合法权益，网络出版物不得含有诱发未成年人模仿违反社会公德和违法犯罪行为的内容，不得含有恐怖、残酷等妨害未成年人身心健康的内容，不得含有披露未成年人个人隐私的内容。"},{"i":26,"n":"第二十六条","txt":"网络出版服务单位出版涉及国家安全、社会安定等方面重大选题的内容，应当按照国家新闻出版广电总局有关重大选题备案管理的规定办理备案手续。未经备案的重大选题内容，不得出版。"},{"i":27,"n":"第二十七条","txt":"网络游戏上网出版前，必须向所在地省、自治区、直辖市出版行政主管部门提出申请，经审核同意后，报国家新闻出版广电总局审批。"},{"i":28,"n":"第二十八条","txt":"网络出版物的内容不真实或不公正，致使公民、法人或者其他组织合法权益受到侵害的，相关网络出版服务单位应当停止侵权，公开更正，消除影响，并依法承担其他民事责任。"},{"i":29,"n":"第二十九条","txt":"国家对网络出版物实行标识管理，具体办法由国家新闻出版广电总局另行制定。"},{"i":30,"n":"第三十条","txt":"网络出版物必须符合国家的有关规定和标准要求，保证出版物质量。 网络出版物使用语言文字，必须符合国家法律规定和有关标准规范。"},{"i":31,"n":"第三十一条","txt":"网络出版服务单位应当按照国家有关规定或技术标准，配备应用必要的设备和系统，建立健全各项管理制度，保障信息安全、内容合法，并为出版行政主管部门依法履行监督管理职责提供技术支持。"},{"i":32,"n":"第三十二条","txt":"网络出版服务单位在网络上提供境外出版物，应当取得著作权合法授权。其中，出版境外著作权人授权的网络游戏，须按本规定第二十七条办理审批手续。"},{"i":33,"n":"第三十三条","txt":"网络出版服务单位发现其出版的网络出版物含有本规定第二十四条、第二十五条所列内容的，应当立即删除，保存有关记录，并向所在地县级以上出版行政主管部门报告。"},{"i":34,"n":"第三十四条","txt":"网络出版服务单位应记录所出版作品的内容及其时间、网址或者域名，记录应当保存60日，并在国家有关部门依法查询时，予以提供。"},{"i":35,"n":"第三十五条","txt":"网络出版服务单位须遵守国家统计规定，依法向出版行政主管部门报送统计资料。"},{"i":36,"n":"第三十六条","txt":"网络出版服务的监督管理实行属地管理原则。 各地出版行政主管部门应当加强对本行政区域内的网络出版服务单位及其出版活动的日常监督管理，履行下列职责： （一）对网络出版服务单位进行行业监管，对网络出版服务单位违反本规定的情况进行查处并报告上级出版行政主管部门； （二）对网络出版服务进行监管，对违反本规定的行为进行查处并报告上级出版行政主管部门； （三）对网络出版物内容和质量进行监管，定期组织内容审读和质量检查，并将结果向上级出版行政主管部门报告； （四）对网络出版从业人员进行管理，定期组织岗位、业务培训和考核； （五）配合上级出版行政主管部门、协调相关部门、指导下级出版行政主管部门开展工作。"},{"i":37,"n":"第三十七条","txt":"出版行政主管部门应当加强监管队伍和机构建设，采取必要的技术手段对网络出版服务进行管理。出版行政主管部门依法履行监督检查等执法职责时，网络出版服务单位应当予以配合，不得拒绝、阻挠。 各省、自治区、直辖市出版行政主管部门应当定期将本行政区域内的网络出版服务监督管理情况向国家新闻出版广电总局提交书面报告。"},{"i":38,"n":"第三十八条","txt":"网络出版服务单位实行年度核验制度，年度核验每年进行一次。省、自治区、直辖市出版行政主管部门负责对本行政区域内的网络出版服务单位实施年度核验并将有关情况报国家新闻出版广电总局备案。年度核验内容包括网络出版服务单位的设立条件、登记项目、出版经营情况、出版质量、遵守法律规范、内部管理情况等。"},{"i":39,"n":"第三十九条","txt":"年度核验按照以下程序进行： （一）网络出版服务单位提交年度自检报告，内容包括：本年度政策法律执行情况，奖惩情况，网站出版、管理、运营绩效情况，网络出版物目录，对年度核验期内的违法违规行为的整改情况，编辑出版人员培训管理情况等；并填写由国家新闻出版广电总局统一印制的《网络出版服务年度核验登记表》，与年度自检报告一并报所在地省、自治区、直辖市出版行政主管部门。 （二）省、自治区、直辖市出版行政主管部门对本行政区域内的网络出版服务单位的设立条件、登记项目、开展业务及执行法规等情况进行全面审核，并在收到网络出版服务单位的年度自检报告和《网络出版服务年度核验登记表》等年度核验材料的45日内完成全面审核查验工作。对符合年度核验要求的网络出版服务单位予以登记，并在其《网络出版服务许可证》上加盖年度核验章。 （三）省、自治区、直辖市出版行政主管部门应于完成全面审核查验工作的15日内将年度核验情况及有关"},{"i":40,"n":"第四十条","txt":"有下列情形之一的，暂缓年度核验： （一）正在停业整顿的； （二）违反出版法规规章，应予处罚的； （三）未按要求执行出版行政主管部门相关管理规定的； （四）内部管理混乱，无正当理由未开展实质性网络出版服务活动的； （五）存在侵犯著作权等其他违法嫌疑需要进一步核查的。 暂缓年度核验的期限由省、自治区、直辖市出版行政主管部门确定，报国家新闻出版广电总局备案，最长不得超过180日。暂缓年度核验期间，须停止网络出版服务。 暂缓核验期满，按本规定重新办理年度核验手续。"},{"i":41,"n":"第四十一条","txt":"已经不具备本规定第八条、第九条规定条件的，责令限期改正；逾期仍未改正的，不予通过年度核验，由国家新闻出版广电总局撤销《网络出版服务许可证》，所在地省、自治区、直辖市出版行政主管部门注销登记，并通知当地电信主管部门依法处理。"},{"i":42,"n":"第四十二条","txt":"省、自治区、直辖市出版行政主管部门可根据实际情况，对本行政区域内的年度核验事项进行调整，相关情况报国家新闻出版广电总局备案。"},{"i":43,"n":"第四十三条","txt":"省、自治区、直辖市出版行政主管部门可以向社会公布年度核验结果。"},{"i":44,"n":"第四十四条","txt":"从事网络出版服务的编辑出版等相关专业技术人员及其负责人应当符合国家关于编辑出版等相关专业技术人员职业资格管理的有关规定。 网络出版服务单位的法定代表人或主要负责人应按照有关规定参加出版行政主管部门组织的岗位培训，并取得国家新闻出版广电总局统一印制的《岗位培训合格证书》。未按规定参加岗位培训或培训后未取得《岗位培训合格证书》的，不得继续担任法定代表人或主要负责人。"},{"i":45,"n":"第四十五条","txt":"国家制定有关政策，保障、促进网络出版服务业的发展与繁荣。鼓励宣传科学真理、传播先进文化、倡导科学精神、塑造美好心灵、弘扬社会正气等有助于形成先进网络文化的网络出版服务，推动健康文化、优秀文化产品的数字化、网络化传播。 网络出版服务单位依法从事网络出版服务，任何组织和个人不得干扰、阻止和破坏。"},{"i":46,"n":"第四十六条","txt":"国家支持、鼓励下列优秀的、重点的网络出版物的出版： （一）对阐述、传播宪法确定的基本原则有重大作用的； （二）对弘扬社会主义核心价值观，进行爱国主义、集体主义、社会主义和民族团结教育以及弘扬社会公德、职业道德、家庭美德、个人品德有重要意义的； （三）对弘扬民族优秀文化，促进国际文化交流有重大作用的； （四）具有自主知识产权和优秀文化内涵的； （五）对推进文化创新，及时反映国内外新的科学文化成果有重大贡献的； （六）对促进公共文化服务有重大作用的； （七）专门以未成年人为对象、内容健康的或者其他有利于未成年人健康成长的； （八）其他具有重要思想价值、科学价值或者文化艺术价值的。"},{"i":47,"n":"第四十七条","txt":"对为发展、繁荣网络出版服务业作出重要贡献的单位和个人，按照国家有关规定给予奖励。"},{"i":48,"n":"第四十八条","txt":"国家保护网络出版物著作权人的合法权益。网络出版服务单位应当遵守《中华人民共和国著作权法》、《信息网络传播权保护条例》、《计算机软件保护条例》等著作权法律法规。"},{"i":49,"n":"第四十九条","txt":"对非法干扰、阻止和破坏网络出版物出版的行为，出版行政主管部门及其他有关部门，应当及时采取措施，予以制止。"},{"i":50,"n":"第五十条","txt":"网络出版服务单位违反本规定的，出版行政主管部门可以采取下列行政措施： （一）下达警示通知书； （二）通报批评、责令改正； （三）责令公开检讨； （四）责令删除违法内容。 警示通知书由国家新闻出版广电总局制定统一格式，由出版行政主管部门下达给相关网络出版服务单位。 本条所列的行政措施可以并用。"},{"i":51,"n":"第五十一条","txt":"未经批准，擅自从事网络出版服务，或者擅自上网出版网络游戏（含境外著作权人授权的网络游戏），根据《出版管理条例》第六十一条、《互联网信息服务管理办法》第十九条的规定，由出版行政主管部门、工商行政管理部门依照法定职权予以取缔，并由所在地省级电信主管部门依据有关部门的通知，按照《互联网信息服务管理办法》第十九条的规定给予责令关闭网站等处罚；已经触犯刑法的，依法追究刑事责任；尚不够刑事处罚的，删除全部相关网络出版物，没收违法所得和从事违法出版活动的主要设备、专用工具，违法经营额1万元以上的，并处违法经营额5倍以上10倍以下的罚款；违法经营额不足1万元的，可以处5万元以下的罚款；侵犯他人合法权益的，依法承担民事责任。"},{"i":52,"n":"第五十二条","txt":"出版、传播含有本规定第二十四条、第二十五条禁止内容的网络出版物的，根据《出版管理条例》第六十二条、《互联网信息服务管理办法》第二十条的规定，由出版行政主管部门责令删除相关内容并限期改正，没收违法所得，违法经营额1万元以上的，并处违法经营额5倍以上10倍以下罚款；违法经营额不足1万元的，可以处5万元以下罚款；情节严重的，责令限期停业整顿或者由国家新闻出版广电总局吊销《网络出版服务许可证》，由电信主管部门依据出版行政主管部门的通知吊销其电信业务经营许可或者责令关闭网站；构成犯罪的，依法追究刑事责任。 为从事本条第一款行为的网络出版服务单位提供人工干预搜索排名、广告、推广等相关服务的，由出版行政主管部门责令其停止提供相关服务。"},{"i":53,"n":"第五十三条","txt":"违反本规定第二十一条的，根据《出版管理条例》第六十六条的规定，由出版行政主管部门责令停止违法行为，给予警告，没收违法所得，违法经营额1万元以上的，并处违法经营额5倍以上10倍以下的罚款；违法经营额不足1万元的，可以处5万元以下的罚款；情节严重的，责令限期停业整顿或者由国家新闻出版广电总局吊销《网络出版服务许可证》。"},{"i":54,"n":"第五十四条","txt":"有下列行为之一的，根据《出版管理条例》第六十七条的规定，由出版行政主管部门责令改正，给予警告；情节严重的，责令限期停业整顿或者由国家新闻出版广电总局吊销《网络出版服务许可证》： （一）网络出版服务单位变更《网络出版服务许可证》登记事项、资本结构，超出批准的服务范围从事网络出版服务，合并或者分立，设立分支机构，未依据本规定办理审批手续的； （二）网络出版服务单位未按规定出版涉及重大选题出版物的； （三）网络出版服务单位擅自中止网络出版服务超过180日的； （四）网络出版物质量不符合有关规定和标准的。"},{"i":55,"n":"第五十五条","txt":"违反本规定第三十四条的，根据《互联网信息服务管理办法》第二十一条的规定，由省级电信主管部门责令改正；情节严重的，责令停业整顿或者暂时关闭网站。"},{"i":56,"n":"第五十六条","txt":"网络出版服务单位未依法向出版行政主管部门报送统计资料的，依据《新闻出版统计管理办法》处罚。"},{"i":57,"n":"第五十七条","txt":"网络出版服务单位违反本规定第二章规定，以欺骗或者贿赂等不正当手段取得许可的，由国家新闻出版广电总局撤销其相应许可。"},{"i":58,"n":"第五十八条","txt":"有下列行为之一的，由出版行政主管部门责令改正，予以警告，并处3万元以下罚款： （一）违反本规定第十条，擅自与境内外中外合资经营、中外合作经营和外资经营的企业进行涉及网络出版服务业务的合作的； （二）违反本规定第十九条，未标明有关许可信息或者未核验有关网站的《网络出版服务许可证》的； （三）违反本规定第二十三条，未按规定实行编辑责任制度等管理制度的； （四）违反本规定第三十一条，未按规定或标准配备应用有关系统、设备或未健全有关管理制度的； （五）未按本规定要求参加年度核验的； （六）违反本规定第四十四条，网络出版服务单位的法定代表人或主要负责人未取得《岗位培训合格证书》的； （七）违反出版行政主管部门关于网络出版其他管理规定的。"},{"i":59,"n":"第五十九条","txt":"网络出版服务单位违反本规定被处以吊销许可证行政处罚的，其法定代表人或者主要负责人自许可证被吊销之日起10年内不得担任网络出版服务单位的法定代表人或者主要负责人。 从事网络出版服务的编辑出版等相关专业技术人员及其负责人违反本规定，情节严重的，由原发证机关吊销其资格证书。"},{"i":60,"n":"第六十条","txt":"本规定所称出版物内容审核责任制度、责任编辑制度、责任校对制度等管理制度，参照《图书质量保障体系》的有关规定执行。"},{"i":61,"n":"第六十一条","txt":"本规定自2016年3月10日起施行。原国家新闻出版总署、信息产业部2002年6月27日颁布的《互联网出版管理暂行规定》同时废止。"}],"wangluoanquanshenchabanfa-4":[{"i":1,"n":"第一条","txt":"为了确保关键信息基础设施供应链安全，维护国家安全，依据《中华人民共和国国家安全法》《中华人民共和国网络安全法》，制定本办法。"},{"i":2,"n":"第二条","txt":"关键信息基础设施运营者（以下简称运营者）采购网络产品和服务，影响或可能影响国家安全的，应当按照本办法进行网络安全审查。"},{"i":3,"n":"第三条","txt":"网络安全审查坚持防范网络安全风险与促进先进技术应用相结合、过程公正透明与知识产权保护相结合、事前审查与持续监管相结合、企业承诺与社会监督相结合，从产品和服务安全性、可能带来的国家安全风险等方面进行审查。"},{"i":4,"n":"第四条","txt":"在中央网络安全和信息化委员会领导下，国家互联网信息办公室会同中华人民共和国国家发展和改革委员会、中华人民共和国工业和信息化部、中华人民共和国公安部、中华人民共和国国家安全部、中华人民共和国财政部、中华人民共和国商务部、中国人民银行、国家市场监督管理总局、国家广播电视总局、国家保密局、国家密码管理局建立国家网络安全审查工作机制。 网络安全审查办公室设在国家互联网信息办公室，负责制定网络安全审查相关制度规范，组织网络安全审查。"},{"i":5,"n":"第五条","txt":"运营者采购网络产品和服务的，应当预判该产品和服务投入使用后可能带来的国家安全风险。影响或者可能影响国家安全的，应当向网络安全审查办公室申报网络安全审查。 关键信息基础设施保护工作部门可以制定本行业、本领域预判指南。"},{"i":6,"n":"第六条","txt":"对于申报网络安全审查的采购活动，运营者应通过采购文件、协议等要求产品和服务提供者配合网络安全审查，包括承诺不利用提供产品和服务的便利条件非法获取用户数据、非法控制和操纵用户设备，无正当理由不中断产品供应或必要的技术支持服务等。"},{"i":7,"n":"第七条","txt":"运营者申报网络安全审查，应当提交以下材料： （一）申报书； （二）关于影响或可能影响国家安全的分析报告； （三）采购文件、协议、拟签订的合同等； （四）网络安全审查工作需要的其他材料。"},{"i":8,"n":"第八条","txt":"网络安全审查办公室应当自收到审查申报材料起，10个工作日内确定是否需要审查并书面通知运营者。"},{"i":9,"n":"第九条","txt":"网络安全审查重点评估采购网络产品和服务可能带来的国家安全风险，主要考虑以下因素： （一）产品和服务使用后带来的关键信息基础设施被非法控制、遭受干扰或破坏，以及重要数据被窃取、泄露、毁损的风险； （二）产品和服务供应中断对关键信息基础设施业务连续性的危害； （三）产品和服务的安全性、开放性、透明性、来源的多样性，供应渠道的可靠性以及因为政治、外交、贸易等因素导致供应中断的风险； （四）产品和服务提供者遵守中国法律、行政法规、部门规章情况； （五）其他可能危害关键信息基础设施安全和国家安全的因素。"},{"i":10,"n":"第十条","txt":"网络安全审查办公室认为需要开展网络安全审查的，应当自向运营者发出书面通知之日起30个工作日内完成初步审查，包括形成审查结论建议和将审查结论建议发送网络安全审查工作机制成员单位、相关关键信息基础设施保护工作部门征求意见；情况复杂的，可以延长15个工作日。"},{"i":11,"n":"第十一条","txt":"网络安全审查工作机制成员单位和相关关键信息基础设施保护工作部门应当自收到审查结论建议之日起15个工作日内书面回复意见。 网络安全审查工作机制成员单位、相关关键信息基础设施保护工作部门意见一致的，网络安全审查办公室以书面形式将审查结论通知运营者；意见不一致的，按照特别审查程序处理，并通知运营者。"},{"i":12,"n":"第十二条","txt":"按照特别审查程序处理的，网络安全审查办公室应当听取相关部门和单位意见，进行深入分析评估，再次形成审查结论建议，并征求网络安全审查工作机制成员单位和相关关键信息基础设施保护工作部门意见，按程序报中央网络安全和信息化委员会批准后，形成审查结论并书面通知运营者。"},{"i":13,"n":"第十三条","txt":"特别审查程序一般应当在45个工作日内完成，情况复杂的可以适当延长。"},{"i":14,"n":"第十四条","txt":"网络安全审查办公室要求提供补充材料的，运营者、产品和服务提供者应当予以配合。提交补充材料的时间不计入审查时间。"},{"i":15,"n":"第十五条","txt":"网络安全审查工作机制成员单位认为影响或可能影响国家安全的网络产品和服务，由网络安全审查办公室按程序报中央网络安全和信息化委员会批准后，依照本办法的规定进行审查。"},{"i":16,"n":"第十六条","txt":"参与网络安全审查的相关机构和人员应严格保护企业商业秘密和知识产权，对运营者、产品和服务提供者提交的未公开材料，以及审查工作中获悉的其他未公开信息承担保密义务；未经信息提供方同意，不得向无关方披露或用于审查以外的目的。"},{"i":17,"n":"第十七条","txt":"运营者或网络产品和服务提供者认为审查人员有失客观公正，或未能对审查工作中获悉的信息承担保密义务的，可以向网络安全审查办公室或者有关部门举报。"},{"i":18,"n":"第十八条","txt":"运营者应当督促产品和服务提供者履行网络安全审查中作出的承诺。 网络安全审查办公室通过接受举报等形式加强事前事中事后监督。"},{"i":19,"n":"第十九条","txt":"运营者违反本办法规定的，依照《中华人民共和国网络安全法》第六十五条的规定处理。"},{"i":20,"n":"第二十条","txt":"本办法中关键信息基础设施运营者是指经关键信息基础设施保护工作部门认定的运营者。 本办法所称网络产品和服务主要指核心网络设备、高性能计算机和服务器、大容量存储设备、大型数据库和应用软件、网络安全设备、云计算服务，以及其他对关键信息基础设施安全有重要影响的网络产品和服务。"},{"i":21,"n":"第二十一条","txt":"涉及国家秘密信息的，依照国家有关保密规定执行。"},{"i":22,"n":"第二十二条","txt":"本办法自2020年6月1日起实施，《网络产品和服务安全审查办法（试行）》同时废止。"}],"wangluoanquanshenchabanfa":[{"i":1,"n":"第一条","txt":"为了确保关键信息基础设施供应链安全，保障网络安全和数据安全，维护国家安全，根据《中华人民共和国国家安全法》、《中华人民共和国网络安全法》、《中华人民共和国数据安全法》、《关键信息基础设施安全保护条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"关键信息基础设施运营者采购网络产品和服务，网络平台运营者开展数据处理活动，影响或者可能影响国家安全的，应当按照本办法进行网络安全审查。 前款规定的关键信息基础设施运营者、网络平台运营者统称为当事人。"},{"i":3,"n":"第三条","txt":"网络安全审查坚持防范网络安全风险与促进先进技术应用相结合、过程公正透明与知识产权保护相结合、事前审查与持续监管相结合、企业承诺与社会监督相结合，从产品和服务以及数据处理活动安全性、可能带来的国家安全风险等方面进行审查。"},{"i":4,"n":"第四条","txt":"在中央网络安全和信息化委员会领导下，国家互联网信息办公室会同中华人民共和国国家发展和改革委员会、中华人民共和国工业和信息化部、中华人民共和国公安部、中华人民共和国国家安全部、中华人民共和国财政部、中华人民共和国商务部、中国人民银行、国家市场监督管理总局、国家广播电视总局、中国证券监督管理委员会、国家保密局、国家密码管理局建立国家网络安全审查工作机制。 网络安全审查办公室设在国家互联网信息办公室，负责制定网络安全审查相关制度规范，组织网络安全审查。"},{"i":5,"n":"第五条","txt":"关键信息基础设施运营者采购网络产品和服务的，应当预判该产品和服务投入使用后可能带来的国家安全风险。影响或者可能影响国家安全的，应当向网络安全审查办公室申报网络安全审查。 关键信息基础设施安全保护工作部门可以制定本行业、本领域预判指南。"},{"i":6,"n":"第六条","txt":"对于申报网络安全审查的采购活动，关键信息基础设施运营者应当通过采购文件、协议等要求产品和服务提供者配合网络安全审查，包括承诺不利用提供产品和服务的便利条件非法获取用户数据、非法控制和操纵用户设备，无正当理由不中断产品供应或者必要的技术支持服务等。"},{"i":7,"n":"第七条","txt":"掌握超过100万用户个人信息的网络平台运营者赴国外上市，必须向网络安全审查办公室申报网络安全审查。"},{"i":8,"n":"第八条","txt":"当事人申报网络安全审查，应当提交以下材料： （一）申报书； （二）关于影响或者可能影响国家安全的分析报告； （三）采购文件、协议、拟签订的合同或者拟提交的首次公开募股（IPO）等上市申请文件； （四）网络安全审查工作需要的其他材料。"},{"i":9,"n":"第九条","txt":"网络安全审查办公室应当自收到符合本办法第八条规定的审查申报材料起10个工作日内，确定是否需要审查并书面通知当事人。"},{"i":10,"n":"第十条","txt":"网络安全审查重点评估相关对象或者情形的以下国家安全风险因素： （一）产品和服务使用后带来的关键信息基础设施被非法控制、遭受干扰或者破坏的风险； （二）产品和服务供应中断对关键信息基础设施业务连续性的危害； （三）产品和服务的安全性、开放性、透明性、来源的多样性，供应渠道的可靠性以及因为政治、外交、贸易等因素导致供应中断的风险； （四）产品和服务提供者遵守中国法律、行政法规、部门规章情况； （五）核心数据、重要数据或者大量个人信息被窃取、泄露、毁损以及非法利用、非法出境的风险； （六）上市存在关键信息基础设施、核心数据、重要数据或者大量个人信息被外国政府影响、控制、恶意利用的风险，以及网络信息安全风险； （七）其他可能危害关键信息基础设施安全、网络安全和数据安全的因素。"},{"i":11,"n":"第十一条","txt":"网络安全审查办公室认为需要开展网络安全审查的，应当自向当事人发出书面通知之日起30个工作日内完成初步审查，包括形成审查结论建议和将审查结论建议发送网络安全审查工作机制成员单位、相关部门征求意见；情况复杂的，可以延长15个工作日。"},{"i":12,"n":"第十二条","txt":"网络安全审查工作机制成员单位和相关部门应当自收到审查结论建议之日起15个工作日内书面回复意见。 网络安全审查工作机制成员单位、相关部门意见一致的，网络安全审查办公室以书面形式将审查结论通知当事人；意见不一致的，按照特别审查程序处理，并通知当事人。"},{"i":13,"n":"第十三条","txt":"按照特别审查程序处理的，网络安全审查办公室应当听取相关单位和部门意见，进行深入分析评估，再次形成审查结论建议，并征求网络安全审查工作机制成员单位和相关部门意见，按程序报中央网络安全和信息化委员会批准后，形成审查结论并书面通知当事人。"},{"i":14,"n":"第十四条","txt":"特别审查程序一般应当在90个工作日内完成，情况复杂的可以延长。"},{"i":15,"n":"第十五条","txt":"网络安全审查办公室要求提供补充材料的，当事人、产品和服务提供者应当予以配合。提交补充材料的时间不计入审查时间。"},{"i":16,"n":"第十六条","txt":"网络安全审查工作机制成员单位认为影响或者可能影响国家安全的网络产品和服务以及数据处理活动，由网络安全审查办公室按程序报中央网络安全和信息化委员会批准后，依照本办法的规定进行审查。 为了防范风险，当事人应当在审查期间按照网络安全审查要求采取预防和消减风险的措施。"},{"i":17,"n":"第十七条","txt":"参与网络安全审查的相关机构和人员应当严格保护知识产权，对在审查工作中知悉的商业秘密、个人信息，当事人、产品和服务提供者提交的未公开材料，以及其他未公开信息承担保密义务；未经信息提供方同意，不得向无关方披露或者用于审查以外的目的。"},{"i":18,"n":"第十八条","txt":"当事人或者网络产品和服务提供者认为审查人员有失客观公正，或者未能对审查工作中知悉的信息承担保密义务的，可以向网络安全审查办公室或者有关部门举报。"},{"i":19,"n":"第十九条","txt":"当事人应当督促产品和服务提供者履行网络安全审查中作出的承诺。 网络安全审查办公室通过接受举报等形式加强事前事中事后监督。"},{"i":20,"n":"第二十条","txt":"当事人违反本办法规定的，依照《中华人民共和国网络安全法》、《中华人民共和国数据安全法》的规定处理。"},{"i":21,"n":"第二十一条","txt":"本办法所称网络产品和服务主要指核心网络设备、重要通信产品、高性能计算机和服务器、大容量存储设备、大型数据库和应用软件、网络安全设备、云计算服务，以及其他对关键信息基础设施安全、网络安全和数据安全有重要影响的网络产品和服务。"},{"i":22,"n":"第二十二条","txt":"涉及国家秘密信息的，依照国家有关保密规定执行。 国家对数据安全审查、外商投资安全审查另有规定的，应当同时符合其规定。"},{"i":23,"n":"第二十三条","txt":"本办法自2022年2月15日起施行。2020年4月13日公布的《网络安全审查办法》（国家互联网信息办公室、国家发展和改革委员会、工业和信息化部、公安部、国家安全部、财政部、商务部、中国人民银行、国家市场监督管理总局、国家广播电视总局、国家保密局、国家密码管理局令第6号）同时废止。"}],"wangluobaolixinxizhiliguiding":[{"i":1,"n":"第一条","txt":"为了治理网络暴力信息，营造良好网络生态，保障公民合法权益，维护社会公共利益，根据《中华人民共和国网络安全法》、《中华人民共和国个人信息保护法》、《中华人民共和国治安管理处罚法》、《互联网信息服务管理办法》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内的网络暴力信息治理活动，适用本规定。"},{"i":3,"n":"第三条","txt":"网络暴力信息治理坚持源头防范、防控结合、标本兼治、协同共治的原则。"},{"i":4,"n":"第四条","txt":"国家网信部门负责统筹协调全国网络暴力信息治理和相关监督管理工作。国务院公安、文化和旅游、广播电视等有关部门依据各自职责开展网络暴力信息的监督管理工作。 地方网信部门负责统筹协调本行政区域内网络暴力信息治理和相关监督管理工作。地方公安、文化和旅游、广播电视等有关部门依据各自职责开展本行政区域内网络暴力信息的监督管理工作。"},{"i":5,"n":"第五条","txt":"鼓励网络相关行业组织加强行业自律，开展网络暴力信息治理普法宣传，督促指导网络信息服务提供者加强网络暴力信息治理并接受社会监督，为遭受网络暴力信息侵害的用户提供帮扶救助等支持。"},{"i":6,"n":"第六条","txt":"网络信息服务提供者和用户应当坚持社会主义核心价值观，遵守法律法规，尊重社会公德和伦理道德，促进形成积极健康、向上向善的网络文化，维护良好网络生态。"},{"i":7,"n":"第七条","txt":"网络信息服务提供者应当履行网络信息内容管理主体责任，建立完善网络暴力信息治理机制，健全用户注册、账号管理、个人信息保护、信息发布审核、监测预警、识别处置等制度。"},{"i":8,"n":"第八条","txt":"网络信息服务提供者为用户提供信息发布、即时通讯等服务的，应当依法对用户进行真实身份信息认证。用户不提供真实身份信息的，网络信息服务提供者不得为其提供相关服务。 网络信息服务提供者应当加强用户账号信息管理，为遭受网络暴力信息侵害的相关主体提供账号信息认证协助，防范和制止假冒、仿冒、恶意关联相关主体进行违规注册或者发布信息。"},{"i":9,"n":"第九条","txt":"网络信息服务提供者应当制定和公开管理规则、平台公约，与用户签订服务协议，明确网络暴力信息治理相关权利义务，并依法依约履行治理责任。"},{"i":10,"n":"第十条","txt":"任何组织和个人不得制作、复制、发布、传播涉网络暴力违法信息，应当防范和抵制制作、复制、发布、传播涉网络暴力不良信息。 任何组织和个人不得利用网络暴力事件实施蹭炒热度、推广引流等营销炒作行为，不得通过批量注册或者操纵用户账号等形式组织制作、复制、发布、传播网络暴力信息。 明知他人从事涉网络暴力信息违法犯罪活动的，任何组织和个人不得为其提供数据、技术、流量、资金等支持和协助。"},{"i":11,"n":"第十一条","txt":"网络信息服务提供者应当定期发布网络暴力信息治理公告，并将相关工作情况列入网络信息内容生态治理工作年度报告。"},{"i":12,"n":"第十二条","txt":"网络信息服务提供者应当在国家网信部门和国务院有关部门指导下细化网络暴力信息分类标准规则，建立健全网络暴力信息特征库和典型案例样本库，采用人工智能、大数据等技术手段和人工审核相结合的方式加强对网络暴力信息的识别监测。"},{"i":13,"n":"第十三条","txt":"网络信息服务提供者应当建立健全网络暴力信息预警模型，综合事件类别、针对主体、参与人数、信息内容、发布频次、环节场景、举报投诉等因素，及时发现预警网络暴力信息风险。 网络信息服务提供者发现存在网络暴力信息风险的，应当及时回应社会关切，引导用户文明互动、理性表达，并对异常账号及时采取真实身份信息动态核验、弹窗提示、违规警示、限制流量等措施；发现相关信息内容浏览、搜索、评论、举报量显著增长等情形的，还应当及时向有关部门报告。"},{"i":14,"n":"第十四条","txt":"网络信息服务提供者应当建立健全用户账号信用管理体系，将涉网络暴力信息违法违规情形记入用户信用记录，依法依约降低账号信用等级或者列入黑名单，并据以限制账号功能或者停止提供相关服务。"},{"i":15,"n":"第十五条","txt":"网络信息服务提供者发现涉网络暴力违法信息的，或者在其服务的醒目位置、易引起用户关注的重点环节发现涉网络暴力不良信息的，应当立即停止传输，采取删除、屏蔽、断开链接等处置措施，保存有关记录，向有关部门报告。发现涉嫌违法犯罪的，应当及时向公安机关报案，并提供相关线索，依法配合开展侦查、调查和处置等工作。"},{"i":16,"n":"第十六条","txt":"互联网新闻信息服务提供者应当坚持正确政治方向、舆论导向、价值取向，加强网络暴力信息治理的公益宣传。 互联网新闻信息服务提供者不得通过夸大事实、过度渲染、片面报道等方式采编发布、转载涉网络暴力新闻信息。对互联网新闻信息提供跟帖评论服务的，应当实行先审后发。 互联网新闻信息服务提供者采编发布、转载涉网络暴力新闻信息不真实或者不公正的，应当立即公开更正，消除影响。"},{"i":17,"n":"第十七条","txt":"网络信息服务提供者应当加强网络视听节目、网络表演等服务内容的管理，发现含有网络暴力信息的网络视听节目、网络表演等服务的，应当及时删除信息或者停止提供相关服务；应当加强对网络直播、短视频等服务的内容审核，及时阻断含有网络暴力信息的网络直播，处置含有网络暴力信息的短视频。"},{"i":18,"n":"第十八条","txt":"网络信息服务提供者应当加强对跟帖评论信息内容的管理，对以评论、回复、留言、弹幕、点赞等方式制作、复制、发布、传播网络暴力信息的，应当及时采取删除、屏蔽、关闭评论、停止提供相关服务等处置措施。"},{"i":19,"n":"第十九条","txt":"网络信息服务提供者应当加强对网络论坛社区和网络群组的管理，禁止用户在版块、词条、超话、群组等环节制作、复制、发布、传播网络暴力信息，禁止以匿名投稿、隔空喊话等方式创建含有网络暴力信息的论坛社区和群组账号。 网络论坛社区、网络群组的建立者和管理者应当履行管理责任，发现用户制作、复制、发布、传播网络暴力信息的，应当依法依约采取限制发言、移出群组等管理措施。"},{"i":20,"n":"第二十条","txt":"公众账号生产运营者应当建立健全发布推广、互动评论等全过程信息内容安全审核机制，发现账号跟帖评论等环节存在网络暴力信息的，应当及时采取举报、处置等措施。"},{"i":21,"n":"第二十一条","txt":"对违反本规定第十条的用户，网络信息服务提供者应当依法依约采取警示、删除信息、限制账号功能、关闭账号等处置措施，并保存相关记录；对组织、煽动、多次发布网络暴力信息的，网络信息服务提供者还应当依法依约采取列入黑名单、禁止重新注册等处置措施。 对借网络暴力事件实施营销炒作等行为的，除前款规定外，还应当依法依约采取清理订阅关注账号、暂停营利权限等处置措施。"},{"i":22,"n":"第二十二条","txt":"对组织、煽动制作、复制、发布、传播网络暴力信息的网络信息内容多渠道分发服务机构，网络信息服务提供者应当依法依约对该机构及其管理的账号采取警示、暂停营利权限、限制提供服务、入驻清退等处置措施。"},{"i":23,"n":"第二十三条","txt":"网络信息服务提供者应当建立健全网络暴力信息防护功能，提供便利用户设置屏蔽陌生用户或者特定用户、本人发布信息可见范围、禁止转载或者评论本人发布信息等网络暴力信息防护选项。 网络信息服务提供者应当完善私信规则，提供便利用户设置仅接收好友私信或者拒绝接收所有私信等网络暴力信息防护选项，鼓励提供智能屏蔽私信或者自定义私信屏蔽词等功能。"},{"i":24,"n":"第二十四条","txt":"网络信息服务提供者发现用户面临网络暴力信息风险的，应当及时通过显著方式提示用户，告知用户可以采取的防护措施。 网络信息服务提供者发现网络暴力信息风险涉及以下情形的，还应当为用户提供网络暴力信息防护指导和保护救助服务，协助启动防护措施，并向网信、公安等有关部门报告： （一）网络暴力信息侵害未成年人、老年人、残疾人等用户合法权益的； （二）网络暴力信息侵犯用户个人隐私的； （三）若不及时采取措施，可能造成用户人身、财产损害等严重后果的其他情形。"},{"i":25,"n":"第二十五条","txt":"网络信息服务提供者发现、处置网络暴力信息的，应当及时保存信息内容、浏览评论转发数量等数据。网络信息服务提供者应当向用户提供网络暴力信息快捷取证等功能，依法依约为用户维权提供便利。 公安、网信等有关部门依法调取证据的，网络信息服务提供者应当及时提供必要的技术支持和协助。"},{"i":26,"n":"第二十六条","txt":"网络信息服务提供者应当自觉接受社会监督，优化投诉、举报程序，在服务显著位置设置专门的网络暴力信息快捷投诉、举报入口，公布处理流程，及时受理、处理公众投诉、举报并反馈处理结果。 网络信息服务提供者应当结合投诉、举报内容以及相关证明材料及时研判。对属于网络暴力信息的投诉、举报，应当依法处理并反馈结果；对因证明材料不充分难以准确判断的，应当及时告知用户补充证明材料；对不属于网络暴力信息的投诉、举报，应当按照其他类型投诉、举报的受理要求予以处理并反馈结果。"},{"i":27,"n":"第二十七条","txt":"网络信息服务提供者应当优先处理涉未成年人网络暴力信息的投诉、举报。发现涉及侵害未成年人用户合法权益的网络暴力信息风险的，应当按照法律法规和本规定要求及时采取措施，提供相应保护救助服务，并向有关部门报告。 网络信息服务提供者应当设置便利未成年人及其监护人行使通知删除网络暴力信息权利的功能、渠道，接到相关通知后，应当及时采取删除、屏蔽、断开链接等必要的措施，防止信息扩散。"},{"i":28,"n":"第二十八条","txt":"网信部门会同公安、文化和旅游、广播电视等有关部门依法对网络信息服务提供者的网络暴力信息治理情况进行监督检查。 网络信息服务提供者对网信部门和有关部门依法实施的监督检查应当予以配合。"},{"i":29,"n":"第二十九条","txt":"网信部门会同公安、文化和旅游、广播电视等有关部门建立健全信息共享、会商通报、取证调证、案件督办等工作机制，协同治理网络暴力信息。 公安机关对于网信、文化和旅游、广播电视等部门移送的涉网络暴力信息违法犯罪线索，应当及时进行审查，并对符合立案条件的及时立案侦查、调查。"},{"i":30,"n":"第三十条","txt":"违反本规定的，依照《中华人民共和国网络安全法》、《中华人民共和国个人信息保护法》、《中华人民共和国治安管理处罚法》、《互联网信息服务管理办法》等法律、行政法规的规定予以处罚。 法律、行政法规没有规定的，由网信、公安、文化和旅游、广播电视等有关部门依据职责给予警告、通报批评，责令限期改正，可以并处一万元以上十万元以下罚款；涉及危害公民生命健康安全且有严重后果的，并处十万元以上二十万元以下罚款。 对组织、煽动制作、复制、发布、传播网络暴力信息或者利用网络暴力事件实施恶意营销炒作等行为的组织和个人，应当依法从重处罚。"},{"i":31,"n":"第三十一条","txt":"违反本规定，给他人造成损害的，依法承担民事责任；构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":32,"n":"第三十二条","txt":"本规定所称网络暴力信息，是指通过网络以文本、图像、音频、视频等形式对个人集中发布的，含有侮辱谩骂、造谣诽谤、煽动仇恨、威逼胁迫、侵犯隐私，以及影响身心健康的指责嘲讽、贬低歧视等内容的违法和不良信息。"},{"i":33,"n":"第三十三条","txt":"依法通过网络检举、揭发他人违法犯罪，或者依法实施舆论监督的，不适用本规定。"},{"i":34,"n":"第三十四条","txt":"本规定自2024年8月1日起施行。"}],"guifanhulianwangxinxifuwushichangzhixuruoganguidin311944-2":[{"i":1,"n":"第一条","txt":"为了规范互联网信息服务市场秩序，保护互联网信息服务提供者和用户的合法权益，促进互联网行业的健康发展，根据《中华人民共和国电信条例》、《互联网信息服务管理办法》等法律、行政法规的规定，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事互联网信息服务及与互联网信息服务有关的活动，应当遵守本规定。"},{"i":3,"n":"第三条","txt":"工业和信息化部和各省、自治区、直辖市通信管理局（以下统称“电信管理机构”）依法对互联网信息服务活动实施监督管理。"},{"i":4,"n":"第四条","txt":"互联网信息服务提供者应当遵循平等、自愿、公平、诚信的原则提供服务。"},{"i":5,"n":"第五条","txt":"互联网信息服务提供者不得实施下列侵犯其他互联网信息服务提供者合法权益的行为： （一）恶意干扰用户终端上其他互联网信息服务提供者的服务，或者恶意干扰与互联网信息服务相关的软件等产品（“与互联网信息服务相关的软件等产品”以下简称“产品”）的下载、安装、运行和升级； （二）捏造、散布虚假事实损害其他互联网信息服务提供者的合法权益，或者诋毁其他互联网信息服务提供者的服务或者产品； （三）恶意对其他互联网信息服务提供者的服务或者产品实施不兼容； （四）欺骗、误导或者强迫用户使用或者不使用其他互联网信息服务提供者的服务或者产品； （五）恶意修改或者欺骗、误导、强迫用户修改其他互联网信息服务提供者的服务或者产品参数； （六）其他违反国家法律规定，侵犯其他互联网信息服务提供者合法权益的行为。"},{"i":6,"n":"第六条","txt":"对互联网信息服务提供者的服务或者产品进行评测，应当客观公正。 评测方公开或者向用户提供评测结果的，应当同时提供评测实施者、评测方法、数据来源、用户原始评价、评测手段和评测环境等与评测活动相关的信息。评测结果应当真实准确，与评测活动相关的信息应当完整全面。被评测的服务或者产品与评测方的服务或者产品相同或者功能类似的，评测结果中不得含有评测方的主观评价。 被评测方对评测结果有异议的，可以自行或者委托第三方就评测结果进行再评测，评测方应当予以配合。 评测方不得利用评测结果，欺骗、误导、强迫用户对被评测方的服务或者产品作出处置。 本规定所称评测，是指提供平台供用户评价，或者以其他方式对互联网信息服务或者产品的性能等进行评价和测试。"},{"i":7,"n":"第七条","txt":"互联网信息服务提供者不得实施下列侵犯用户合法权益的行为： （一）无正当理由拒绝、拖延或者中止向用户提供互联网信息服务或者产品； （二）无正当理由限定用户使用或者不使用其指定的互联网信息服务或者产品； （三）以欺骗、误导或者强迫等方式向用户提供互联网信息服务或者产品； （四）提供的互联网信息服务或者产品与其向用户所作的宣传或者承诺不符； （五）擅自改变服务协议或者业务规程，降低服务质量或者加重用户责任； （六）与其他互联网信息服务提供者的服务或者产品不兼容时，未主动向用户提示和说明； （七）未经提示并由用户主动选择同意，修改用户浏览器配置或者其他设置； （八）其他违反国家法律规定，侵犯用户合法权益的行为。"},{"i":8,"n":"第八条","txt":"互联网信息服务提供者在用户终端上进行软件下载、安装、运行、升级、卸载等操作的，应当提供明确、完整的软件功能等信息，并事先征得用户同意。 互联网信息服务提供者不得实施下列行为： （一）欺骗、误导或者强迫用户下载、安装、运行、升级、卸载软件； （二）未提供与软件安装方式同等或者更便捷的卸载方式； （三）在未受其他软件影响和人为破坏的情况下，未经用户主动选择同意，软件卸载后有可执行代码或者其他不必要的文件驻留在用户终端。"},{"i":9,"n":"第九条","txt":"互联网信息服务终端软件捆绑其他软件的，应当以显著的方式提示用户，由用户主动选择是否安装或者使用，并提供独立的卸载或者关闭方式，不得附加不合理条件。"},{"i":10,"n":"第十条","txt":"互联网信息服务提供者在用户终端弹出广告或者其他与终端软件功能无关的信息窗口的，应当以显著的方式向用户提供关闭或者退出窗口的功能标识。"},{"i":11,"n":"第十一条","txt":"未经用户同意，互联网信息服务提供者不得收集与用户相关、能够单独或者与其他信息结合识别用户的信息（以下简称“用户个人信息”），不得将用户个人信息提供给他人，但是法律、行政法规另有规定的除外。 互联网信息服务提供者经用户同意收集用户个人信息的，应当明确告知用户收集和处理用户个人信息的方式、内容和用途，不得收集其提供服务所必需以外的信息，不得将用户个人信息用于其提供服务之外的目的。"},{"i":12,"n":"第十二条","txt":"互联网信息服务提供者应当妥善保管用户个人信息；保管的用户个人信息泄露或者可能泄露时，应当立即采取补救措施；造成或者可能造成严重后果的，应当立即向准予其互联网信息服务许可或者备案的电信管理机构报告，并配合相关部门进行的调查处理。"},{"i":13,"n":"第十三条","txt":"互联网信息服务提供者应当加强系统安全防护，依法维护用户上载信息的安全，保障用户对上载信息的使用、修改和删除。 互联网信息服务提供者不得有下列行为： （一）无正当理由擅自修改或者删除用户上载信息； （二）未经用户同意，向他人提供用户上载信息，但是法律、行政法规另有规定的除外； （三）擅自或者假借用户名义转移用户上载信息，或者欺骗、误导、强迫用户转移其上载信息； （四）其他危害用户上载信息安全的行为。"},{"i":14,"n":"第十四条","txt":"互联网信息服务提供者应当以显著的方式公布有效联系方式，接受用户及其他互联网信息服务提供者的投诉，并自接到投诉之日起十五日内作出答复。"},{"i":15,"n":"第十五条","txt":"互联网信息服务提供者认为其他互联网信息服务提供者实施违反本规定的行为，侵犯其合法权益并对用户权益造成或者可能造成重大影响的，应当立即向准予该其他互联网信息服务提供者互联网信息服务许可或者备案的电信管理机构报告。 电信管理机构应当对报告或者发现的可能违反本规定的行为的影响进行评估；影响特别重大的，相关省、自治区、直辖市通信管理局应当向工业和信息化部报告。电信管理机构在依据本规定作出处理决定前，可以要求互联网信息服务提供者暂停有关行为，互联网信息服务提供者应当执行。"},{"i":16,"n":"第十六条","txt":"互联网信息服务提供者违反本规定第五条、第七条或者第十三条的规定，由电信管理机构依据职权责令改正，处以警告，可以并处一万元以上三万元以下的罚款，向社会公告；其中，《中华人民共和国电信条例》或者《互联网信息服务管理办法》规定法律责任的，依照其规定处理。"},{"i":17,"n":"第十七条","txt":"评测方违反本规定第六条的规定的，由电信管理机构依据职权处以警告，可以并处一万元以上三万元以下的罚款，向社会公告。"},{"i":18,"n":"第十八条","txt":"互联网信息服务提供者违反本规定第八条、第九条、第十条、第十一条、第十二条或者第十四条的规定的，由电信管理机构依据职权处以警告，可以并处一万元以上三万元以下的罚款，向社会公告。"},{"i":19,"n":"第十九条","txt":"互联网信息服务提供者违反本规定第十五条规定，不执行电信管理机构暂停有关行为的要求的，由电信管理机构依据职权处以警告，向社会公告。"},{"i":20,"n":"第二十条","txt":"互联网信息服务提供者违反其他法律、行政法规规定的，依照其规定处理。"},{"i":21,"n":"第二十一条","txt":"本规定自2012年3月15日起施行。"}]};
